/* DAWAH X — ahmad, অধ্যায় 24 · খণ্ড 24 · 200 টি হাদিস · উৎস: https://github.com/elyabany/Hadith */
window.HADITH_DATA['ahmad'][24]=[[4601,4601,"","আমরা দুই বছর আগে একটা কুত্তার বাচ্চা, মান, মান-তাড়ি আর আমরা খেতে চাই আর ঈশ্বরের অনুগ্রহের অঙ্গীকার করতে চাই।","‏ ‏حَدَّثَنَا ‏ ‏مُعَاذٌ ‏ ‏حَدَّثَنَا ‏ ‏عِمْرَانُ بْنُ حُدَيْرٍ ‏ ‏عَنْ ‏ ‏يَزِيدَ بْنِ عُطَارِدٍ أَبِي الْبَزَرِى ‏ ‏قَالَ قَالَ ‏ ‏ابْنُ عُمَرَ ‏ ‏كُنَّا نَشْرَبُ وَنَحْنُ قِيَامٌ وَنَأْكُلُ وَنَحْنُ ‏ ‏نَسْعَى عَلَى عَهْدِ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏","","",""],[4602,4602,"","আমরা একটি ছেলে সঙ্গে একটি স্টান্টের কথা বলেছি একজন অধ্যাপকের সাথে খেলা করার জন্য যে বলেছে যে সে এক ছেলের কথা বলেছিল যে শীতের সময় শীতের সময় সে বলেছিল যে তার কাছে এক বছর বা তার জন্য কোন বছর বা অর্তক্ষস্তের জন্য তাকে জিজ্ঞাসা করা হয়েছে। মেয়ার বলেছিল আমি এক বছর নই সে বলেছে এটা মূল্যবান অথবা ঈশ্বরের দয়া বাদ দিয়ে দাও।","‏ ‏حَدَّثَنَا ‏ ‏مُعَاذٌ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ عَوْنٍ ‏ ‏عَنْ ‏ ‏مُسْلِمٍ ‏ ‏مَوْلًى ‏ ‏لِعَبْدِ الْقَيْسِ ‏ ‏قَالَ ‏ ‏مُعَاذٌ ‏ ‏كَانَ ‏ ‏شُعْبَةُ ‏ ‏يَقُولُ ‏ ‏الْقُرِّيِّ ‏ ‏قَالَ ‏ ‏قَالَ رَجُلٌ ‏ ‏لِابْنِ عُمَرَ ‏ ‏أَرَأَيْتَ ‏ ‏الْوِتْرَ ‏ ‏أَسُنَّةٌ هُوَ قَالَ مَا سُنَّةٌ ‏ ‏أَوْتَرَ ‏ ‏رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَأَوْتَرَ الْمُسْلِمُونَ قَالَ لَا أَسُنَّةٌ هُوَ قَالَ ‏ ‏مَهْ ‏ ‏أَوَتَعْقِلُ ‏ ‏أَوْتَرَ ‏ ‏رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَأَوْتَرَ ‏ ‏الْمُسْلِمُونَ ‏","","",""],[4603,4603,"","আমরা একটা ছেলের সাথে কথা বলেছি যে আমার সাথে কথা বলার ক্ষমতা ছিল। সে বলেছে, জেব্রার দয়ায় তার জেদে... ...তা তার নিজের বইয়ের যোগ্য একটা গর্তের ছেলে বলেছিল.","‏ ‏حَدَّثَنَا ‏ ‏مُعَاذٌ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ عَوْنٍ ‏ ‏عَنْ ‏ ‏نَافِعٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏قَالَ ‏ ‏نَادَى رَجُلٌ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَاذَا يَلْبَسُ ‏ ‏الْمُحْرِمُ ‏ ‏مِنْ الثِّيَابِ فَقَالَ ‏ ‏لَا تَلْبَسُوا الْقَمِيصَ وَلَا الْعِمَامَةَ وَلَا ‏ ‏الْبَرَانِسَ ‏ ‏وَلَا السَّرَاوِيلَاتِ وَلَا الْخِفَافَ إِلَّا أَنْ لَا تَكُونَ نِعَالٌ فَإِنْ لَمْ تَكُنْ نِعَالٌ فَخُفَّيْنِ دُونَ الْكَعْبَيْنِ وَلَا ثَوْبًا ‏ ‏مَسَّهُ ‏ ‏وَرْسٌ ‏ ‏قَالَ ‏ ‏ابْنُ عَوْنٍ ‏ ‏إِمَّا قَالَ مَصْبُوغٌ وَإِمَّا قَالَ ‏ ‏مَسَّهُ ‏ ‏وَرْسٌ ‏ ‏وَزَعْفَرَانٌ ‏ ‏قَالَ ‏ ‏ابْنُ عَوْنٍ ‏ ‏وَفِي كِتَابِ ‏ ‏نَافِعٍ ‏ ‏مَسَّهُ ‏","","",""],[4604,4604,"","আমি যখন বড়ো হয়েছিলাম, তখন বাবার সঙ্গে কথা বলেছিলাম, যখন আমি তার সঙ্গে কথা বলেছিলাম । ছায়া.","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ أَبِي عَدِيٍّ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ إِسْحَاقَ ‏ ‏قَالَ وَذَكَرْتُ ‏ ‏لِابْنِ شِهَابٍ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏سَالِمٌ ‏ ‏أَنَّ ‏ ‏عَبْدَ اللَّهِ بْنَ عُمَرَ ‏ ‏قَدْ كَانَ يَصْنَعُ ذَاكَ ‏ ‏ثُمَّ حَدَّثَتْهُ ‏ ‏صَفِيَّةُ بِنْتُ أَبِي عُبَيْدٍ ‏ ‏أَنَّ ‏ ‏عَائِشَةَ ‏ ‏حَدَّثَتْهَا ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ ‏ ‏يُرَخِّصُ لِلنِّسَاءِ فِي الْخُفَّيْنِ ‏","","",""],[4605,4605,"","আমার বাবা দুটো উপায়ের কথা বলেছেন, যে আমার ছেলেকে ধোঁকা দিতে বলেছিল।","‏ ‏حَدَّثَنِي ‏ ‏ابْنُ أَبِي عَدِيٍّ ‏ ‏عَنْ ‏ ‏سُلَيْمَانَ يَعْنِي التَّيْمِيَّ ‏ ‏عَنْ ‏ ‏طَاوُسٍ ‏ ‏قَالَ ‏ ‏سَأَلْتُ ‏ ‏ابْنَ عُمَرَ ‏ ‏أَنَهَى النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَنْ ‏ ‏نَبِيذِ ‏ ‏الْجَرِّ ‏ ‏قَالَ نَعَمْ ‏ ‏قَالَ ‏ ‏وَقَالَ ‏ ‏طَاوُسٌ ‏ ‏وَاللَّهِ إِنِّي سَمِعْتُهُ مِنْهُ ‏","","",""],[4606,4606,"","আমি বলতে চাই আমার মসজিদে প্রার্থনা হাতি থেকে পার্থক্য তৈরি করতে পারে।","‏ ‏حَدَّثَنَا ‏ ‏إِسْحَاقُ بْنُ يُوسُفَ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الْمَلِكِ ‏ ‏عَنْ ‏ ‏عَطَاءٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّهُ قَالَ ‏ ‏صَلَاةٌ فِي ‏ ‏مَسْجِدِي ‏ ‏هَذَا أَفْضَلُ مِنْ أَلْفِ صَلَاةٍ فِيمَا سِوَاهُ مِنْ الْمَسَاجِدِ إِلَّا ‏ ‏الْمَسْجِدَ الْحَرَامَ ‏ ‏فَهُوَ أَفْضَلُ ‏","","",""],[4607,4607,"","আমরা একজন দাসের কথা বলেছি যে কিনা ঈশ্বরের কাছে কথা বলেছে, যে কিনা ঈশ্বরের কাছে কথা বলেছে। তাই তিনি সবার আগে, প্রথম ও দ্বিতীয় জনের কাজ শেষ করে দিবেন।","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ عُبَيْدٍ ‏ ‏حَدَّثَنَا ‏ ‏عُبَيْدُ اللَّهِ ‏ ‏عَنْ ‏ ‏نَافِعٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِذَا جَمَعَ اللَّهُ الْأَوَّلِينَ وَالْآخِرِينَ يَوْمَ الْقِيَامَةِ رُفِعَ لِكُلِّ ‏ ‏غَادِرٍ ‏ ‏لِوَاءٌ ‏ ‏فَقِيلَ هَذِهِ ‏ ‏غَدْرَةُ ‏ ‏فُلَانِ بْنِ فُلَانٍ ‏","","",""],[4608,4608,"","আমরা তোমার জন্য কিছু দিয়েছি, লর্ডের অনুগ্রহে সূর্য তার কাছে হস্তান্তর করা হয়েছে না আর তোমার জন্য তাকে উদ্ধার করা হয়েছে।","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ عُبَيْدٍ ‏ ‏حَدَّثَنَا ‏ ‏عُبَيْدُ اللَّهِ ‏ ‏عَنْ ‏ ‏نَافِعٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏قَالَ ‏ ‏لَا ‏ ‏يَتَحَيَّنَنَّ ‏ ‏أَحَدُكُمْ طُلُوعَ الشَّمْسِ وَلَا غُرُوبَهَا فَإِنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ يَنْهَى عَنْ ذَلِكَ ‏","","",""],[4609,4609,"","আমরা একজন মহান প্রভুর সাথে কথা বলেছি যে শান্তির জন্য ঈশ্বরের কাছে পাঠানো হয়েছে আর তাকে দেয়া হয়েছে। আর আমি প্রার্থনা করতে চাইলে মানুষকে চুমু দেই। ঈশ্বর আমার সামনে এসেছেন। আমি কি বলেছি? আমি কি বলেছি, আমি কি বলেছি? আমি যদি বলি, আমি কি বলেছি, আমি কি করলাম? ( গীত.","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدٌ ‏ ‏حَدَّثَنَا ‏ ‏عُبَيْدُ اللَّهِ ‏ ‏عَنْ ‏ ‏نَافِعٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏رَأَى ‏ ‏نُخَامَةً ‏ ‏فِي قِبْلَةِ الْمَسْجِدِ ‏ ‏فَحَتَّهَا ‏ ‏ثُمَّ أَقْبَلَ عَلَى النَّاسِ فَقَالَ ‏ ‏إِذَا كَانَ أَحَدُكُمْ فِي الصَّلَاةِ فَلَا ‏ ‏يَتَنَخَّمْ ‏ ‏قِبَلَ وَجْهِهِ فَإِنَّ اللَّهَ تَعَالَى قِبَلَ وَجْهِ أَحَدِكُمْ إِذَا كَانَ فِي الصَّلَاةِ ‏","","",""],[4610,4610,"","আমরা একজন দাসের সাথে কথা বলেছি যে কিনা ঈশ্বরের দোহাই দিয়ে একটা ছেলের স্বপ্নের কথা বলত, যে কিনা শেষ হয়ে গেছে।","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ عُبَيْدٍ ‏ ‏حَدَّثَنَا ‏ ‏عُبَيْدِ اللَّهِ ‏ ‏عَنْ ‏ ‏نَافِعٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ ‏ ‏إِذَا أَدْخَلَ رِجْلَهُ فِي ‏ ‏الْغَرْزِ ‏ ‏وَاسْتَوَتْ ‏ ‏بِهِ نَاقَتُهُ قَائِمَةً ‏ ‏أَهَلَّ ‏ ‏مِنْ مَسْجِدِ ‏ ‏ذِي الْحُلَيْفَةِ ‏","","",""],[4611,4611,"","আমরা একজন মাস্টারের হাতে কথা বলেছি... ...যার সাথে ঈশ্বরের আচরণ করা হয়েছে, সে গাছ থেকে পড়ে যাওয়ার পথে ছিল আর সে তিনপাশে চলে যাচ্ছিল তৃতীয় রাউন্ড শেষ।","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ عُبَيْدٍ ‏ ‏حَدَّثَنَا ‏ ‏عُبَيْدُ اللَّهِ ‏ ‏عَنْ ‏ ‏نَافِعٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ ‏ ‏يَخْرُجُ ‏ ‏مِنْ طَرِيقِ الشَّجَرَةِ وَكَانَ يَدْخُلُ ‏ ‏مَكَّةَ ‏ ‏مِنْ ‏ ‏الثَّنِيَّةِ الْعُلْيَا ‏ ‏وَيَخْرُجُ مِنْ ‏ ‏الثَّنِيَّةِ السُّفْلَى ‏","","",""],[4612,4612,"","আমরা একজন দাসের সাথে কথা বলেছি যে কিনা ঈশ্বরের দোহাই দিয়ে এক ছেলের স্বপ্ন দেখে, যে কিনা অতিক্রম করেছে। প্রথম রুটির পশমটা ছিল তিন বার এবং চার বার হেঁটে হেঁটে হেঁটে হেঁটে।","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ عُبَيْدٍ ‏ ‏حَدَّثَنَا ‏ ‏عُبَيْدُ اللَّهِ ‏ ‏عَنْ ‏ ‏نَافِعٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ ‏ ‏إِذَا طَافَ ‏ ‏بِالْبَيْتِ ‏ ‏الطَّوَافَ الْأَوَّلَ ‏ ‏خَبَّ ‏ ‏ثَلَاثَةً وَمَشَى أَرْبَعَةً ‏","","",""],[4613,4613,"","আমরা একটা দাসের কথা বলেছিলাম, আমরা একটা ছেলের জন্য ঈশ্বরের ভালো কথা বলেছিলাম, যে এটা করতে রাজি হয়েছে বলে যে, আমাকে ছেড়ে দিতে হবে যখন বানরদের মত আমাকে গুড়িয়ে দিতে হবে তাকে একটা ভুল করতে বলে সে নিচে নেমে গেছে।","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ عُبَيْدٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏عُبَيْدُ اللَّهِ ‏ ‏عَنْ ‏ ‏نَافِعٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِنَّمَا ‏ ‏مَثَلُ الْقُرْآنِ مَثَلُ الْإِبِلِ ‏ ‏الْمُعَقَّلَةِ ‏ ‏إِنْ تَعَاهَدَهَا صَاحِبُهَا ‏ ‏بِعُقُلِهَا ‏ ‏أَمْسَكَهَا عَلَيْهِ وَإِنْ أَطْلَقَ ‏ ‏عُقُلَهَا ‏ ‏ذَهَبَتْ ‏","","",""],[4614,4614,"","আমরা আমাদের খবরের চেয়েও বেশি কথা বলেছি... ...ঈশ্বরের কাছে প্রার্থনা করে, তার কাছে একটা মই আসছে, আর চুপ করে আছে।","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ ‏ ‏أَخْبَرَنَا ‏ ‏يَحْيَى بْنُ سَعِيدٍ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ دِينَارٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏قَالَ ‏ ‏كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَأْتِي ‏ ‏قُبَاءً ‏ ‏رَاكِبًا وَمَاشِيًا ‏","","",""],[4615,4615,"","আমরা আমাদের থেকে অনেক কিছু বলেছি একটি দেবতা যার জন্ম হয়েছিল তার ব্যাপারে, যার জন্য সে জন্মগ্রহন করেছে.","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ ‏ ‏أَخْبَرَنَا ‏ ‏هِشَامٌ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ سِيرِينَ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏صَلَاةُ الْمَغْرِبِ وِتْرُ النَّهَارِ فَأَوْتِرُوا صَلَاةَ اللَّيْلِ ‏","","",""],[4616,4616,"","আমরা আমাদের গল্পের কথা অনেক বেশি বলেছি... ...যে ছেলে ঈশ্বরের উপর তৈরি হয়েছে, তার সম্পর্কে আমাদের কথা বলছি। রাতটা বেশ কয়েকবার হয়, তাই সকালে বা এক থেকে আরেককে ভয় পেয়ে থাকে।","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ ‏ ‏أَخْبَرَنَا ‏ ‏سُلَيْمَانُ التَّيْمِيُّ ‏ ‏عَنْ ‏ ‏طَاوُسٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏صَلَاةُ اللَّيْلِ مَثْنَى مَثْنَى فَإِذَا خِفْتَ الصُّبْحَ ‏ ‏فَأَوْتِرْ ‏ ‏بِوَاحِدَةٍ ‏","","",""],[4617,4617,"","আমরা আরও বলে দিয়েছি যে শয়তানের পোশাকে খুশি হতে আমরা একটা ছেলের হাত ধরে ধরার ব্যাপারে কথা বলেছি। আমার পক্ষে দু:খজনক অবস্থা, আমি প্রার্থনা করতে ব্যর্থ হয়েছি, আর আমি আমার পথ হারিয়েছি। আমার নিজের হাতে, তার লর্ডশিপ বিজয় করেছে... ...যেন তার দাস তাকে খুন করে ফেলতে ব্যর্থ হয়। সে ঘুমাচ্ছিলো যে ছেলেটি হলের ভেতরে ছিল, ভগবান তার জন্য প্রার্থনা করলো আর সে শেষ পর্যন্ত চলে আসবে।","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ ‏ ‏أَخْبَرَنَا ‏ ‏سَعِيدُ بْنُ زِيَادٍ الشَّيْبَانِيُّ ‏ ‏حَدَّثَنَا ‏ ‏زِيَادُ بْنُ صُبَيْحٍ الْحَنَفِيُّ ‏ ‏قَالَ ‏ ‏كُنْتُ قَائِمًا أُصَلِّي إِلَى الْبَيْتِ وَشَيْخٌ إِلَى جَانِبِي فَأَطَلْتُ الصَّلَاةَ فَوَضَعْتُ يَدَيَّ عَلَى خَصْرِي فَضَرَبَ الشَّيْخُ صَدْرِي بِيَدِهِ ضَرْبَةً لَا ‏ ‏يَأْلُو ‏ ‏فَقُلْتُ فِي نَفْسِي مَا ‏ ‏رَابَهُ ‏ ‏مِنِّي فَأَسْرَعْتُ ‏ ‏الِانْصِرَافَ فَإِذَا غُلَامٌ خَلْفَهُ قَاعِدٌ فَقُلْتُ مَنْ هَذَا الشَّيْخُ قَالَ هَذَا ‏ ‏عَبْدُ اللَّهِ بْنُ عُمَرَ ‏ ‏فَجَلَسْتُ حَتَّى انْصَرَفَ فَقُلْتُ ‏ ‏أَبَا عَبْدِ الرَّحْمَنِ ‏ ‏مَا ‏ ‏رَابَكَ ‏ ‏مِنِّي قَالَ أَنْتَ هُوَ قُلْتُ نَعَمْ قَالَ ‏ ‏ذَاكَ ‏ ‏الصَّلْبُ ‏ ‏فِي الصَّلَاةِ وَكَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَنْهَى عَنْهُ ‏","","",""],[4618,4618,"","আমরা আমাদের প্রিয় পুত্র হওয়ার সময় অনেক সময় পার করেছি কিন্তু ঈশ্বরের কাছে আমার বাবার একটা ছেলের স্বপ্ন আছে, যার ভালবাসার জন্য তার বাবার কাছে হয়ত ঈশ্বরের অনুগ্রহ ছিল। সকালে আমাদের জ্ঞানের মধ্যে সবচেয়ে বড় আর সবচেয়ে বড় হল আমরা জিতব... ...না হয় আমরা তোমাকে মেরে ফেলব.","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الْعَزِيزِ بْنُ عَبْدِ اللَّهِ بْنِ أَبِي سَلَمَةَ ‏ ‏عَنْ ‏ ‏عُمَرَ بْنِ حُسَيْنٍ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ أَبِي سَلَمَةَ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ عَبْدِ اللَّهِ بْنِ عُمَرَ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ عُمَرَ ‏ ‏قَالَ ‏ ‏كُنَّا مَعَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏صَبِيحَةَ ‏ ‏عَرَفَةَ ‏ ‏مِنَّا الْمُكَبِّرُ وَمِنَّا ‏ ‏الْمُهِلُّ ‏ ‏أَمَّا نَحْنُ فَنُكَبِّرُ قَالَ قُلْتُ الْعَجَبُ لَكُمْ كَيْفَ لَمْ تَسْأَلُوهُ كَيْفَ صَنَعَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏","","",""],[4619,4619,"","আমরা তাকে একটা সুযোগ দিয়েছি বলার জন্য সে এই আগুনটাকে মেরে ফেলবে আর তাকে মেরে ফেলবে যে নরকের মত মারা গেছে।","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ ‏ ‏أَخْبَرَنَا ‏ ‏حَجَّاجُ بْنُ أَرْطَاةَ ‏ ‏عَنْ ‏ ‏وَبَرَةَ ‏ ‏سَمِعْتُ ‏ ‏ابْنَ عُمَرَ ‏ ‏يَقُولُ ‏ ‏أَمَرَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بِقَتْلِ الذِّئْبِ لِلْمُحْرِمِ ‏ ‏يَعْنِي وَالْفَأْرَةَ وَالْغُرَابَ وَالْحِدَأَ ‏ ‏فَقِيلَ لَهُ فَالْحَيَّةُ وَالْعَقْرَبُ فَقَالَ قَدْ كَانَ يُقَالُ ذَاكَ ‏","","",""],[4620,4620,"","আমরা আমাদের মাস্টারদের চেয়েও ভাল কথা বলেছি... ...তার স্বপ্ন ছিল জীবন বাঁচার, আমি তাকে ধরতে বলেছিলাম, সে ছিল ঈশ্বর, তাকে এটা শেখানো হয়েছে, ওকে বলতে দাও, ওর সাথে যোগাযোগ না করতে।","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ ‏ ‏أَخْبَرَنَا ‏ ‏حَمَّادُ بْنُ سَلَمَةَ ‏ ‏عَنْ ‏ ‏عِكْرِمَةَ بْنِ خَالِدٍ الْمَخْزُومِيِّ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏أَنَّ رَجُلًا اشْتَرَى نَخْلًا قَدْ ‏ ‏أَبَّرَهَا ‏ ‏صَاحِبُهَا ‏ ‏فَخَاصَمَهُ ‏ ‏إِلَى النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَضَى رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّ الثَّمَرَةَ لِصَاحِبِهَا الَّذِي ‏ ‏أَبَّرَهَا ‏ ‏إِلَّا أَنْ يَشْتَرِطَ الْمُشْتَرِي ‏","","",""],[4621,4621,"","আমি বলেছিলাম যে আমি কখনো আমার কথা বলেছি না। কথা বলো, ঈশ্বর আমার মুখ থেকে কথা বলেন, আমি পরিষ্কার মনের কথা শিখি, তর্কের সিল্ক, যা থেকে আমি ঈর্ষার জন্য দুটোর মূল্যই পছন্দ করি।","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ ‏ ‏أَخْبَرَنَا ‏ ‏جَرِيرُ بْنُ حَازِمٍ ‏ ‏وَإِسْحَاقُ بْنُ عِيسَى ‏ ‏قَالَ ‏ ‏حَدَّثَنَا ‏ ‏جَرِيرُ بْنُ حَازِمٍ ‏ ‏عَنِ ‏ ‏الزُّبَيْرِ بْنِ الْخِرِّيتِ ‏ ‏عَنِ ‏ ‏الْحَسَنِ بْنِ هَادِيَةَ ‏ ‏قَالَ ‏ ‏لَقِيتُ ‏ ‏ابْنَ عُمَرَ ‏ ‏قَالَ ‏ ‏إِسْحَاقُ ‏ ‏فَقَالَ لِي مِمَّنْ أَنْتَ قُلْتُ مِنْ أَهْلِ ‏ ‏عُمَانَ ‏ ‏قَالَ مِنْ أَهْلِ ‏ ‏عُمَانَ ‏ ‏قُلْتُ نَعَمْ قَالَ أَفَلَا أُحَدِّثُكَ مَا سَمِعْتُ مِنْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قُلْتُ بَلَى ‏ ‏فَقَالَ ‏ ‏سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏إِنِّي لَأَعْلَمُ أَرْضًا يُقَالُ لَهَا ‏ ‏عُمَانُ ‏ ‏يَنْضَحُ ‏ ‏بِجَانِبِهَا ‏ ‏وَقَالَ ‏ ‏إِسْحَاقُ ‏ ‏بِنَاحِيَتِهَا ‏ ‏الْبَحْرُ الْحَجَّةُ مِنْهَا أَفْضَلُ مِنْ حَجَّتَيْنِ مِنْ غَيْرِهَا ‏","","",""],[4622,4622,"","আমরা একটা ছেলের কথা বলেছিলাম, যে আমাদের ঈশ্বরের কাছে প্রার্থনা করতে বলেছে, সে এই সমস্যার জন্য আমি যা করতে পারি তার থেকে বেশি টাকা দেবে, সে তাদের সবাইকে ঈশ্বরের জীবনের সাথে কাটাতে হবে। আমার বাবা একজন বাবা আমাদের বাবা। এমনকি জীবনের পরেও... ...আমি তার কল্পনার মাধ্যমে মুক্তি পেতে চেয়েছিলাম।","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ بْنُ هَارُونَ ‏ ‏أَخْبَرَنَا ‏ ‏الْحَجَّاجُ بْنُ أَرْطَاةَ ‏ ‏عَنْ ‏ ‏نَافِعٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏دَفَعَ ‏ ‏خَيْبَرَ ‏ ‏إِلَى أَهْلِهَا ‏ ‏بِالشَّطْرِ ‏ ‏فَلَمْ تَزَلْ مَعَهُمْ حَيَاةَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كُلَّهَا وَحَيَاةَ ‏ ‏أَبِي بَكْرٍ ‏ ‏وَحَيَاةَ ‏ ‏عُمَرَ ‏ ‏حَتَّى بَعَثَنِي ‏ ‏عُمَرُ ‏ ‏لِأُقَاسِمَهُمْ فَسَحَرُونِي ‏ ‏فَتَكَوَّعَتْ ‏ ‏يَدِي فَانْتَزَعَهَا ‏ ‏عُمَرُ ‏ ‏مِنْهُمْ ‏","","",""],[4623,4623,"","আমরা একটা ক্যারিয়ারের কথা বলেছি যেটা সে বিয়ার কিনতে চায়. তারা তাকে তার কাছে বিক্রি করে না, আর সে বলেছে যে তুমি আমার প্রভু ও তার প্রভুর জন্য বাস করো. আমি তাকে ছেড়ে দেব।","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ ‏ ‏عَنْ ‏ ‏هَمَّامٍ ‏ ‏عَنْ ‏ ‏نَافِعٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏أَنَّ ‏ ‏عَائِشَةَ ‏ ‏أَرَادَتْ أَنْ تَشْتَرِيَ ‏ ‏بَرِيرَةَ ‏ ‏فَأَبَى أَهْلُهَا أَنْ يَبِيعُوهَا إِلَّا أَنْ يَكُونَ لَهُمْ ‏ ‏وَلَاؤُهَا ‏ ‏فَذَكَرَتْ ذَلِكَ ‏ ‏عَائِشَةُ ‏ ‏لِلنَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏اشْتَرِيهَا فَأَعْتِقِيهَا فَإِنَّمَا ‏ ‏الْوَلَاءُ ‏ ‏لِمَنْ أَعْطَى الثَّمَنَ ‏","","",""],[4624,4624,"","আমরা গরু দিয়ে তৈরি গরুটার ব্যাপারে অনেক কথা বলেছি। ওকে রিং এ রাখতে হবে। আর আমাকে বলতে হবে, \"আমাকে আবার যেতে দাও\"","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ ‏ ‏أَخْبَرَنَا ‏ ‏جَرِيرُ بْنُ حَازِمٍ ‏ ‏حَدَّثَنَا ‏ ‏نَافِعٌ ‏ ‏قَالَ ‏ ‏وَجَدَ ‏ ‏ابْنُ عُمَرَ ‏ ‏الْقُرَّ ‏ ‏وَهُوَ ‏ ‏مُحْرِمٌ ‏ ‏فَقَالَ أَلْقِ عَلَيَّ ثَوْبًا فَأَلْقَيْتُ عَلَيْهِ ‏ ‏بُرْنُسًا ‏ ‏فَأَخَّرَهُ وَقَالَ ‏ ‏تُلْقِي عَلَيَّ ثَوْبًا قَدْ ‏ ‏نَهَى رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنْ يَلْبَسَهُ ‏ ‏الْمُحْرِمُ ‏","","",""],[4625,4625,"","তিনি যদি প্রথম সিনেমায় থাকতেন এবং তার জন্য প্রার্থনা করতেন, তা হলে তিনি হয়তো আমার পরিবর্তন করতেন । আমি তাদের হত্যা করবো তাদের মূল্যবান পাপের জন্য, ঈশ্বরের কাজ বেড়ে চলেছে আর সে জীবন যাপনে ছিল.","‏ ‏حَدَّثَنَا ‏ ‏مُعَاذٌ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ عَوْنٍ ‏ ‏قَالَ كَتَبْتُ إِلَى ‏ ‏نَافِعٍ ‏ ‏أَسْأَلُهُ هَلْ كَانَتْ الدَّعْوَةُ قَبْلَ الْقِتَالِ قَالَ فَكَتَبَ إِلَيَّ إِنَّ ذَاكَ كَانَ فِي أَوَّلِ الْإِسْلَامِ وَإِنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَدْ ‏ ‏أَغَارَ ‏ ‏عَلَى ‏ ‏بَنِي الْمُصْطَلِقِ ‏ ‏وَهُمْ ‏ ‏غَارُّونَ ‏ ‏وَأَنْعَامُهُمْ تُسْقَى عَلَى الْمَاءِ فَقَتَلَ مُقَاتِلَتَهُمْ ‏ ‏وَسَبَى ‏ ‏سَبْيَهُمْ ‏ ‏وَأَصَابَ يَوْمَئِذٍ ‏ ‏جُوَيْرِيَةَ ابْنَةَ الْحَارِثِ ‏ ‏وَحَدَّثَنِي ‏ ‏بِهَذَا الْحَدِيثِ ‏ ‏عَبْدُ اللَّهِ بْنُ عُمَرَ ‏ ‏وَكَانَ فِي ذَلِكَ الْجَيْشِ ‏","","",""],[4626,4626,"","আমরা হারুনের কাছে আবার ফিরে এসেছি, যে খবরে আমরা ঈশ্বরের পুত্র হতে পেরে ক্লান্ত। ( আদি.","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ بْنُ هَارُونَ ‏ ‏أَنْبَأَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏خُبَيْبِ بْنِ عَبْدِ الرَّحْمَنِ بْنِ خُبَيْبٍ ‏ ‏عَنْ ‏ ‏حَفْصِ بْنِ عَاصِمٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏قَالَ ‏ ‏صَلَّيْتُ مَعَ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَأَبِي بَكْرٍ ‏ ‏وَعُمَرَ ‏ ‏وَعُثْمَانَ ‏ ‏سِتَّ سِنِينَ ‏ ‏بِمِنًى ‏ ‏فَصَلَّوْا صَلَاةَ الْمُسَافِرِ ‏","","",""],[4627,4627,"","আমরা একটা ছেলের সাথে ঝগড়া করেছি, যে কিনা এটার সমাধান করতে বলেছে, সে বলেছিল, যেমন একটা গাছ আমি এটা ফাকাতে চাইনা, তাই সে বলল আমি মরে যাব। আমি এটা বলি, আমি প্রভুর সাথে ঝগড়া করবো। আর আমি এটা করতে চাই। আমি জানি, আমি তোমাকে বলি, আমি এটা একটা জিনিস। আর আমি জানি না। কিন্তু আমি যদি তুমি জানো, আমি এটা করতে চাই, আমি এটা একটা ছোট বাচ্চা। আর আমি জানি না যে, আমি তোমাকে একটা ছোট বাচ্চা। আর আমি জানি, আমি এটা একটা বাচ্চা। কিন্তু আমি যদি তুমি জানো, আমি এটা একটা ছোট ছেলে হবে। আর আমি জানি, আমি জানি যে তুমি জানো, আমি এটা একটা বাচ্চা। আমি তোমার জন্য না। আমি কি করবো? ওর জন্য প্রার্থনা করো আর সে হাল ছেড়ে দেবে, এটাই কল্পনা।","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ بْنُ هَارُونَ ‏ ‏أَخْبَرَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏مُحَارِبِ بْنِ دِثَارٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏إِنَّ مَثَلَ الْمُؤْمِنِ مَثَلُ شَجَرَةٍ لَا يَسْقُطُ وَرَقُهَا فَمَا هِيَ قَالَ فَقَالُوا وَقَالُوا فَلَمْ يُصِيبُوا وَأَرَدْتُ أَنْ أَقُولَ هِيَ النَّخْلَةُ فَاسْتَحْيَيْتُ فَقَالَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏هِيَ النَّخْلَةُ ‏","","",""],[4628,4628,"","আমরা ভুলেই গিয়েছিলাম যে হয়তো আমরা এটা করতে যাচ্ছি। সে আমাকে আজ রাতে ফোন করবে, আর তারপর সে শেষ রাতে চলে যাবে।","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ ‏ ‏أَخْبَرَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏أَنَسِ بْنِ سِيرِينَ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ عُمَرَ ‏ ‏قَالَ ‏ ‏كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يُصَلِّي اللَّيْلَ مَثْنَى مَثْنَى ثُمَّ يُوتِرُ بِرَكْعَةٍ مِنْ آخِرِ اللَّيْلِ ثُمَّ يَقُومُ كَأَنَّ الْأَذَانَ وَالْإِقَامَةَ فِي أُذُنَيْهِ ‏","","",""],[4629,4629,"","আমরা আমার বাবার কথা বলেছিলাম যে আমি একটা ছেলেকে বলতে চাই যে অন্ধকারে আছে।","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ ‏ ‏أَخْبَرَنَا ‏ ‏إِسْمَاعِيلُ ‏ ‏عَنْ ‏ ‏أَبِي حَنْظَلَةَ ‏ ‏قَالَ ‏ ‏سَأَلْتُ ‏ ‏ابْنَ عُمَرَ ‏ ‏عَنْ الصَّلَاةِ فِي السَّفَرِ فَقَالَ ‏ ‏الصَّلَاةُ فِي السَّفَرِ رَكْعَتَيْنِ فَقَالَ إِنَّا آمِنُونَ لَا نَخَافُ أَحَدًا قَالَ سُنَّةُ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏","","",""],[4630,4630,"","আমরা একটি ছেলে কথা বলেছি যে ঈশ্বরকে শুনতে পায়, সে বলবে মানুষ হয়তো প্রভুর জীবনের সবচেয়ে বেশি কিছু করতে পারে।","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ ‏ ‏أَخْبَرَنَا ‏ ‏مُحَمَّدُ بْنُ إِسْحَاقَ ‏ ‏عَنْ ‏ ‏نَافِعٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏قَالَ ‏ ‏سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏يَقُومُ النَّاسُ لِرَبِّ الْعَالَمِينَ لِعَظَمَةِ الرَّحْمَنِ تَبَارَكَ وَتَعَالَى يَوْمَ الْقِيَامَةِ حَتَّى إِنَّ الْعَرَقَ ‏ ‏لَيُلْجِمُ ‏ ‏الرِّجَالَ إِلَى أَنْصَافِ آذَانِهِمْ ‏","","",""],[4631,4631,"","আমরা বাবার ছেলের কথা বলেছি যে সে কখনো যেতে দেবে না। সে মাতাল আর মাতাল মানুষ হিসেবে সব কিছু করেছে।","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ ‏ ‏أَخْبَرَنَا ‏ ‏مُحَمَّدُ بْنُ عَمْرٍو ‏ ‏عَنْ ‏ ‏أَبِي سَلَمَةَ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كُلُّ مُسْكِرٍ خَمْرٌ وَكُلُّ مُسْكِرٍ حَرَامٌ ‏","","",""],[4632,4632,"","আমরা আমাদের আরও বলার চেষ্টা করেছি একটি ছেলে কি অর্থ করে তাকে রক্ষা করতে পারে. আমি ঈশ্বরের কাছে প্রার্থনা করা বন্ধ করেছি এবং তাকে ঘোমটাতে পাঠানো হবে. আপনার প্রভু অধিকার বা ঈশ্বর যে এখনও আছে তা তিনি করতে পারেন. আমার কথা শোন, লর্ড তাকে মারতে পারবে না। সে বলল, ঈশ্বর তার কাছে প্রার্থনা করেছেন এবং আল্লাহ তাকে এই কাজ করতে বলেছেন। আর ঈশ্বর বলেন, আপনি শুনতে পাচ্ছেন না। মৃত্যু।","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ ‏ ‏أَخْبَرَنَا ‏ ‏مُحَمَّدٌ يَعْنِي ابْنَ عَمْرٍو ‏ ‏عَنْ ‏ ‏يَحْيَى بْنِ عَبْدِ الرَّحْمَنِ بْنِ حَاطِبٍ ‏ ‏أَنَّهُ حَدَّثَهُمْ عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏أَنَّهُ قَالَ ‏ ‏وَقَفَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَلَى ‏ ‏الْقَلِيبِ ‏ ‏يَوْمَ ‏ ‏بَدْرٍ ‏ ‏فَقَالَ يَا فُلَانُ يَا فُلَانُ هَلْ وَجَدْتُمْ مَا ‏ ‏وَعَدَ ‏ ‏رَبُّكُمْ حَقًّا أَمَا وَاللَّهِ إِنَّهُمْ الْآنَ لَيَسْمَعُونَ كَلَامِي قَالَ ‏ ‏يَحْيَى ‏ ‏فَقَالَتْ ‏ ‏عَائِشَةُ ‏ ‏غَفَرَ اللَّهُ ‏ ‏لِأَبِي عَبْدِ الرَّحْمَنِ ‏ ‏إِنَّهُ ‏ ‏وَهِلَ ‏ ‏إِنَّمَا قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَاللَّهِ إِنَّهُمْ لَيَعْلَمُونَ الْآنَ أَنَّ الَّذِي كُنْتُ أَقُولُ لَهُمْ حَقًّا وَإِنَّ اللَّهَ تَعَالَى يَقُولُ ‏ { ‏إِنَّكَ لَا تُسْمِعُ الْمَوْتَى ‏} { ‏وَمَا أَنْتَ بِمُسْمِعٍ مَنْ فِي الْقُبُورِ ‏}","","",""],[4633,4633,"","আমরা এমন একজন লোককে বলেছি যে হয়তো একটা ছেলেকে রক্ষা করতে পারে। ঈশ্বর তাকে আদেশ দিয়েছেন আর আত্মসমর্পণ করেছেন এই বলে যে, এখন তিনি তার বাবা-মা'র পাপের জন্য পাপ করতে ব্যর্থ হয়েছেন। ঈশ্বর সাহায্য করেন তিনি লর্ডের কাছে আর তার পালনকর ্ তার কাছে এসেছেন। তিনি এখন মুক্তির জন্য এই শাস্তি এবং আমি তারই চাই।","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ ‏ ‏أَخْبَرَنَا ‏ ‏مُحَمَّدُ بْنُ عَمْرٍو ‏ ‏عَنْ ‏ ‏يَحْيَى بْنِ عَبْدِ الرَّحْمَنِ بْنِ حَاطِبٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏قَالَ ‏ ‏مَرَّ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بِقَبْرٍ فَقَالَ إِنَّ هَذَا لَيُعَذَّبُ الْآنَ بِبُكَاءِ أَهْلِهِ عَلَيْهِ فَقَالَتْ ‏ ‏عَائِشَةُ ‏ ‏غَفَرَ اللَّهُ ‏ ‏لِأَبِي عَبْدِ الرَّحْمَنِ ‏ ‏إِنَّهُ ‏ ‏وَهِلَ ‏ ‏إِنَّ اللَّهَ تَعَالَى يَقُولُ ‏ { ‏وَلَا ‏ ‏تَزِرُ ‏ ‏وَازِرَةٌ ‏ ‏وِزْرَ ‏ ‏أُخْرَى ‏} ‏إِنَّمَا قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِنَّ هَذَا لَيُعَذَّبُ الْآنَ وَأَهْلُهُ يَبْكُونَ عَلَيْهِ ‏","","",""],[4634,4634,"","আমরা আইনের অনুগ্রহে বাস করা নিয়ে আমাদের চিন্তা নিয়ে কথা বলেছি, ঈশ্বর দ্বিতীয়বারের মতো দ্বিতীয় বার এবং তার মুখ বন্ধ রেখেছেন, কিন্তু আমার বাবা আছে। তার আশীর্বাদে আশীর্বাদ হয়েছে, আর তুমি দশ মাস ধরে... ...তুমি দশ মাস ধরে নিচে থেকে বলেছ যে মাস বৃদ্ধি পাবে আর সূর্য ঠিক হয়ে যাবে।","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ ‏ ‏أَخْبَرَنَا ‏ ‏مُحَمَّدٌ ‏ ‏عَنْ ‏ ‏يَحْيَى بْنِ عَبْدِ الرَّحْمَنِ بْنِ حَاطِبٍ ‏ ‏قَالَ قَالَ ‏ ‏عَبْدُ اللَّهِ بْنُ عُمَرَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏الشَّهْرُ تِسْعٌ وَعِشْرُونَ وَصَفَّقَ بِيَدَيْهِ مَرَّتَيْنِ ثُمَّ صَفَّقَ الثَّالِثَةَ وَقَبَضَ إِبْهَامَهُ فَقَالَتْ ‏ ‏عَائِشَةُ ‏ ‏غَفَرَ اللَّهُ ‏ ‏لِأَبِي عَبْدِ الرَّحْمَنِ ‏ ‏إِنَّهُ ‏ ‏وَهِلَ ‏ ‏إِنَّمَا هَجَرَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏نِسَاءَهُ شَهْرًا فَنَزَلَ لِتِسْعٍ وَعِشْرِينَ فَقَالُوا يَا رَسُولَ اللَّهِ إِنَّكَ نَزَلَتْ لِتِسْعٍ وَعِشْرِينَ فَقَالَ ‏ ‏إِنَّ الشَّهْرَ يَكُونُ تِسْعًا وَعِشْرِينَ ‏","","",""],[4635,4635,"","আমরা একটি ছেলে যে কিনা ঈশ্বরের কাজে নিয়োজিত একটি ছেলে সম্পর্কে সবচেয়ে উজ্জ্বল স্বপ্ন কথা বলেছি। যে কিনা কিনা কিনা কিনা একটি মৃতদেহের জন্য প্রার্থনা করেছে, যে ঈশ্বরকে প্রার্থনা করতে বলেছে এবং কি সারতে চায়। দরিদ্ররা অনেকটা।","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ ‏ ‏أَخْبَرَنَا ‏ ‏إِسْمَاعِيلُ ‏ ‏عَنْ ‏ ‏سَالِمٍ الْبَرَّادِ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏مَنْ صَلَّى عَلَى جَنَازَةٍ فَلَهُ ‏ ‏قِيرَاطٌ ‏ ‏فَسُئِلَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَا ‏ ‏الْقِيرَاطُ ‏ ‏قَالَ مِثْلُ ‏ ‏أُحُدٍ ‏","","",""],[4636,4636,"","আমরা আমাদের সব থেকে ভালো খবর নিয়ে কথা বলেছি... ...একজন ছেলে যে ঈশ্বরের দ্বারা উপকৃত হয়েছে, সে বলবে এটাই সবচেয়ে উজ্জ্বল আর সে মানুষ হয়ে যাবে যদি সে জানে তার যা করার আছে, ব্রেসলেট ধরায় ভীত না, ওয়াররিস বলবে না যে এটা লাফ আর বিতর্কের কথা বলবে।","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ ‏ ‏أَخْبَرَنَا ‏ ‏مُحَمَّدٌ يَعْنِي ابْنَ إِسْحَاقَ ‏ ‏عَنْ ‏ ‏نَافِعٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏قَالَ ‏ ‏سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ عَلَى هَذَا الْمِنْبَرِ وَهُوَ ‏ ‏يَنْهَى النَّاسَ إِذَا أَحْرَمُوا عَمَّا يُكْرَهُ لَهُمْ لَا تَلْبَسُوا الْعَمَائِمَ وَلَا الْقُمُصَ وَلَا السَّرَاوِيلَاتِ وَلَا ‏ ‏الْبَرَانِسَ ‏ ‏وَلَا الْخُفَّيْنِ إِلَّا أَنْ يُضْطَرَّ مُضْطَرٌّ إِلَيْهِمَا فَيَقْطَعَهُمَا أَسْفَلَ مِنْ الْكَعْبَيْنِ وَلَا ثَوْبًا ‏ ‏مَسَّهُ ‏ ‏الْوَرْسُ ‏ ‏وَلَا ‏ ‏الزَّعْفَرَانُ ‏ ‏قَالَ وَسَمِعْتُهُ يَنْهَى النِّسَاءَ عَنْ الْقُفَّازِ ‏ ‏وَالنِّقَابِ ‏ ‏وَمَا مَسَّ ‏ ‏الْوَرْسُ ‏ ‏وَالزَّعْفَرَانُ ‏ ‏مِنْ الثِّيَابِ ‏","","",""],[4637,4637,"","আমরা তার সাথে কি ঘটেছে সে সম্পর্কে কথা বলেছি। আল্লাহ তাঁর জন্য প্রার্থনা করেন এবং তিনি বললেন, অক্সিজেন বিক্রি না করতে, এমনকি যদি তার বাড়ির বাড়ির ছাদ ঠিক থাকে।","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ ‏ ‏أَخْبَرَنَا ‏ ‏مُحَمَّدُ بْنُ عَمْرٍو ‏ ‏عَنْ ‏ ‏سَالِمِ بْنِ عَبْدِ اللَّهِ بْنِ عُمَرَ ‏ ‏أَنَّهُ حَدَّثَهُمْ عَنْ ‏ ‏أَبِيهِ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏لَا يَصْلُحُ بَيْعُ الثَّمَرِ حَتَّى ‏ ‏يَتَبَيَّنَ ‏ ‏صَلَاحُهُ ‏","","",""],[4638,4638,"","আমরা একটা ভাল ছেলের কথা বলেছি, যে কিনা দেখছে, সে এমন একটা জায়গায় গিয়েছে যেটা সে জিজ্ঞেস করেছিল কেন সে তোমাকে পাঠিয়েছে, সে বলল সে ঈশ্বরের কাছে পাঠালো।","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ بْنُ هَارُونَ ‏ ‏أَخْبَرَنَا ‏ ‏سُفْيَانُ يَعْنِي ابْنَ حُسَيْنٍ ‏ ‏عَنِ ‏ ‏الْحَكَمِ ‏ ‏عَنْ ‏ ‏مُجَاهِدٍ ‏ ‏قَالَ ‏ ‏كُنَّا مَعَ ‏ ‏ابْنِ عُمَرَ ‏ ‏فِي سَفَرٍ ‏ ‏فَمَرَّ بِمَكَانٍ ‏ ‏فَحَادَ ‏ ‏عَنْهُ فَسُئِلَ لِمَ فَعَلْتَ فَقَالَ رَأَيْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَعَلَ هَذَا فَفَعَلْتُ ‏","","",""],[4639,4639,"","আমরা আমাদের সংবাদের থেকে ভালো কথা বলেছি মানে হলো একটা সুখী ছেলে যে আমার ভালোবাসা নিয়ে বেঁচে আছে, আমার বাবা ঈশ্বরের সাথে বাস করতো কিন্তু কখনো ঈশ্বরও ছিলেন না। সে টাকা দিয়ে দিয়েছে, আর সে নিজের দুটো ঋণও নিতে পারেনি।","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ ‏ ‏أَخْبَرَنَا ‏ ‏يَحْيَى يَعْنِي ابْنَ سَعِيدٍ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ يَحْيَىِ بْنِ حَبَّانَ ‏ ‏أَخْبَرَهُ أَنَّ ‏ ‏رَجُلًا ‏ ‏أَخْبَرَهُ عَنْ ‏ ‏أَبِيهِ ‏ ‏يَحْيَى ‏ ‏أَنَّهُ كَانَ مَعَ ‏ ‏عَبْدِ اللَّهِ بْنِ عُمَرَ ‏ ‏وَأَنَّ ‏ ‏عَبْدَ اللَّهِ بْنَ عُمَرَ ‏ ‏قَالَ لَهُ فِي ‏ ‏الْفِتْنَةِ ‏ ‏لَا تَرَوْنَ الْقَتْلَ شَيْئًا ‏ ‏وَقَالَ ‏ ‏رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لِلثَّمَادَةِ ‏ ‏لَا ‏ ‏يَنْتَجِي ‏ ‏اثْنَانِ دُونَ صَاحِبِهِمَا ‏","","",""],[4640,4640,"","আমরা আমার বাবার আবেগ একটা বদৌলতে একটা শয়তান ছেলের প্রতি কথা বলেছি, তার মুখের একজন রাজাকে খুন করার এবং তার মুখের স্পর্শ করার জন্য তার সারা জীবন ধরে। যদি সে তার অনুগ্রহের কারণে ভেসে থাকে, তাহলে সে তার উপর আঘাত হানলো। ঈশ্বর তাঁর ছেলের দ্বারা পরাজিত হবেন, যখন তিনি ঈশ্বরের কাছে তাঁর প্রতিজ্ঞা করেছেন এবং তাঁর শয়তানের কাছে আত্মসমর্পণ করেছেন। তোমার সাথে.","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏الْمَسْعُودِيُّ ‏ ‏عَنْ ‏ ‏أَبِي جَعْفَرٍ مُحَمَّدِ بْنِ عَلِيٍّ ‏ ‏قَالَ ‏ ‏بَيْنَمَا ‏ ‏عُبَيْدُ بْنُ عُمَيْرٍ ‏ ‏يَقُصُّ وَعِنْدَهُ ‏ ‏عَبْدُ اللَّهِ بْنُ عُمَرَ ‏ ‏فَقَالَ ‏ ‏عُبَيْدُ بْنُ عُمَيْرٍ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَثَلُ الْمُنَافِقِ كَشَاةٍ مِنْ بَيْنِ ‏ ‏رَبِيضَيْنِ ‏ ‏إِذَا ‏ ‏أَتَتْ ‏ ‏هَؤُلَاءِ نَطَحْنَهَا وَإِذَا أَتَتْ هَؤُلَاءِ نَطَحْنَهَا فَقَالَ ‏ ‏ابْنُ عُمَرَ ‏ ‏لَيْسَ كَذَلِكَ قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِنَّمَا قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَشَاةٍ بَيْنَ غَنَمَيْنِ قَالَ فَاحْتَفَظَ الشَّيْخُ وَغَضِبَ فَلَمَّا رَأَى ذَلِكَ ‏ ‏عَبْدُ اللَّهِ ‏ ‏قَالَ أَمَا إِنِّي لَوْ لَمْ أَسْمَعْهُ لَمْ أَرُدَّ ذَلِكَ عَلَيْكَ ‏","","",""],[4641,4641,"","আমরা একটি ছেলের কথা বলেছিলাম যে আমি তাকে জিজ্ঞেস করেছি আমি কি করবো. অথবা যদি শক্তি শত্রুকে হত্যা করার আগে তারা জয় করে, তাহলে তারা তাকে বলে দেবে যে সে আসলে সে। ঈশ্বর ফিরে এসে আবার ফিরে এসেছিলেন এবং আমি মনে করি যে, একটা ছেলে মারা গিয়েছে, সেটা হল একটা ব্যাপার । ঈশ্বর তাকে আদেশ দিয়েছেন এবং আমার আদেশ পালন করবেন এবং জগতের বাহিনী দ্বারা চুপ করে থাকবে। সেই ব্যক্তি তার নিজের অথবা নিজের বই বহন করতে পারবেন না ।","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ ‏ ‏أَخْبَرَنَا ‏ ‏ابْنُ عَوْنٍ ‏ ‏قَالَ كَتَبْتُ إِلَى ‏ ‏نَافِعٍ ‏ ‏أَسْأَلُهُ مَا أَقْعَدَ ‏ ‏ابْنَ عُمَرَ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏عَنْ الْغَزْوِ ‏ ‏أَوْ عَنْ الْقَوْمِ ‏ ‏إِذَا غَزَوْا بِمَا يَدْعُونَ الْعَدُوَّ قَبْلَ أَنْ يُقَاتِلُوهُمْ وَهَلْ يَحْمِلُ الرَّجُلُ إِذَا كَانَ فِي الْكَتِيبَةِ بِغَيْرِ إِذْنِ إِمَامِهِ فَكَتَبَ إِلَيَّ إِنَّ ‏ ‏ابْنَ عُمَرَ ‏ ‏قَدْ كَانَ يَغْزُو وَلَدُهُ وَيَحْمِلُ عَلَى الظَّهْرِ وَكَانَ يَقُولُ إِنَّ أَفْضَلَ الْعَمَلِ بَعْدَ الصَّلَاةِ الْجِهَادُ فِي سَبِيلِ اللَّهِ تَعَالَى وَمَا أَقْعَدَ ‏ ‏ابْنَ عُمَرَ ‏ ‏عَنْ الْغَزْوِ إِلَّا وَصَايَا ‏ ‏لِعُمَرَ ‏ ‏وَصِبْيَانٌ صِغَارٌ ‏ ‏وَضَيْعَةٌ ‏ ‏كَثِيرَةٌ وَقَدْ ‏ ‏أَغَارَ ‏ ‏رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَلَى ‏ ‏بَنِي الْمُصْطَلِقِ ‏ ‏وَهُمْ ‏ ‏غَارُّونَ ‏ ‏يَسْقُونَ عَلَى نَعَمِهِمْ فَقَتَلَ مُقَاتِلَتَهُمْ وَسَبَى سَبَايَاهُمْ وَأَصَابَ ‏ ‏جُوَيْرِيَةَ بِنْتَ الْحَارِثِ ‏ ‏قَالَ فَحَدَّثَنِي بِهَذَا الْحَدِيثِ ‏ ‏ابْنُ عُمَرَ ‏ ‏وَكَانَ فِي ذَلِكَ الْجَيْشِ وَإِنَّمَا كَانُوا يُدْعَوْنَ فِي أَوَّلِ الْإِسْلَامِ وَأَمَّا الرَّجُلُ فَلَا يَحْمِلُ عَلَى الْكَتِيبَةِ إِلَّا بِإِذْنِ إِمَامِهِ ‏","","",""],[4642,4642,"","আমরা একটা ছেলের কথা বলেছি যে ঈশ্বরকে বলে যে, সে ছেলেটি।","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ ‏ ‏أَخْبَرَنَا ‏ ‏مُحَمَّدُ بْنُ إِسْحَاقَ ‏ ‏عَنْ ‏ ‏نَافِعٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏قَالَ ‏ ‏نَهَى رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنْ ‏ ‏يَتَنَاجَى ‏ ‏اثْنَانِ ‏ ‏دُونَ ‏ ‏الثَّالِثِ إِذَا لَمْ يَكُنْ مَعَهُمْ غَيْرُهُمْ قَالَ وَنَهَى النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنْ يَخْلُفَ الرَّجُلُ الرَّجُلَ فِي مَجْلِسِهِ وَقَالَ إِذَا رَجَعَ فَهُوَ أَحَقُّ بِهِ ‏","","",""],[4643,4643,"","আমরা একটা ছেলের কথা বলেছি যে ঈশ্বরকে শুনতে পায়, সে বলবে যদি আমরা মনে করি তুমি জনতার গৌরবে আছো, সে তার কোণ থেকে পরিবর্তন নিয়ে মজা পাবে।","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ ‏ ‏أَخْبَرَنَا ‏ ‏مُحَمَّدُ بْنُ إِسْحَاقَ ‏ ‏عَنْ ‏ ‏نَافِعٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏قَالَ ‏ ‏سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏إِذَا نَعَسَ أَحَدُكُمْ فِي الْمَسْجِدِ يَوْمَ الْجُمُعَةِ فَلْيَتَحَوَّلْ مِنْ مَجْلِسِهِ ذَلِكَ إِلَى غَيْرِهِ ‏","","",""],[4644,4644,"","আমরা আমাদের বলতে চেষ্টা করেছি যে আমরা ভালো কাজ করার এবং ঈশ্বরের দোহাই যখন তিনি একটি ছেলের জন্য করা হয়েছে, তিনি জন্য ঈশ্বরের জন্য করা হয়েছে, আমি তার জন্য প্রার্থনা এবং তিনি একটি একটি ৫ না একটি হিংসাকে হত্যা করে, কাছে গিয়ে গরু খেয়ে ফেল","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ ‏ ‏أَخْبَرَنَا ‏ ‏مُحَمَّدٌ ‏ ‏عَنْ ‏ ‏نَافِعٍ ‏ ‏وَعُبَيْدِ اللَّهِ بْنِ عَبْدِ اللَّهِ بْنِ عُمَرَ ‏ ‏حَدَّثَاهُ عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏قَالَ ‏ ‏سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏خَمْسٌ لَا ‏ ‏جُنَاحَ ‏ ‏عَلَى أَحَدٍ فِي قَتْلِهِنَّ الْغُرَابُ وَالْفَأْرَةُ وَالْحِدَأَةُ وَالْعَقْرَبُ وَالْكَلْبُ ‏ ‏الْعَقُورُ ‏","","",""],[4645,4645,"","আমরা একটা ছেলের কথা বলেছি যে ঈশ্বরকে দেখে তার জন্য প্রার্থনা করেছে আর সে এটা করবে না, অথবা চুমুটা তালাবদ্ধ, অথবা এই গল্প তার সাথে বাঁধা। ঈশ্বর তোমার মঙ্গল করুক এবং তুমি যাও।","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ ‏ ‏أَخْبَرَنَا ‏ ‏مُحَمَّدٌ ‏ ‏عَنْ ‏ ‏نَافِعٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏قَالَ ‏ ‏رَأَى رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِي الْقِبْلَةِ ‏ ‏نُخَامَةً ‏ ‏فَأَخَذَ عُودًا أَوْ حَصَاةً فَحَكَّهَا بِهِ ثُمَّ قَالَ ‏ ‏إِذَا قَامَ أَحَدُكُمْ ‏ ‏يُصَلِّي فَلَا يَبْصُقْ فِي قِبْلَتِهِ فَإِنَّمَا ‏ ‏يُنَاجِي ‏ ‏رَبَّهُ تَبَارَكَ وَتَعَالَى ‏","","",""],[4646,4646,"","আমরা ঈশ্বরের একজন পুত্র সম্পর্কে অনেক কথা বলেছি, গত রাতে থেকে আমার আর নাইজেরিয়রা পালিয়ে যায়।","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ ‏ ‏حَدَّثَنَا ‏ ‏هِشَامٌ ‏ ‏عَنْ ‏ ‏مُحَمَّدٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏صَلَاةُ اللَّيْلِ مَثْنَى مَثْنَى ‏ ‏وَالْوِتْرُ ‏ ‏رَكْعَةٌ مِنْ آخِرِ اللَّيْلِ ‏","","",""],[4647,4647,"","আমরা কথা দিয়েছি আমরা ঈশ্বরের এক ছেলের জন্য একটা উপহার পেতে পারি যে ভালোবাসার জন্য তৈরি হয়েছে.","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ ‏ ‏أَخْبَرَنَا ‏ ‏مُحَمَّدُ بْنُ إِسْحَاقَ ‏ ‏عَنْ ‏ ‏نَافِعٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏الدَّجَّالُ ‏ ‏أَعْوَرُ الْعَيْنِ كَأَنَّهَا عِنَبَةٌ ‏ ‏طَافِيَةٌ ‏","","",""],[4648,4648,"","আমরা আমাদের ভাইয়ের থেকে বেশি কথা বলেছি... ...আমি একটা ভালো ডিম বানিয়েছি যেটা নিয়ে আমরা আমার ভাইয়ের সাথে কথা বলেছি। ঐ ছেলে তার কাছে প্রার্থনা করেছে আর তোমাকে যাদের কাছে পৌঁছে দিয়েছে তাদের কাছে। খোদা এতে ক্লান্ত হয়ে যাচ্ছে, না হয় আমার খারাপ লাগছে।","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ ‏ ‏أَخْبَرَنَا ‏ ‏أَصْبَغُ بْنُ زَيْدٍ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو بِشْرٍ ‏ ‏عَنْ ‏ ‏أَبِي الزَّاهِرِيَّةِ ‏ ‏عَنْ ‏ ‏كَثِيرِ بْنِ مُرَّةَ الْحَضْرَمِيِّ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَنْ ‏ ‏احْتَكَرَ ‏ ‏طَعَامًا أَرْبَعِينَ لَيْلَةً فَقَدْ بَرِئَ مِنْ اللَّهِ تَعَالَى وَبَرِئَ اللَّهُ تَعَالَى مِنْهُ وَأَيُّمَا أَهْلُ ‏ ‏عَرْصَةٍ ‏ ‏أَصْبَحَ فِيهِمْ امْرُؤٌ جَائِعٌ فَقَدْ بَرِئَتْ مِنْهُمْ ‏ ‏ذِمَّةُ ‏ ‏اللَّهِ تَعَالَى ‏","","",""],[4649,4649,"","আমরা আমাদের কাছে তার ছেলে সম্পর্কে আমাদের সব থেকে ভালো কথা বলেছি... ...সে কি বলছে. তোমার যুক্তি হচ্ছে তোমার ছেলে তার ইচ্ছা আর সে আত্মসমর্পণ করবে না.","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏أَخْبَرَنَا ‏ ‏مَعْمَرٌ ‏ ‏عَنِ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنْ ‏ ‏سَالِمٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏أَنَّهُ كَانَ ‏ ‏يَكْرَهُ ‏ ‏الِاشْتِرَاطَ فِي الْحَجِّ وَيَقُولُ أَمَا حَسْبُكُمْ ‏ ‏سُنَّةَ ‏ ‏نَبِيِّكُمْ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِنَّهُ لَمْ يَشْتَرِطْ ‏","","",""],[4650,4650,"","আমরা একটি ছেলে সম্পর্কে কথা বলেছি যে কিনা ঈশ্বরের দোহাই দিয়ে আমার ভালোবাসায় মুগ্ধ হয়েছে। খাও।","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏حَدَّثَنَا ‏ ‏مَعْمَرٌ ‏ ‏عَنْ ‏ ‏أَيُّوبَ ‏ ‏عَنْ ‏ ‏نَافِعٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏وَعُبَيْدُ اللَّهِ ‏ ‏عَنْ ‏ ‏نَافِعٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏قَالَ ‏ ‏سُئِلَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَنْ الضَّبِّ فَقَالَ ‏ ‏لَسْتُ بِآكِلِهِ وَلَا مُحَرِّمِهِ ‏","","",""],[4651,4651,"","ঈশ্বর তাকে আদেশ দিয়েছেন আর আমি আপনার বিরুদ্ধে পদক্ষেপ নিতে ইচ্ছুক ।","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏أَخْبَرَنَا ‏ ‏إِسْرَائِيلُ ‏ ‏عَنْ ‏ ‏سِمَاكٍ ‏ ‏عَنْ ‏ ‏سَعِيدِ بْنِ جُبَيْرٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏أَنَّهُ سَأَلَ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَشْتَرِي الذَّهَبَ بِالْفِضَّةِ فَقَالَ ‏ ‏إِذَا أَخَذْتَ وَاحِدًا مِنْهُمَا فَلَا يُفَارِقْكَ صَاحِبُكَ وَبَيْنَكَ وَبَيْنَهُ ‏ ‏لَبْسٌ ‏","","",""],[4652,4652,"","আমরা আমাদের সবচেয়ে ভালো ছেলের কথা বলেছি, আমার ছেলেকে আমি আমার নীরবতার কথা বলেছি। যদি বলি, তাহলে আমি বলব যে শান্তি তোমার ক্ষমতায় আছে। আল্লাহ তাকে ভগবানের দিকে লক্ষ্য করেনি বলে তার সাথে দেখা করতে।","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏أَخْبَرَنَا ‏ ‏دَاوُدُ يَعْنِي ابْنَ قَيْسٍ ‏ ‏عَنْ ‏ ‏زَيْدِ بْنِ أَسْلَمَ ‏ ‏قَالَ ‏ ‏أَرْسَلَنِي أَبِي إِلَى ‏ ‏ابْنِ عُمَرَ ‏ ‏فَقُلْتُ أَأَدْخُلُ فَعَرَفَ صَوْتِي فَقَالَ أَيْ بُنَيَّ إِذَا أَتَيْتَ إِلَى قَوْمٍ فَقُلْ السَّلَامُ عَلَيْكُمْ فَإِنْ رَدُّوا عَلَيْكَ فَقُلْ أَأَدْخُلُ قَالَ ثُمَّ رَأَى ابْنَهُ وَاقِدًا يَجُرُّ إِزَارَهُ فَقَالَ ارْفَعْ إِزَارَكَ فَإِنِّي سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏مَنْ جَرَّ ثَوْبَهُ مِنْ ‏ ‏الْخُيَلَاءِ ‏ ‏لَمْ يَنْظُرْ اللَّهُ إِلَيْهِ ‏","","",""],[4653,4653,"","আমরা দলের মধ্যে থেকে ভালো কথা বলেছি একটা ছেলের জন্য যে ঈশ্বরকে এসেছে, সে বলল আমি তোমাকে সূর্যের আলো থেকে ফোন করতে পারব না।","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏حَدَّثَنَا ‏ ‏مَالِكٌ ‏ ‏عَنْ ‏ ‏نَافِعٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَا ‏ ‏يَتَحَرَّ ‏ ‏أَحَدُكُمْ أَنْ يُصَلِّيَ عِنْدَ طُلُوعِ الشَّمْسِ وَلَا عِنْدَ غُرُوبِهَا ‏","","",""],[4654,4654,"","ঈশ্বর তাঁর কাছে প্রার্থনা করেছেন এবং আমি যদি কেবলমাত্র তাঁর কাছে তার সঙ্গে কথা বলি, তা হলে তিনি তাতে রাজি হয়েছেন । আর সে তার টাকা নিয়ে ড্রিংক করে।","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏حَدَّثَنَا ‏ ‏مَالِكٌ ‏ ‏عَنِ ‏ ‏ابْنِ شِهَابٍ ‏ ‏عَنْ ‏ ‏أَبِي بَكْرِ بْنِ عُبَيْدِ اللَّهِ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِذَا أَكَلَ أَحَدُكُمْ فَلْيَأْكُلْ بِيَمِينِهِ وَإِذَا شَرِبَ فَلْيَشْرَبْ بِيَمِينِهِ فَإِنَّ الشَّيْطَانَ يَأْكُلُ بِشِمَالِهِ وَيَشْرَبُ بِشِمَالِهِ ‏","","",""],[4655,4655,"","আমরা সেই লোকেদের সম্বন্ধে সবচেয়ে ভাল কথা বলেছিলাম, যারা আপনাকে আ্যটকে আগে যে - বিয়ের কথা বলেছিল, সেই সম্বন্ধে আমাদের বলেছিল । যেহেতু আমি ঈশ্বরের অনুগ্রহ দেখেছি, এমন এক ছেলের কথা যিনি নিজের পাশ দিয়ে চলে গেছেন।","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏أَخْبَرَنَا ‏ ‏مَعْمَرٌ ‏ ‏عَنِ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنْ ‏ ‏سَالِمٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏قَالَ ‏ ‏مَا تَرَكْتُ ‏ ‏اسْتِلَامَ ‏ ‏الرُّكْنَيْنِ فِي رَخَاءٍ وَلَا شِدَّةٍ مُنْذُ رَأَيْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَسْتَلِمُهُمَا ‏ ‏قَالَ ‏ ‏مَعْمَرٌ ‏ ‏وَأَخْبَرَنِي ‏ ‏أَيُّوبُ ‏ ‏عَنْ ‏ ‏نَافِعٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏مِثْلَهُ ‏","","",""],[4656,4656,"","তার কাছে বলেন যে, আমরা একটা ছেলের কথা বলি, যিনি ঈশ্বরের দ্বারা উত্থাপিত হয়েছিলেন এবং তার সঙ্গে কথা বলেছিলাম । তার নিজের স্বপ্নের জন্য।","‏ ‏قَالَ ‏ ‏و حَدَّثَنَا ‏ ‏مَعْمَرٌ ‏ ‏عَنْ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنْ ‏ ‏سَالِمٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏حَلَقَ فِي حَجَّتِهِ ‏ ‏قَالَ ‏ ‏و حَدَّثَنَا ‏ ‏مَعْمَرٌ ‏ ‏عَنْ ‏ ‏أَيُّوبَ ‏ ‏عَنْ ‏ ‏نَافِعٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مِثْلَهُ ‏","","",""],[4657,4657,"","আমরা ব্যান্ডের সবচেয়ে ভাল সম্পর্কে কথা বলেছি। সে হঠাৎই তার নাম আত্মসমর্পণ করেছে এবং সে নিজেকে আত্মসমর্পণ করেছে। দরজাটি ভদ্র হয়ে চলে যাবে। ঈশ্বর তাকে জিজ্ঞেস করেছেন, সে বলবে আমি কত করে যাব।","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏حَدَّثَنَا ‏ ‏عُبَيْدُ اللَّهِ ‏ ‏عَنْ ‏ ‏نَافِعٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏قَالَ ‏ ‏دَخَلَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَوْمَ فَتْحِ ‏ ‏مَكَّةَ ‏ ‏عَلَى نَاقَةٍ ‏ ‏لِأُسَامَةَ بْنِ زَيْدٍ ‏ ‏حَتَّى ‏ ‏أَنَاخَ ‏ ‏بِفِنَاءِ ‏ ‏الْكَعْبَةِ ‏ ‏فَدَعَا ‏ ‏عُثْمَانَ بْنَ طَلْحَةَ ‏ ‏بِالْمِفْتَاحِ فَجَاءَ بِهِ فَفَتَحَ فَدَخَلَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَأُسَامَةُ ‏ ‏وَبِلَالٌ ‏ ‏وَعُثْمَانُ بْنُ طَلْحَةَ ‏ ‏فَأَجَافُوا ‏ ‏عَلَيْهِمْ الْبَابَ ‏ ‏مَلِيًّا ‏ ‏ثُمَّ فَتَحُوهُ قَالَ ‏ ‏عَبْدُ اللَّهِ ‏ ‏فَبَادَرْتُ ‏ ‏النَّاسَ فَوَجَدْتُ ‏ ‏بِلَالًا ‏ ‏عَلَى الْبَابِ قَائِمًا فَقُلْتُ أَيْنَ صَلَّى رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏بَيْنَ الْعَمُودَيْنِ الْمُقَدَّمَيْنِ قَالَ وَنَسِيتُ أَنْ أَسْأَلَهُ كَمْ صَلَّى ‏","","",""],[4658,4658,"","আমরা সবচেয়ে ভালো একটা ফুল সম্পর্কে কথা বলেছি, যাকে আমরা ঈশ্বরের কাছে নিয়ে এসেছিলাম।","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏أَخْبَرَنَا ‏ ‏مَعْمَرٌ ‏ ‏عَنِ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنْ ‏ ‏سَالِمٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَذِنَ لِضَعَفَةِ النَّاسِ مِنْ ‏ ‏الْمُزْدَلِفَةِ ‏ ‏بِلَيْلٍ ‏","","",""],[4659,4659,"","আমরা আমাদের সেরা দুই ছেলেদের কথা বলেছি আমার বাবা সম্পর্কে একটি ছেলে জন্ম নিয়ে আপনার টাকা দিয়ে, যে জন্ম হয়, তার সাথে সাথে আমি হলাম সেই রকম একজন ছেলে, যে কিনা সূর্যাস্ত এবং বাসা দিয়ে জন্ম নিয়েছে, আমি কেবল এক সবচেয়ে ভালো যে প্রভুর বার্তাবাহকের কাছে প্রার্থনা করেছে...","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏أَخْبَرَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏أَبِي إِسْحَاقَ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ مَالِكٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏قَالَ ‏ ‏صَلَّيْتُ مَعَهُ الْمَغْرِبَ ثَلَاثًا وَالْعِشَاءَ رَكْعَتَيْنِ بِإِقَامَةٍ وَاحِدَةٍ فَقَالَ لَهُ ‏ ‏مَالِكُ بْنُ خَالِدٍ الْحَارِثِيُّ ‏ ‏مَا هَذِهِ الصَّلَاةُ يَا ‏ ‏أَبَا عَبْدِ الرَّحْمَنِ ‏ ‏قَالَ صَلَّيْتُهَا مَعَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِي هَذَا الْمَكَانِ بِإِقَامَةٍ وَاحِدَةٍ ‏","","",""],[4660,4660,"","এটলাসের আগে আমরা কথা বলেছি একজন চাচার ছেলে, যিনি এক বছরের জন্য সুখী, ঈশ্বর আপনার টাকা দান করেছেন, যিনি ঈশ্বর তাকে আশীর্বাদ করেছেন এবং তাকে শিখিয়েছেন। ঈশ্বরের সবচেয়ে সুন্দর পুত্র হওয়ার জন্য ।","‏ ‏قَالَ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏أَخْبَرَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏سَلَمَةَ بْنِ كُهَيْلٍ ‏ ‏عَنْ ‏ ‏سَعِيدٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏ح ‏ ‏و عَنْ ‏ ‏أَبِي إِسْحَاقَ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ مَالِكٍ الْأَسَدِيِّ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏جَمَعَ بَيْنَ الْمَغْرِبِ وَالْعِشَاءِ ‏ ‏بِجَمْعٍ ‏ ‏صَلَّى الْمَغْرِبَ ثَلَاثًا وَالْعِشَاءَ رَكْعَتَيْنِ بِإِقَامَةٍ وَاحِدَةٍ ‏","","",""],[4661,4661,"","আমরা আমাদের সেরাদের কথা বলছি একটি ছেলের জন্য ফুল সম্পর্কে যে এটা শুনেছিল তার সম্পর্কে যে কিনা এটা শুনেছিল. আমার প্রভু আপনার আত্মা আপনার ভাইয়ের উদ্দেশ্যে উদ্বুদ্ধ করতে হবে. আমরা কথা বলেছিলাম. একটা ছেলে সম্বন্ধে আমাদের কত উত্তম বিষয়ই না বলা হয়েছিল ।","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏أَخْبَرَنَا ‏ ‏مَعْمَرٌ ‏ ‏عَنِ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنْ ‏ ‏سَالِمٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏قَالَ ‏ ‏سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يُلَبِّي ‏ ‏لَبَّيْكَ اللَّهُمَّ لَبَّيْكَ لَبَّيْكَ لَا شَرِيكَ لَكَ لَبَّيْكَ إِنَّ الْحَمْدَ وَالنِّعْمَةَ لَكَ وَالْمُلْكَ لَا شَرِيكَ لَكَ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏أَخْبَرَنَا ‏ ‏مَعْمَرٌ ‏ ‏عَنْ ‏ ‏أَيُّوبَ ‏ ‏عَنْ ‏ ‏نَافِعٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏وَمَالِكٌ ‏ ‏عَنْ ‏ ‏نَافِعٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مِثْلَهُ ‏","","",""],[4662,4662,"","আমরা বলেছিলাম, তিনি কি করতে হবে তাকে কি করতে হবে। সে বলবে একজন মানুষ এবং গরীবকে খুন করতে চাচ্ছে। আর যখন আপনি সবচেয়ে বেশি কিছু বলছেন না, তখন তিন বা চার, তারপর সে দুই বাচ্চাকে শিখতে বলে।","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏أَخْبَرَنَا ‏ ‏مَعْمَرٌ ‏ ‏عَنْ ‏ ‏أَيُّوبَ ‏ ‏عَنْ ‏ ‏نَافِعٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ يَوْمَ ‏ ‏الْحُدَيْبِيَةِ ‏ ‏اللَّهُمَّ اغْفِرْ لِلْمُحَلِّقِينَ فَقَالَ رَجُلٌ وَالْمُقَصِّرِينَ فَقَالَ اللَّهُمَّ اغْفِرْ لِلْمُحَلِّقِينَ فَقَالَ وَلِلْمُقَصِّرِينَ حَتَّى قَالَهَا ثَلَاثًا أَوْ أَرْبَعًا ثُمَّ قَالَ وَلِلْمُقَصِّرِينَ ‏","","",""],[4663,4663,"","আমি সিল্কগুলো জাগিয়ে তুলি এবং এরপর তিনি আমার কাছে ফিরে আসেন ।","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏أَخْبَرَنَا ‏ ‏عُبَيْدُ اللَّهِ ‏ ‏عَنْ ‏ ‏نَافِعٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَفَاضَ ‏ ‏يَوْمَ النَّحْرِ ‏ ‏ثُمَّ رَجَعَ فَصَلَّى الظُّهْرَ ‏ ‏بِمِنًى ‏","","",""],[4664,4664,"","আমরা সবচেয়ে ভালো একটা ছেলের কথা বলেছি, যে আমার কাছে এসেছিল, সে নাকি ভালোর রক্ষক নয়। এক দিন পর কেউ তোমাকে গুলি করতে পারবে না। একটা শপথে, আমরা আর কাজ করবো না যদি আমরা এটা না পাই।","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏أَخْبَرَنَا ‏ ‏مَعْمَرٌ ‏ ‏عَنِ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنْ ‏ ‏سَالِمٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏أَنَّ رَجُلًا نَادَى فَقَالَ يَا رَسُولَ اللَّهِ مَا يَجْتَنِبُ الْمُحْرِمُ مِنْ الثِّيَابِ فَقَالَ ‏ ‏لَا يَلْبَسُ السَّرَاوِيلَ وَلَا الْقَمِيصَ وَلَا ‏ ‏الْبُرْنُسَ ‏ ‏وَلَا الْعِمَامَةَ وَلَا ثَوْبًا ‏ ‏مَسَّهُ ‏ ‏زَعْفَرَانٌ وَلَا ‏ ‏وَرْسٌ ‏ ‏وَلْيُحْرِمْ أَحَدُكُمْ فِي ‏ ‏إِزَارٍ ‏ ‏وَرِدَاءٍ وَنَعْلَيْنِ فَإِنْ لَمْ يَجِدْ نَعْلَيْنِ فَلْيَلْبَسْ خُفَّيْنِ وَلْيَقْطَعْهُمَا حَتَّى يَكُونَا أَسْفَلَ مِنْ ‏ ‏الْعَقِبَيْنِ ‏","","",""],[4665,4665,"","তিন জনের পর আমার আলো রক্ষা করার জন্য একটা মই রয়েছে অনুষ্ঠান।","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏أَخْبَرَنَا ‏ ‏مَعْمَرٌ ‏ ‏عَنِ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنْ ‏ ‏سَالِمٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏نَهَى أَنْ تُؤْكَلَ لُحُومُ الْأَضَاحِيِّ بَعْدَ ثَلَاثٍ ‏","","",""],[4666,4666,"","আমি যে আমার জীবনে সবচেয়ে ভালো কিছুর কথা বলেছি, তার সাথে আমি এক ছেলের স্বপ্নের কথা বলেছিলাম, যার প্রভুর কাছে ছিল। তিনি আমার অতীত জীবনের শেষ করেছেন। আমি আমার স্বপ্নের মধ্যে যা করেছি, তা হল, আমি আমার জীবনের সবচেয়ে ভালো কিছুর জন্য। আমি আমার স্বপ্নের মধ্যে একটা হল, আমার স্বপ্ন। আমি আমার স্বপ্নের কথা বলেছি। আমি আমার জীবনের জন্য, আমি আমার জীবনের শেষ সময়টাকে নিয়ে এসেছি। আমি আমার জীবনের উদ্দেশ্য ছিল আমার জীবনের উদ্দেশ্য। আমি আমার জীবনের উদ্দেশ্য নিয়ে আলোচনা করেছি। কিন্তু আমি এখন অনেক কিছু করতে চাই না। আমি মনে করি। আমি জানি না যে, আমি এখন আমার জীবনের জন্য। আমি আমার জীবনের জন্য অপেক্ষা করে যাচ্ছি। আমি আমার জীবনের জন্য। আমি আমার জীবনের জন্য। আমি আমার জীবনের জন্য। আমি আমার জীবনের জন্য অনেক সময় নির্ধারণ করেছি। আমি যখন আমি আমার জীবনের জন্য অপেক্ষা করি, তখন আমি জানি যে, আমি আমার বাবা-মাটকে বেছে নিয়েছি। আমি আমার জীবনের সবচেয়ে বড় হয়েছি।","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏حَدَّثَنَا ‏ ‏مَعْمَرٌ ‏ ‏عَنِ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنْ ‏ ‏سَالِمٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏مَنْ أَعْتَقَ ‏ ‏شِرْكًا ‏ ‏لَهُ فِي عَبْدٍ أُقِيمَ مَا بَقِيَ فِي مَالِهِ ‏","","",""],[4667,4667,"","আমরা জনতার সেরা কথা বলছি এক ছেলে সম্বন্ধে, যে আমাকে বলল যে একজন শান্তিপূর্ণ মহিলার জন্য তিন দিন বা প্রার্থনা করার অধিকার কি।","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏حَدَّثَنَا ‏ ‏مَعْمَرٌ ‏ ‏عَنِ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنْ ‏ ‏سَالِمٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏قَالَ ‏ ‏سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏مَا حَقُّ امْرِئٍ مُسْلِمٍ تَمُرُّ عَلَيْهِ ثَلَاثُ لَيَالٍ إِلَّا وَوَصِيَّتُهُ عِنْدَهُ ‏","","",""],[4668,4668,"","ঈশ্বর তাকে তার জীবন বাঁচাতে এবং ঈশ্বর যে - বিষয়গুলো করবেন, সেগুলো তিনি উপভোগ করবেন । শান্তি।","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏أَخْبَرَنَا ‏ ‏مَعْمَرٌ ‏ ‏عَنِ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنْ ‏ ‏سَالِمٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏أَنَّ ‏ ‏عُمَرَ ‏ ‏حَمَلَ عَلَى فَرَسٍ لَهُ فِي سَبِيلِ اللَّهِ ثُمَّ رَآهَا تُبَاعُ فَأَرَادَ أَنْ يَشْتَرِيَهَا فَقَالَ لَهُ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَا تَعُدْ فِي ‏ ‏صَدَقَتِكَ ‏","","",""],[4669,4669,"","আমি তার বাবা আর ভালোবাসার পর কিভাবে যাওয়ার স্বপ্ন নিয়ে কথা বলেছিলাম, সে বলল সে আমার বাবার ভদ্র শিল্প ঠিক করার চেষ্টা করছে, কিন্তু সে কার কাছে গিয়েছে তা দিতে। সে বলেছে, অন্যটা তোমার সঙ্গী।","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏أَخْبَرَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏وَالْأَعْمَشِ ‏ ‏وَمَنْصُورٍ ‏ ‏عَنْ ‏ ‏سَعْدِ بْنِ عُبَيْدَةَ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏قَالَ ‏ ‏كَانَ ‏ ‏عُمَرُ ‏ ‏يَحْلِفُ وَأَبِي فَنَهَاهُ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏مَنْ حَلَفَ بِشَيْءٍ دُونَ اللَّهِ تَعَالَى فَقَدْ أَشْرَكَ ‏ ‏وَقَالَ الْآخَرُ ‏ ‏وَهُوَ شِرْكٌ ‏","","",""],[4670,4670,"","আমি যেভাবে বিশ্বাস করতাম বা আমি কী বলেছিলাম, সেই বিষয়ে আমরা কথা বলেছিলাম । তোমার ভুলের কথা উল্লেখ করেছি, মেয়েদের আদেশ দিচ্ছি আমি।","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏أَخْبَرَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏إِسْمَاعِيلَ بْنِ أُمَيَّةَ ‏ ‏أَخْبَرَنِي ‏ ‏الثِّقَةُ ‏ ‏أَوْ مَنْ لَا أَتَّهِمُ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏أَنَّهُ خَطَبَ إِلَى نَسِيبٍ لَهُ ابْنَتَهُ قَالَ فَكَانَ هَوَى أُمِّ الْمَرْأَةِ فِي ‏ ‏ابْنِ عُمَرَ ‏ ‏وَكَانَ هَوَى أَبِيهَا فِي يَتِيمٍ لَهُ قَالَ فَزَوَّجَهَا الْأَبُ يَتِيمَهُ ذَلِكَ فَجَاءَتْ إِلَى النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَذَكَرَتْ ذَلِكَ لَهُ فَقَالَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَمِّرُوا النِّسَاءَ فِي بَنَاتِهِنَّ ‏","","",""],[4671,4671,"","তিনি বলেছিলেন, ঈশ্বর তাঁর জন্য প্রার্থনা করেছিলেন এবং তাকে এমন কাউকে দেননি, যাকে তিনি হয়তো তার সঙ্গে যেতে পারতেন না । আর তার মৃত্যু.","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏أَخْبَرَنَا ‏ ‏ابْنُ جُرَيْجٍ ‏ ‏أَخْبَرَنِي ‏ ‏عَطَاءٌ ‏ ‏عَنْ ‏ ‏حَبِيبِ بْنِ أَبِي ثَابِتٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏أَنَّهُ قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَا ‏ ‏عُمْرَى ‏ ‏وَلَا ‏ ‏رُقْبَى ‏ ‏فَمَنْ ‏ ‏أُعْمِرَ ‏ ‏شَيْئًا أَوْ ‏ ‏أُرْقِبَهُ ‏ ‏فَهُوَ لَهُ حَيَاتَهُ وَمَمَاتَهُ ‏","","",""],[4672,4672,"","আমার বাবা যে - সর্বোত্তমটা পেতে ইচ্ছুক ছিলেন, আমরা সেই সম্বন্ধে কথা বলেছিলাম ।","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الْعَزِيزِ بْنُ أَبِي رَوَّادٍ ‏ ‏عَنْ ‏ ‏نَافِعٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏قَالَ ‏ ‏كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَضَعُ فَصَّ خَاتَمِهِ فِي بَطْنِ الْكَفِّ ‏","","",""],[4673,4673,"","আমরা আমাদের জীবনের সেরাদের ব্যাপারে কথা বলেছি, আমার বাবার ছেলেকে নিজের ছেলের কাছে জয় করতে বলা। ঈশ্বর আপনার জন্য আশীর্বাদ নিয়ে আসবেন এবং তাঁর মৃত্যু থেকে তাকে অনুসরণ করবেন ।","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏أَخْبَرَنَا ‏ ‏ابْنُ أَبِي رَوَّادٍ ‏ ‏عَنْ ‏ ‏نَافِعٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏قَالَ ‏ ‏صَلَّى رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِي الْمَسْجِدِ فَرَأَى فِي الْقِبْلَةِ ‏ ‏نُخَامَةً ‏ ‏فَلَمَّا قَضَى صَلَاتَهُ قَالَ ‏ ‏إِنَّ أَحَدَكُمْ إِذَا صَلَّى فِي الْمَسْجِدِ فَإِنَّهُ ‏ ‏يُنَاجِي ‏ ‏رَبَّهُ وَإِنَّ اللَّهَ تَبَارَكَ وَتَعَالَى يَسْتَقْبِلُهُ بِوَجْهِهِ فَلَا ‏ ‏يَتَنَخَّمَنَّ ‏ ‏أَحَدُكُمْ فِي الْقِبْلَةِ وَلَا عَنْ يَمِينِهِ ثُمَّ دَعَا بِعُودٍ فَحَكَّهُ ثُمَّ دَعَا ‏ ‏بِخَلُوقٍ ‏ ‏فَخَضَبَهُ ‏","","",""],[4674,4674,"","আমাদের মধ্যে অধিকাংশই আমার বাবাকে এমন একটা ছেলে খুঁজতে খুঁজছিলেন, যাকে আমি দেখেছি । আমার প্রচারাভিযানে, কাফন, আর বলে এটা ঈশ্বর।","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏أَخْبَرَنَا ‏ ‏الثَّوْرِيُّ ‏ ‏عَنْ ‏ ‏أَبِي إِسْحَاقَ ‏ ‏عَنْ ‏ ‏مُجَاهِدٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏قَالَ ‏ ‏رَأَيْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَكْثَرَ مِنْ خَمْسٍ وَعِشْرِينَ مَرَّةً ‏ ‏أَوْ أَكْثَرَ مِنْ عِشْرِينَ مَرَّةً قَالَ ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏وَأَنَا أَشُكُّ ‏ ‏يَقْرَأُ فِي رَكْعَتَيْ الْفَجْرِ ‏ ‏قُلْ يَا أَيُّهَا الْكَافِرُونَ ‏ ‏وَ ‏ ‏قُلْ هُوَ اللَّهُ أَحَدٌ ‏","","",""],[4675,4675,"","আমার বাবা আমার কাছে সবচেয়ে ভালো মানুষ ছিলেন, আমার ছেলে আছে যে ভাববাদীকে তার পতাকা বা মানুষকে ঈশ্বরের কাছে পৌঁছে দিতে বলেছে। সে বলল কি হচ্ছে? সাক্ষীরা তার উপর ভালো খরচ করে আর একজন মানুষের শান্তি চায়, ক্ষমার চেষ্টা মানে আমাকে সুস্থ করা।","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏أَنْبَأَنَا ‏ ‏شَيْخٌ ‏ ‏مِنْ أَهْلِ ‏ ‏نَجْرَانَ ‏ ‏حَدَّثَنِي ‏ ‏مُحَمَّدُ بْنُ عَبْدِ الرَّحْمَنِ بْنِ الْبَيْلَمَانِيِّ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏أَنَّهُ سَأَلَ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَوْ أَنَّ رَجُلًا سَأَلَ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ ‏ ‏مَا الَّذِي يَجُوزُ فِي الرَّضَاعِ مِنْ الشُّهُودِ فَقَالَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏رَجُلٌ أَوْ امْرَأَةٌ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ أَبِي شَيْبَةَ ‏ ‏عَنْ ‏ ‏مُعْتَمِرٍ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ عُثَيْمٍ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ عَبْدِ الرَّحْمَنِ ‏ ‏يَعْنِي بِهَذَا الْحَدِيثِ ‏","","",""],[4676,4676,"","বাবা আমাদের সবচেয়ে ভালো কিছু করার চেষ্টা করেছিলেন আর আমরা আল্লাহ্‌র নামে বড় হওয়ার চেষ্টা করেছিলাম যে, আমার বাবা আমাদের সাথে কিছু করেছে। আমি নিশ্চিত যে, ঈশ্বর হলেন ঈশ্বরের পুত্র। আমি নিশ্চিত যে, আমি যদি কোনো একটা জিনিস চাই, তাহলে আমি শুধু একটা জিনিসও করতে পারি। যদি আমি আমার বাবা না বলি, আমি জানি যে, আমি আমার বাবা আমাদের বাবা আমাদের বাবা আমাদের সাথে নেই, আমি যদি আমার বাবা আমাদের সাথে নেই, আমি যদি আমার বাবাও না থাকতাম, তাহলে আমি শুধু একটা প্রশ্ন করি। আর আমি জানি যে, আমি কি করবো? আমি জানি যে, আমি জানি না যে, আমি জানি না যে, আমি এটা করতে পারি না যে, আমি জানি না যে, আমি শুধু একটা ছোট---------- আর আমি জানি যে, আমি জানি যে, আমি জানি যে, আমি জানি না। প্রত্যক্ষদর্শীরা কি বলেছে, একজন নারী ও মহিলা আদেশ।","‏ ‏قَالَ ‏ ‏أَبُو عَبْد الرَّحْمَنِ ‏ ‏و حَدَّثَنَا ‏ ‏أَبُو بَكْرٍ عَبْدُ اللَّهِ بْنُ أَبِي شَيْبَةَ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏مُعْتَمِرٌ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ عُثَيْمٍ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ عَبْدِ الرَّحْمَنِ بْنِ الْبَيْلَمَانِيِّ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏قَالَ ‏ ‏سُئِلَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَا يَجُوزُ فِي الرَّضَاعَةِ مِنْ الشُّهُودِ قَالَ رَجُلٌ وَامْرَأَةٌ ‏","","",""],[4677,4677,"","আমরা একটা কুত্তার বাচ্চাকে তার বাবার ব্যাপারে বলেছি, হয়তো আমি তাকে বলতে চাই সে ঈশ্বরের কাছে ভিক্ষা চেয়ে আছে সে জঙ্গলে পৌঁছে দিবে আর আমরা বলবো যে,","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏وَابْنُ بَكْرٍ ‏ ‏قَالَا أَخْبَرَنَا ‏ ‏ابْنُ جُرَيْجٍ ‏ ‏أَخْبَرَنِي ‏ ‏ابْنُ طَاوُسٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏أَنَّ رَجُلًا سَأَلَهُ فَقَالَ ‏ ‏أَنَهَى رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنْ ‏ ‏يُنْبَذَ ‏ ‏فِي ‏ ‏الْجَرِّ ‏ ‏وَالدُّبَّاءِ ‏ ‏قَالَ نَعَمْ ‏","","",""],[4678,4678,"","আমরা সবচেয়ে ভালো কথা বলেছি আমরা যা শুনেছি তা হলো একটা ষাঁড়ের ছেলে যে আমাকে বলেছে সে তাকে নাম দিয়েছে আর তাকে গাছ থেকে বের করে দেয়া হবে আর মানুষের ইচ্ছা আছে এটা বলার জন্য যে ভালো বন্ধুর বাবা আর ভালোর কথা শুনতে পান, তিনি বলেছেন যে তিনি তার প্রার্থনার শেষ করেছেন আর তাকে খোঁড়া আর বস্তা আর বস্তা আর বস্তা দিয়ে দেবেন তার কাছে আগুন লেগে গেলে সে তার এলাকায় আগুন লেগে যেতে পারে।","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏أَنْبَأَنَا ‏ ‏ابْنُ جُرَيْجٍ ‏ ‏أَخْبَرَنِي ‏ ‏أَبُو الزُّبَيْرِ ‏ ‏أَنَّهُ سَمِعَ ‏ ‏ابْنَ عُمَرَ ‏ ‏يَقُولُ ‏ ‏سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَنْهَى عَنْ ‏ ‏الْجَرِّ ‏ ‏وَالْمُزَفَّتِ ‏ ‏وَالدُّبَّاءِ ‏ ‏قَالَ ‏ ‏أَبُو الزُّبَيْرِ ‏ ‏وَسَمِعْتُ ‏ ‏جَابِرَ بْنَ عَبْدِ اللَّهِ ‏ ‏يَقُولُ ‏ ‏نَهَى رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَنْ ‏ ‏الْجَرِّ ‏ ‏وَالْمُزَفَّتِ ‏ ‏وَالنَّقِيرِ ‏ ‏وَكَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِذَا لَمْ يَجِدْ شَيْئًا ‏ ‏يُنْبَذُ ‏ ‏لَهُ فِيهِ ‏ ‏نُبِذَ ‏ ‏لَهُ فِي ‏ ‏تَوْرٍ ‏ ‏مِنْ حِجَارَةٍ ‏","","",""],[4679,4679,"","আমরা ছেলেদের সেরাটা নিয়ে কথা বলেছি... ...আমি কখনো স্টোনের ভালোবাসার কথা বলছি. তুমি.","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏أَخْبَرَنَا ‏ ‏مَعْمَرٌ ‏ ‏عَنْ ‏ ‏ثَابِتٍ الْبُنَانِيِّ ‏ ‏قَالَ ‏ ‏سَأَلْتُ ‏ ‏ابْنَ عُمَرَ ‏ ‏عَنْ ‏ ‏نَبِيذِ ‏ ‏الْجَرِّ ‏ ‏فَقَالَ حَرَامٌ فَقُلْتُ ‏ ‏أَنَهَى عَنْهُ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ ‏ ‏ابْنُ عُمَرَ ‏ ‏يَزْعُمُونَ ذَلِكَ ‏","","",""],[4680,4680,"","আমরা বলেছিলাম, তিনি কি করতে হবে।","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏أَخْبَرَنَا ‏ ‏مَعْمَرٌ ‏ ‏عَنْ ‏ ‏أَيُّوبَ ‏ ‏عَنْ ‏ ‏نَافِعٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏مَنْ شَرِبَ الْخَمْرَ فِي الدُّنْيَا ثُمَّ مَاتَ وَهُوَ يَشْرَبُهَا لَمْ يَتُبْ مِنْهَا حَرَّمَهَا اللَّهُ عَلَيْهِ فِي الْآخِرَةِ ‏","","",""],[4681,4681,"","আমি ঈশ্বরের কাছে একটা ছেলেকে দেওয়ার বিষয়ে কথা বলেছিলাম । খুন করার দিন... ...আর তারপর সে তার হৃদয় হারিয়ে ফেলত.","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏حَدَّثَنَا ‏ ‏مَعْمَرٌ ‏ ‏عَنْ ‏ ‏عَطَاءِ بْنِ السَّائِبِ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ عُبَيْدِ بْنِ عُمَيْرٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏مَنْ شَرِبَ الْخَمْرَ لَمْ تُقْبَلْ ‏ ‏لَهُ صَلَاةٌ ‏ ‏أَرْبَعِينَ لَيْلَةً فَإِنْ تَابَ تَابَ اللَّهُ عَلَيْهِ فَإِنْ عَادَ كَانَ حَقًّا عَلَى اللَّهِ تَعَالَى أَنْ يَسْقِيَهُ مِنْ نَهَرِ ‏ ‏الْخَبَالِ ‏ ‏قِيلَ وَمَا نَهَرُ الْخَبَالِ قَالَ صَدِيدُ أَهْلِ النَّارِ ‏","","",""],[4682,4682,"","তিনি বলেছিলেন যে, সিঁড়িতে সেলাই না করে সেলাই না দিয়ে তিনি বলেছিলেন যে, তিনি সিঁড়িতে সেলাই করবেন না ।","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏حَدَّثَنَا ‏ ‏مَعْمَرٌ ‏ ‏عَنْ ‏ ‏أَيُّوبَ ‏ ‏عَنْ ‏ ‏نَافِعٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏لَا ‏ ‏شِغَارَ ‏ ‏فِي الْإِسْلَامِ ‏","","",""],[4683,4683,"","আমরা ঈশ্বরের সেরাটার ব্যাপারে কথা বলেছি, যিনি পাস করেছেন তার ছেলের জন্য সৌভাগ্য বয়ে এনেছে।","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏أَخْبَرَنَا ‏ ‏مَعْمَرٌ ‏ ‏عَنْ ‏ ‏عُبَيْدِ اللَّهِ بْنِ عُمَرَ ‏ ‏عَنْ ‏ ‏نَافِعٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏قَالَ ‏ ‏كَانَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَخْطُبُ يَوْمَ الْجُمُعَةِ مَرَّتَيْنِ بَيْنَهُمَا جَلْسَةٌ ‏","","",""],[4684,4684,"","আমরা আমাদের সেরাদের কথা বলেছি একটি ছেলের জন্য ফুল সম্পর্কে যে এটা শুনেছিলো। ঈশ্বর তা দিয়েছেন এবং যারা আপনার কাছ থেকে এসেছে তাদের মঙ্গলের জন্য এটা ভাল। আমরা আপনাদের কাছে এসেছি। আমরা আমাদের কাছে এটা একটি সুন্দর জিনিস আছে, যেটিকে আমরা সবচেয়ে ভাল উপায়ে উপস্থাপন করেছি। আমরা আমাদের কাছে এসেছি। আমরা যা আছে, তা হল, আমরা আপনাকে বলছি, আমরা যা বলছি, আমরা সত্যিই বলছি, আমরা সত্যিই বলছি, আমরা আমাদের জন্য, আমরা যা করেছি এবং আমরা যা করেছি তা হল সেই সমস্ত লোকের কথা। আমরা যা করেছি, এবং আমরা জানি, আমরা যখন আমরা তা হল সেই অনুসারে বলি, আমরা আমাদের কাছে এটা করি,","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏أَخْبَرَنَا ‏ ‏مَعْمَرٌ ‏ ‏عَنِ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنْ ‏ ‏سَالِمٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏قَالَ ‏ ‏سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَهُوَ عَلَى الْمِنْبَرِ يَقُولُ ‏ ‏مَنْ جَاءَ مِنْكُمْ الْجُمُعَةَ فَلْيَغْتَسِلْ ‏","","",""],[4685,4685,"","আমরা যে সমস্ত দলের কথা বলেছি তাদের মধ্যে আমরা সবচেয়ে ভাল কথা বলেছি, যেমন আমরা এমন এক ছেলের কথা বলছিলাম, যে কিনা কিনা কিনা করতে চেষ্টা করছিল । বাড়ি।","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏حَدَّثَنَا ‏ ‏مَعْمَرٌ ‏ ‏عَنْ ‏ ‏أَيُّوبَ ‏ ‏عَنْ ‏ ‏نَافِعٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏قَالَ ‏ ‏كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يُصَلِّي بَعْدَ الْجُمُعَةِ رَكْعَتَيْنِ فِي بَيْتِهِ ‏","","",""],[4686,4686,"","আমরা দলের মধ্যে সব থেকে ভালো কথা বলেছি একটা ছেলে যে আমাকে কেন ভালোবাসি সে সম্পর্কে যে কথা বলে, সে দুই বছর থেকে মুক্তি পাবে তাকে তার মৃত্যুর মুখে সতর্ক করে দিতে হবে, সে আমার সাথে প্রতিবেশী যে তাকে মরতে দিতে যাচ্ছে, আমরা হয়তো বাইরে চলে যেতাম, আর তারা বলে আমরা ঈশ্বরের কাছে প্রার্থনা করব তার জন্য এবং তাকে বলতে বলা হয়েছে সে চলে গেছে, আমি তাকে পাঠিয়েছি","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏حَدَّثَنَا ‏ ‏مَعْمَرٌ ‏ ‏عَنْ ‏ ‏أَيُّوبَ ‏ ‏عَنْ ‏ ‏نَافِعٍ ‏ ‏عَنْ ‏ ‏ابْنِ عُمَرَ ‏ ‏قَالَ ‏ ‏لَمَّا قَفَلَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مِنْ ‏ ‏حُنَيْنٍ ‏ ‏سَأَلَ ‏ ‏عُمَرُ ‏ ‏عَنْ نَذْرٍ كَانَ نَذَرَهُ فِي الْجَاهِلِيَّةِ اعْتِكَافُ يَوْمٍ ‏ ‏فَأَمَرَ بِهِ فَانْطَلَقَ ‏ ‏عُمَرُ ‏ ‏بَيْنَ يَدَيْهِ قَالَ وَبَعَثَ مَعِي بِجَارِيَةٍ كَانَ أَصَابَهَا يَوْمَ ‏ ‏حُنَيْنٍ ‏ ‏قَالَ فَجَعَلْتُهَا فِي بَعْضِ بُيُوتِ ‏ ‏الْأَعْرَابِ ‏ ‏حِينَ نَزَلْتُ فَإِذَا أَنَا بِسَبْيِ ‏ ‏حُنَيْنٍ ‏ ‏قَدْ خَرَجُوا يَسْعَوْنَ يَقُولُونَ أَعْتَقَنَا رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ فَقَالَ ‏ ‏عُمَرُ ‏ ‏لِعَبْدِ اللَّهِ ‏ ‏اذْهَبْ فَأَرْسِلْهَا قَالَ فَذَهَبْتُ فَأَرْسَلْتُهَا ‏","","",""],[4687,4687,"","আমরা কথা বলেছিলাম কিভাবে আমরা একে অপরের সাথে কথা বলেছিলাম যে সে ঈশ্বরকে যা বলেছে তার জন্য যে সে তার কাছে বলেছে তাকে ছেড়ে দিতে হবে। যদি তাকে কোরআনের মতো গ্রহণ করতে হয়, তাহলে তাকে তার মন দিয়ে পড়তে হবে আর সব ভেঙ্গে ফেলা হবে। আর যদি আমি তাকে তালাক দেই সে এটা নিয়ে কাউবয়দের সাথে এমন করবে।","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏أَخْبَرَنَا ‏ ‏مَعْمَرٌ ‏ ‏عَنْ ‏ ‏أَيُّوبَ ‏ ‏عَنْ ‏ ‏نَافِعٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَثَلُ الْقُرْآنِ إِذَا ‏ ‏عَاهَدَ ‏ ‏عَلَيْهِ صَاحِبُهُ فَقَرَأَهُ بِاللَّيْلِ وَالنَّهَارِ كَمَثَلِ رَجُلٍ لَهُ إِبِلٌ فَإِنْ ‏ ‏عَقَلَهَا ‏ ‏حَفِظَهَا وَإِنْ أَطْلَقَ ‏ ‏عُقُلَهَا ‏ ‏ذَهَبَتْ فَكَذَلِكَ صَاحِبُ الْقُرْآنِ ‏","","",""],[4688,4688,"","আমরা সেই দলের মধ্যে সবচেয়ে ভাল একটা সম্বন্ধে কথা বলেছিলাম, যারা ঈশ্বরকে বলেছিল । ঈশ্বরের টাকা রাত আর দিন অতিবাহিত হয়।","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏حَدَّثَنَا ‏ ‏مَعْمَرٌ ‏ ‏عَنِ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنْ ‏ ‏سَالِمٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَا حَسَدَ إِلَّا عَلَى اثْنَتَيْنِ رَجُلٌ آتَاهُ اللَّهُ الْقُرْآنَ فَهُوَ يَقُومُ بِهِ ‏ ‏آنَاءَ ‏ ‏اللَّيْلِ ‏ ‏وَآنَاءَ ‏ ‏النَّهَارِ وَرَجُلٌ آتَاهُ اللَّهُ مَالًا فَهُوَ يُنْفِقُ مِنْهُ ‏ ‏آنَاءَ ‏ ‏اللَّيْلِ ‏ ‏وَآنَاءَ ‏ ‏النَّهَارِ ‏","","",""],[4689,4689,"","আমরা সময়ের সেরা কথা বলেছি একটি ছেলে নিয়ে যে দেবী ছিল সে রাতের দশম চাঁদ ছেড়ে দেবে মেঘের অভাব।","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏حَدَّثَنَا ‏ ‏مَعْمَرٌ ‏ ‏عَنْ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنْ ‏ ‏سَالِمٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏الْتَمِسُوا ‏ ‏لَيْلَةَ الْقَدْرِ فِي الْعَشْرِ ‏ ‏الْغَوَابِرِ ‏ ‏فِي التِّسْعِ ‏ ‏الْغَوَابِرِ ‏","","",""],[4690,4690,"","আমরা আমাদের ছেলের জন্য ভালো নাম পেয়ে সবচেয়ে ভালোর কথা বলেছিলাম। হাম্মুস ফিরে গিয়ে নিজের চোখে দেখে, সে নিজেই এসে আইমকে এলো যেটা কোন ব্লাস্ট হতে পারেনি। মানে পাথর আর পাথরকে হত্যা করা ১০০ বার আমি ফিরে আসতে পারি। তার নিজের দেশে অথবা নিজের দেশে।","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏حَدَّثَنَا ‏ ‏مَعْمَرٌ ‏ ‏عَنْ ‏ ‏عَلِيِّ بْنِ زَيْدِ بْنِ جُدْعَانَ ‏ ‏عَنِ ‏ ‏الْقَاسِمِ بْنِ رَبِيعَةَ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏قَالَ ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏كَانَ مَرَّةً يَقُولُ ‏ ‏ابْنِ مُحَمَّدٍ ‏ ‏وَمَرَّةً يَقُولُ ‏ ‏ابْنِ رَبِيعَةَ ‏ ‏قَالَ ‏ ‏سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ وَهُوَ عَلَى دَرَجِ ‏ ‏الْكَعْبَةِ ‏ ‏الْحَمْدُ لِلَّهِ الَّذِي أَنْجَزَ وَعْدَهُ وَنَصَرَ عَبْدَهُ وَهَزَمَ الْأَحْزَابَ وَحْدَهُ أَلَا وَإِنَّ كُلَّ مَأْثُرَةٍ كَانَتْ فِي الْجَاهِلِيَّةِ فَإِنَّهَا تَحْتَ قَدَمَيَّ الْيَوْمَ إِلَّا مَا كَانَ مِنْ ‏ ‏سِدَانَةِ ‏ ‏الْبَيْتِ ‏ ‏وَسِقَايَةِ ‏ ‏الْحَاجِّ أَلَا وَإِنَّ مَا بَيْنَ الْعَمْدِ وَالْخَطَإِ وَالْقَتْلِ بِالسَّوْطِ وَالْحَجَرِ فِيهَا مِائَةُ بَعِيرٍ مِنْهَا أَرْبَعُونَ فِي بُطُونِهَا أَوْلَادُهَا ‏","","",""],[4691,4691,"","আমরা তাদের কথা বলেছিলাম যেন তারা ঈশ্বরের ভালবাসার প্রধান ব্যক্তি হয়ে ওঠে।","‏ ‏حَدَّثَنَا ‏ ‏إِبْرَاهِيمُ بْنُ خَالِدٍ ‏ ‏حَدَّثَنَا ‏ ‏رَبَاحٌ ‏ ‏عَنْ ‏ ‏مَعْمَرٍ ‏ ‏عَنِ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنْ ‏ ‏حَمْزَةَ بْنِ عَبْدِ اللَّهِ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏الشُّؤْمُ فِي ثَلَاثٍ الْفَرَسِ وَالْمَرْأَةِ وَالدَّارِ ‏","","",""],[4692,4692,"","আমরা ম্যাক কারির বন্ধুত্ব নিয়ে কথা বলেছি আমরা হয়ত ওমারের মাধ্যমে এসেছি, ঈশ্বর আপনাকে তার কাছে সমর্পণ করেছেন, মানুষ হত্যা করার পরিকল্পনা করেছেন, অথবা আপনার নিজের লোককে হত্যা করেছে সার্ভিস, সে কি পেয়েছে, ঈশ্বরের কাছে, তোমার মধ্যে কিছু গরু আছে কিনা সেটা নিয়ে কিছু খেলে না।","‏ ‏حَدَّثَنَا ‏ ‏إِبْرَاهِيمُ بْنُ خَالِدٍ ‏ ‏حَدَّثَنَا ‏ ‏رَبَاحٌ ‏ ‏عَنْ ‏ ‏مَعْمَرٍ ‏ ‏عَنْ ‏ ‏صَدَقَةَ الْمَكِّيِّ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ عُمَرَ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏اعْتَكَفَ ‏ ‏وَخَطَبَ النَّاسَ فَقَالَ ‏ ‏أَمَا إِنَّ أَحَدَكُمْ إِذَا قَامَ فِي الصَّلَاةِ فَإِنَّهُ ‏ ‏يُنَاجِي ‏ ‏رَبَّهُ فَلْيَعْلَمْ أَحَدُكُمْ مَا ‏ ‏يُنَاجِي ‏ ‏رَبَّهُ وَلَا يَجْهَرْ بَعْضُكُمْ عَلَى بَعْضٍ بِالْقِرَاءَةِ فِي الصَّلَاةِ ‏","","",""],[4693,4693,"","ঈশ্বরের সঙ্গে শান্তি বজায় রেখে আমরা কি একজন পাপীকে ঘুমাই, যে তার আলো জ্বালিয়ে দিয়েছে আমি এমন কিছু করতে চাই যা তার জন্য সবচেয়ে ভালো কিছু করতে তোমার আলো, আমি দুঃখিত, সে আত্মসমর্পণ করেছে।","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏حَدَّثَنَا ‏ ‏عُبَيْدُ اللَّهِ بْنُ عُمَرَ ‏ ‏عَنْ ‏ ‏نَافِعٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏أَنَّ ‏ ‏عُمَرَ ‏ ‏سَأَلَ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏هَلْ يَنَامُ أَحَدُنَا وَهُوَ ‏ ‏جُنُبٌ ‏ ‏فَقَالَ نَعَمْ وَيَتَوَضَّأُ وُضُوءَهُ لِلصَّلَاةِ ‏ ‏قَالَ ‏ ‏نَافِعٌ ‏ ‏فَكَانَ ‏ ‏ابْنُ عُمَرَ ‏ ‏إِذَا أَرَادَ أَنْ يَفْعَلَ شَيْئًا مِنْ ذَلِكَ تَوَضَّأَ وُضُوءَهُ لِلصَّلَاةِ ‏ ‏مَا خَلَا ‏ ‏رِجْلَيْهِ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏حَدَّثَنِي ‏ ‏مَعْمَرٌ ‏ ‏عَنْ ‏ ‏أَيُّوبَ ‏ ‏عَنْ ‏ ‏نَافِعٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مِثْلَهُ أَنَّ ‏ ‏عُمَرَ ‏ ‏سَأَلَ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏","","",""],[4694,4694,"","ঈশ্বর তাদের কাছে প্রতিজ্ঞা করেছেন যে, তোমাদের একজনকে স্পর্শ করার জন্য আমাকে পাঠানো হবে ।","‏ ‏حَدَّثَنَا ‏ ‏إِبْرَاهِيمُ بْنُ خَالِدٍ ‏ ‏حَدَّثَنَا ‏ ‏رَبَاحٌ ‏ ‏عَنْ ‏ ‏مَعْمَرٍ ‏ ‏عَنْ ‏ ‏أَيُّوبَ ‏ ‏عَنْ ‏ ‏نَافِعٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏نَهَى أَنْ ‏ ‏يَتَحَرَّى ‏ ‏أَحَدُكُمْ غُرُوبَ الشَّمْسِ فَيُصَلِّيَ عِنْدَ ذَلِكَ ‏","","",""],[4695,4695,"","আমরা তাদের সাথে একটা ঘোড়ার সাথে কথা বলেছি, যে এক ছেলের সাথে একটা ছেলে যে তার কাছে প্রার্থনা করেছিল, সে বলল যে, আল্লাহ তার কাছে প্রার্থনা করা বন্ধ করবেন না।","‏ ‏حَدَّثَنَا ‏ ‏إِبْرَاهِيمُ بْنُ خَالِدٍ ‏ ‏حَدَّثَنَا ‏ ‏رَبَاحٌ ‏ ‏عَنْ ‏ ‏مَعْمَرٍ ‏ ‏عَنْ ‏ ‏أَيُّوبَ ‏ ‏عَنْ ‏ ‏نَافِعٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَا تَمْنَعُوا ‏ ‏إِمَاءَ ‏ ‏اللَّهِ أَنْ يَأْتِينَ ‏ ‏أَوْ قَالَ يُصَلِّينَ فِي ‏ ‏الْمَسْجِدِ ‏","","",""],[4696,4696,"","আমরা তাদের কথা বলেছিলাম, আমার বাবার ভালবাসা এক চমৎকার ভালবাসার জন্য আমার বাবার ভালোবাসার প্রধান। ঈশ্বর তাঁর জন্য প্রার্থনা করেছেন এবং তিনি বলবেন, কোন মানুষ ঘুম থেকে রক্ষা পাবে না, ঈশ্বর। আমরা যখন তাদের থামালাম, তখন তিনি বলেছিলেন যে ঈশ্বর, ঈশ্বর, ঈশ্বর, ঈশ্বর, ঈশ্বর, ঈশ্বর, ঈশ্বর, ঈশ্বর, ঈশ্বর, ঈশ্বর, ঈশ্বর, ঈশ্বর, ঈশ্বর, ঈশ্বর, ঈশ্বর, ঈশ্বর, ঈশ্বর, ঈশ্বর, ঈশ্বর, ঈশ্বর, ঈশ্বর, খোদা, ঈশ্বর \"গো, যাও!\" সে ঈশ্বরের সাথে কথা বলেছে, যখন সে মারা গিয়েছিল।","‏ ‏حَدَّثَنَا ‏ ‏إِبْرَاهِيمُ بْنُ خَالِدٍ ‏ ‏حَدَّثَنَا ‏ ‏رَبَاحٌ ‏ ‏حَدَّثَنِي ‏ ‏عُمَرُ بْنُ حَبِيبٍ ‏ ‏عَنِ ‏ ‏ابْنِ أَبِي نَجِيحٍ ‏ ‏عَنْ ‏ ‏مُجَاهِدٍ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ عُمَرَ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏لَا يَمْنَعَنَّ رَجُلٌ أَهْلَهُ أَنْ يَأْتُوا الْمَسَاجِدَ ‏ ‏فَقَالَ ‏ ‏ابْنٌ لِعَبْدِ اللَّهِ بْنِ عُمَرَ ‏ ‏فَإِنَّا نَمْنَعُهُنَّ قَالَ ‏ ‏عَبْدُ اللَّهِ ‏ ‏أُحَدِّثُكَ عَنْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَتَقُولُ هَذَا قَالَ فَمَا كَلَّمَهُ ‏ ‏عَبْدُ اللَّهِ ‏ ‏حَتَّى مَاتَ ‏","","",""],[4697,4697,"","আমি যে - লোকেদের কাছে ছিলাম তাদের মধ্যে সবচেয়ে ভালটা নিয়ে কথা বলেছিলাম । আকাশ ভেঙ্গে গেছে আর আকাশ ভেঙ্গে গেছে।","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏أَخْبَرَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ بَحِيرٍ الْقَاصُّ ‏ ‏أَنَّ ‏ ‏عَبْدَ الرَّحْمَنِ بْنَ يَزِيدَ الصَّنْعَانِيَّ ‏ ‏أَخْبَرَهُ أَنَّهُ سَمِعَ ‏ ‏ابْنَ عُمَرَ ‏ ‏يَقُولُ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَنْ سَرَّهُ أَنْ يَنْظُرَ إِلَى يَوْمِ الْقِيَامَةِ كَأَنَّهُ رَأْيُ عَيْنٍ فَلْيَقْرَأْ ‏ ‏إِذَا الشَّمْسُ ‏ ‏كُوِّرَتْ ‏ ‏وَ ‏ ‏إِذَا السَّمَاءُ انْفَطَرَتْ ‏ ‏وَ ‏ ‏إِذَا السَّمَاءُ انْشَقَّتْ ‏ ‏وَأَحْسَبُهُ قَالَ وَسُورَةَ ‏ ‏هُودٍ ‏","","",""],[4698,4698,"","আমরা একটি মহান মন নিয়ে কথা বলেছি... ...আমাদের বলতে হবে আমি কতটা খারাপ ছিলাম। লর্ড তার জন্য প্রার্থনা করেছিল এবং তার মূল্যবান যাত্রা শেষ না হওয়া পর্যন্ত আমি আত্মসমর্পণ করব।","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ بَكْرٍ ‏ ‏أَخْبَرَنَا ‏ ‏ابْنُ جُرَيْجٍ ‏ ‏أَخْبَرَنِي ‏ ‏صَالِحُ بْنُ كَيْسَانَ ‏ ‏عَنْ ‏ ‏نَافِعٍ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ عُمَرَ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَهَلَّ ‏ ‏حِينَ ‏ ‏اسْتَوَتْ ‏ ‏بِهِ ‏ ‏رَاحِلَتُهُ ‏ ‏قَائِمَةً ‏","","",""],[4699,4699,"","আমরা আমাদের কথা বলেছিলাম কত মানুষ বলেছে যে তিনি বলছেন যে তিনি ঈশ্বর মুক্তির জন্য... ...আর আমি তিন দিন থেকে তোমাদের ত্যাগ করব না।","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ بَكْرٍ ‏ ‏أَخْبَرَنَا ‏ ‏ابْنُ جُرَيْجٍ ‏ ‏قَالَ أَخْبَرَنِي ‏ ‏نَافِعٌ ‏ ‏أَنَّ ‏ ‏ابْنَ عُمَرَ ‏ ‏كَانَ يَقُولُ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَا يَأْكُلْ أَحَدُكُمْ مِنْ أُضْحِيَّتِهِ فَوْقَ ثَلَاثَةِ أَيَّامٍ ‏","","",""],[4700,4700,"","আমরা একটি মহান বিয়ার সম্পর্কে কথা বলেছি, কিভাবে প্রভু শুনতে হবে সে পাঁচ বছর আগে দরজা থেকে হত্যা করবে, খুনিরা বনের ভেতরে আর অন্ধকারের আগুনে নয়. ফ্ল্যাশ.","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ بَكْرٍ ‏ ‏أَخْبَرَنَا ‏ ‏ابْنُ جُرَيْجٍ ‏ ‏قَالَ قَالَ لِي ‏ ‏نَافِعٌ ‏ ‏قَالَ ‏ ‏عَبْدُ اللَّهِ ‏ ‏سَمِعْتُ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏يُقْتَلُ مِنْ الدَّوَابِّ خَمْسٌ لَا ‏ ‏جُنَاحَ ‏ ‏عَلَى مَنْ قَتَلَهُنَّ فِي قَتْلِهِنَّ الْغُرَابُ وَالْحِدَأَةُ وَالْعَقْرَبُ وَالْكَلْبُ ‏ ‏الْعَقُورُ ‏ ‏وَالْفَأْرَةُ ‏","","",""],[4701,4701,"","আমরা একটি মহান বুলেটিনের সাথে কথা বলেছি যে আমাদের ঈশ্বরকে ভালোবাসার কথা বলেছে, ঈশ্বরকে প্রার্থনা করতে বলা হয়েছে, ঈশ্বরকে তাঁর উদ্ধার করতে হবে এবং প্রভুর ভাগ্য উদ্ধার করতে হবে।","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ بَكْرٍ ‏ ‏أَخْبَرَنَا ‏ ‏ابْنُ جُرَيْجٍ ‏ ‏حَدَّثَنِي ‏ ‏الزُّهْرِيُّ ‏ ‏عَنْ ‏ ‏حَدِيثِ ‏ ‏سَالِمِ بْنِ عَبْدِ اللَّهِ ‏ ‏أَنَّ ‏ ‏عَبْدَ اللَّهِ بْنَ عُمَرَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏الْتَمِسُوا ‏ ‏لَيْلَةَ الْقَدْرِ فِي السَّبْعِ الْأَوَاخِرِ مِنْ شَهْرِ رَمَضَانَ ‏","","",""],[4702,4702,"","আমরা একটা কুত্তার সবচেয়ে ভালো ছেলের কথা বলেছিলাম... ...আমি তাকে বলেছিলাম যে খোদা যেন ঈশ্বরের অন্ত্যেষ্টিক্রিয়ায় হেঁটে যায়, আর আল্লাহ ঈশ্বর তাকে উদ্ধার করেছেন, তারপর সে তার মায়ের মাকে গুলি করবে। গলা থেকে একটা ঝগড়ার শব্দও করেছি যে আমার সাথে কথা বলেছে, এমন একটা ছেলের কথা আমি পড়েছি যার ছেলে তার মত বয়স হয়ে গেছে","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏وَابْنُ بَكْرٍ ‏ ‏قَالَا أَخْبَرَنَا ‏ ‏ابْنُ جُرَيْجٍ ‏ ‏قَالَ قَالَ ‏ ‏ابْنُ شِهَابٍ ‏ ‏حَدَّثَنِي ‏ ‏سَالِمُ بْنُ عَبْدِ اللَّهِ ‏ ‏أَنَّ ‏ ‏عَبْدَ اللَّهِ بْنَ عُمَرَ ‏ ‏كَانَ يَمْشِي بَيْنَ يَدَيْ الْجِنَازَةِ وَقَدْ ‏ ‏كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَأَبُو بَكْرٍ ‏ ‏وَعُمَرُ ‏ ‏وَعُثْمَانُ ‏ ‏يَمْشُونَ أَمَامَهَا ‏ ‏حَدَّثَنَا ‏ ‏حَجَّاجٌ ‏ ‏قَالَ قَرَأْتُ عَلَى ‏ ‏ابْنِ جُرَيْجٍ ‏ ‏حَدَّثَنِي ‏ ‏زِيَادٌ يَعْنِي ابْنَ سَعْدٍ ‏ ‏عَنِ ‏ ‏ابْنِ شِهَابٍ ‏ ‏عَنْ ‏ ‏سَالِمٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏مِثْلَهُ ‏","","",""],[4703,4703,"","আমি আমার ছেলের স্বপ্নের অর্থ বুঝতে পেরেছিলাম যে, ঈশ্বর আমাদের কাছ থেকে কী চান । সুরটা হচ্ছে সূর্যকে পড়া।","‏ ‏حَدَّثَنَا ‏ ‏إِبْرَاهِيمُ بْنُ خَالِدٍ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ بَحِيرٍ ‏ ‏عَنْ ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ يَزِيدَ ‏ ‏وَكَانَ مِنْ أَهْلِ ‏ ‏صَنْعَاءَ ‏ ‏وَكَانَ أَعْلَمَ بِالْحَلَالِ وَالْحَرَامِ مِنْ ‏ ‏وَهْبٍ يَعْنِي ابْنَ مُنَبِّهٍ ‏ ‏قَالَ سَمِعْتُ ‏ ‏ابْنَ عُمَرَ ‏ ‏يَقُولُ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَنْ أَحَبَّ أَنْ يَنْظُرَ إِلَى يَوْمِ الْقِيَامَةِ فَلْيَقْرَأْ ‏ ‏إِذَا الشَّمْسُ ‏ ‏كُوِّرَتْ ‏","","",""],[4704,4704,"","আমরা ঈশ্বরের পুত্র একটি পুত্র জন্য কথা বলেছি যে একটি পুত্র যে শুনেছেন যে তিনি বলেছেন যে তিনি ঈশ্বরের দোহাই জন্য প্রার্থনা করবেন এবং ঈশ্বরের দোহাই জন্য নয়.","‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ دِينَارٍ ‏ ‏سَمِعَ ‏ ‏ابْنَ عُمَرَ ‏ ‏يَقُولُ ‏ ‏سَمِعْتُ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ عَلَى الْمِنْبَرِ ‏ ‏مَنْ جَاءَ مِنْكُمْ الْجُمُعَةَ فَلْيَغْتَسِلْ ‏","","",""],[4705,4705,"","আমরা দুই বছর ধরে একটা ছেলের ছেলের জন্য দুই বছর করেছি, যে বলেছে সে ঈশ্বরের দোহাই দিয়ে গেছে আর আল্লাহ তার বন্ধু।","‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنِ ‏ ‏ابْنِ دِينَارٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏قَالَ ‏ ‏نَهَى رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَنْ الثَّمَرِ أَنْ يُبَاعَ حَتَّى ‏ ‏يَبْدُوَ ‏ ‏صَلَاحُهُ ‏","","",""],[4706,4706,"","আমরা একটি ছেলের জন্য দুইটা জীবন করেছি, যে বলছে আল্লাহ ঈশ্বরের শান্তি পান করেছে আর তিনিই হবেন সেই ব্যক্তি যে হবে সেই হবে যে লোক এই জন ্ য বেঁচে থাকবে সে-ই তবে যে ব ্ যক ্ তি হবে নিরাপদ , সে-ই হবে ক ্ ষমতার অধিকারী । রাজা হতে হবে, আমি প্রত্যেক কুকুর, স্নাইপার অথবা কুকুরকে ব্যয় করেছি, যে ভাড়ার টাকা খুব ভালো.","‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ دِينَارٍ ‏ ‏سَمِعْتُ ‏ ‏ابْنَ عُمَرَ ‏ ‏يَقُولُ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَنْ ‏ ‏اقْتَنَى ‏ ‏كَلْبًا إِلَّا كَلْبَ مَاشِيَةٍ أَوْ كَلْبَ ‏ ‏قَنْصٍ ‏ ‏نَقَصَ مِنْ أَجْرِهِ كُلَّ يَوْمٍ ‏ ‏قِيرَاطَانِ ‏","","",""],[4707,4707,"","আমরা দুই বছর ধরে কথা বলেছি তুমি একটা ভালো কাপুরুষের সাথে থাকলে... ...আমি এমন একজন লোকের ছেলে যে আমাকে মৃত্যুর আদেশ দিয়েছিল, ঈশ্বর তার কাছে প্রার্থনা করে তাকে আত্মসমর্পণ করবেন ভাই, আমি সবচেয়ে জরুরী ব্যক্তি হবো যে তুমি তোমার সাথে মিথ্যা বলেছিলে।","‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏أَيُّوبَ ‏ ‏عَنْ ‏ ‏سَعِيدِ بْنِ جُبَيْرٍ ‏ ‏قَالَ ‏ ‏قُلْتُ ‏ ‏لِابْنِ عُمَرَ ‏ ‏رَجُلٌ ‏ ‏لَاعَنَ ‏ ‏امْرَأَتَهُ فَقَالَ ‏ ‏فَرَّقَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بَيْنَ أَخَوَيْ ‏ ‏بَنِي الْعَجْلَانِ ‏ ‏وَقَالَ إِنَّ أَحَدَكُمَا كَاذِبٌ فَهَلْ مِنْكُمَا تَائِبٌ ثَلَاثًا ‏","","",""],[4708,4708,"","আমরা হামাদের নাম বলেছি যেখানে তিনি আমাকে ঈশ্বরের কাছে একটি ছেলের জন্য একটা কথা বলেছিলেন যে ঈশ্বরকে পাঠানো হয়েছে। তিনি এমন কাজ করতেন যাতে তিনি এক বছর ধরে কোন জায়গা থেকে বের হতে বা অন্য কোথাও যেতে পারেন। কবিতা দিয়ে দৌড়াচ্ছে।","‏ ‏حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ أُسَامَةَ ‏ ‏قَالَ ‏ ‏عُبَيْدُ اللَّهِ ‏ ‏أَخْبَرَنِي ‏ ‏نَافِعٌ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَامَلَ أَهْلَ ‏ ‏خَيْبَرَ ‏ ‏بِشَطْرِ ‏ ‏مَا خَرَجَ مِنْ زَرْعٍ أَوْ تَمْرٍ فَكَانَ يُعْطِي أَزْوَاجَهُ كُلَّ عَامٍ مِائَةَ ‏ ‏وَسْقٍ ‏ ‏وَثَمَانِينَ ‏ ‏وَسْقًا ‏ ‏مِنْ تَمْرٍ وَعِشْرِينَ ‏ ‏وَسْقًا ‏ ‏مِنْ شَعِيرٍ ‏","","",""],[4709,4709,"","আমরা ঈশ্বরের লর্ড বানের একজন চাকরের কথা বলেছি, যে ঈশ্বরের অনুগ্রহ লাভ করেছে, আমি একজন সহপাঠীর সাথে দেখা করেছি যে তার পর্দার উপর দিয়ে এসেছে।","‏ ‏حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ أُسَامَةَ ‏ ‏عَنْ ‏ ‏عُبَيْدِ اللَّهِ بْنِ عُمَرَ ‏ ‏عَنْ ‏ ‏نَافِعٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ ‏ ‏إِذَا أَدْخَلَ رِجْلَهُ فِي ‏ ‏الْغَرْزِ ‏ ‏وَاسْتَوَتْ ‏ ‏بِهِ نَاقَتُهُ قَائِمَةً ‏ ‏أَهَلَّ ‏ ‏مِنْ عِنْدِ مَسْجِدِ ‏ ‏ذِي الْحُلَيْفَةِ ‏","","",""],[4710,4710,"","আমরা ঈশ্বরের দাসের কথা বলেছি, আমাদের সাথে একজন সুমন্ত্রী ছেলে আছে যে আমাদের সাথে কথা বলেছে, ঈশ্বরের নামে কথা বলেছে, আমি ঈশ্বরের কাছে প্রার্থনা করবো আর সে মাস্কির নামে তার নাম সরিয়ে দেবে লোকেরা আপনাকে আশীর্বাদ করেছিল এবং আমি যা বলি, তা না বলে বরং তা প্রকাশ করে দিয়েছিল ।","‏ ‏حَدَّثَنَا ‏ ‏حَمَّادٌ ‏ ‏قَالَ ‏ ‏عُبَيْدُ اللَّهِ ‏ ‏أَخْبَرَنَا ‏ ‏وَمُحَمَّدُ بْنُ بِشْرٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏عُبَيْدُ اللَّهِ ‏ ‏عَنْ ‏ ‏نَافِعٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏ذَكَرَ ‏ ‏الْمَسِيحَ ‏ ‏قَالَ ‏ ‏ابْنُ بِشْرٍ ‏ ‏فِي حَدِيثِهِ وَذَكَرَ ‏ ‏الدَّجَّالَ ‏ ‏بَيْنَ ‏ ‏ظَهْرَانَيْ ‏ ‏النَّاسِ فَقَالَ ‏ ‏إِنَّ اللَّهَ تَبَارَكَ وَتَعَالَى لَيْسَ بِأَعْوَرَ أَلَا وَإِنَّ ‏ ‏الْمَسِيحَ الدَّجَّالَ ‏ ‏أَعْوَرُ عَيْنِ الْيُمْنَى كَأَنَّ عَيْنَهُ عِنَبَةٌ ‏ ‏طَافِيَةٌ ‏","","",""],[4711,4711,"","আমরা আমাদের দিনের বন্ধনের কথা বলেছি, কিন্তু আমরা এমন একটা ছেলের জন্য ভালো কাজ করেছি যে ঈশ্বরকে ভুলে গেছে, সে আমাদের একটা হাত দেবে যেখানে আমি তোমাকে ভালবাসি, একটা ছেলে যে তার জন্য প্রার্থনা করেছিল। আর তার জন্য, সে আমার ভালবাসার জন্য। এই ঘটনা ঘটেছে এবং এই গ্রীষ্মে বাবা বলেছিলেন এবং আমরা আমার বাবার দয়ার প্রতি প্রবল আগ্রহ নিয়ে কথা বলেছি। আমরা ঈশ্বরের কাছে প্রার্থনা করেছি। আমার বাসা প্রার্থনার জন্য প্রার্থনা করা হয়, এবং আমি প্রার্থনা করি। এবং এই গ্রীষ্মের এই সময়ে আমার বাবা-মা আমাদের বাবার কাছে প্রার্থনা করি। আমি যখন প্রার্থনা করি, তখন আমি আমার বাবার কাছে প্রার্থনা করি। এবং আমি যখন প্রার্থনা করি, তখন আমি আমার বাবার কাছে প্রার্থনা করি। আমি যখন আমি আমার বাবার কাছে প্রার্থনা করি, তখন আমি মনে করি, আমি আমার বাবার কাছে প্রার্থনা করি। এবং আমার প্রার্থনা করি, আমি যখন আমি আমার বাবার কাছে প্রার্থনা করি, তখন আমি যখন আমি আমার বাবার কাছে প্রার্থনা করি। এবং আমার বাবা আমাকে জিজ্ঞেস করি, আমি যখন আমার বাবা আমাকে জিজ্ঞেস করি, আমি আমার বাবার কাছে ক্ষমার জন্য প্রার্থনা করি, তখন আমি আমার বাবার কাছে প্রার্থনা করি। আর আমার বাবার সাথে প্রার্থনা করি, আমি যখন আমি আমার বাবা-মা-মা'র জন্য প্রার্থনা করি, তখন আমি আমার বাবার কাছে প্রার্থনা করি। আর আমার বাবা আমাকে জিজ্ঞেস করি, আমি যখন আমার বাবা আমাকে জিজ্ঞেস করেন, আমি আমার বাবা আমাকে জিজ্ঞেস করেন। তারপর তাকে জাদুর কথা বলতে দেয়া হয়.","‏ ‏حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ أُسَامَةَ ‏ ‏حَدَّثَنَا ‏ ‏عُبَيْدُ اللَّهِ ‏ ‏حَدَّثَنَا ‏ ‏نَافِعٌ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏إِذَا دُعِيَ أَحَدُكُمْ إِلَى ‏ ‏وَلِيمَةٍ ‏ ‏فَلْيُجِبْ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ أُسَامَةَ ‏ ‏حَدَّثَنَا ‏ ‏عُبَيْدُ اللَّهِ ‏ ‏حَدَّثَنَا ‏ ‏نَافِعٌ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏هَذَا الْحَدِيثَ وَهَذَا الْوَصْفَ ‏ ‏قَالَ ‏ ‏أَبِي ‏ ‏وَحَدَّثَنَا ‏ ‏قَبْلَهُ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏هِشَامٌ ‏ ‏وَابْنُ عَوْنٍ ‏ ‏عَنْ ‏ ‏مُحَمَّدٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏صَلَّى بِنَا رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِحْدَى صَلَاتَيْ ‏ ‏الْعَشِيِّ ‏ ‏رَكْعَتَيْنِ ثُمَّ سَلَّمَ فَذَكَرَ الْحَدِيثَ فَلْيُجِبْ ‏","","",""],[4712,4712,"","তিনি আমাকে ছেড়ে চলে যান এবং আমাকে বলেন যে, তিনি আমার বাবার সঙ্গে কথা বলছেন ।","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ زَكَرِيَّا بْنِ أَبِي زَائِدَةَ ‏ ‏حَدَّثَنِي ‏ ‏عُبَيْدُ اللَّهِ ‏ ‏عَنْ ‏ ‏نَافِعٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏بَادِرُوا ‏ ‏الصُّبْحَ ‏ ‏بِالْوِتْرِ ‏","","",""],[4713,4713,"","আমরা প্রিয়ের কথা বলেছি, আমার টাকা ভুলে গেছে একটা ছেলে যে কিনা প্রার্থনা করছিল, আমি বিশ্বাস করি, অভিশাপের সন্তানই তার মায়ের।","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ زَكَرِيَّا ‏ ‏حَدَّثَنِي ‏ ‏مَالِكُ بْنُ أَنَسٍ ‏ ‏عَنْ ‏ ‏نَافِعٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَلْحَقَ ابْنَ ‏ ‏الْمُلَاعَنَةِ ‏ ‏بِأُمِّهِ ‏","","",""],[4714,4714,"","আমি আমার পরিবারের সঙ্গে বাইবেল অধ্যয়ন করতে শুরু করি ।","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ زَكَرِيَّا ‏ ‏أَخْبَرَنِي ‏ ‏عَاصِمٌ الْأَحْوَلُ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ شَقِيقٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏بَادِرُوا ‏ ‏الصُّبْحَ ‏ ‏بِالْوَتْرِ ‏","","",""],[4715,4715,"","তিনি দশ বছর ধরে সেই নগর ত্যাগ করেছিলেন ।","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ زَكَرِيَّا ‏ ‏حَدَّثَنَا ‏ ‏حَجَّاجٌ ‏ ‏عَنْ ‏ ‏نَافِعٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏قَالَ ‏ ‏أَقَامَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بِالْمَدِينَةِ ‏ ‏عَشْرَ سِنِينَ يُضَحِّي ‏","","",""],[4716,4716,"","আমরা দুটো গ্রাম তৈরি করেছি, যেগুলো একটি ছেলে সম্পর্কে ঈশ্বরের ভালো কথা দ্বারা পূর্ণ। যে আমাকে ঈশ্বর সম্পর্কে শিক্ষা দিয়েছেন এবং একটি পার্থক্য আনতে সক্ষম হবেন। তিনি তার যাত্রা শুরু করার জন্য প্রার্থনা করেছিলেন। তিনি আমার জন্য একটি ছোট গ্রাম তৈরি করেছেন। এবং তিনি আমার জন্য একটি ভাল শিক্ষা লাভ করেছেন। আমি একটি ছোট ছোট গ্রাম গড়ে তুলতে সক্ষম হয়েছি। আমি নিশ্চিত নই যে, আমি আমার একটি ছেলে যে আমি আমার কাছে একটি ছোট গ্রাম খুঁজে পেয়েছি। আমি যদি আমার জীবনের জন্য একটি ছোট ছোট গ্রাম খুঁজে পাই, তাহলে আমি আমার জীবনের জন্য, আমি একটি ছোট ছোট ছোট গ্রাম খুঁজে বের করতে পারি। আমি আমার জীবনের পথে যাব। আমি যখন আমি একটি ছোট ছোট ছোট ছোট ছোট ছোট ছোট পরিবার, তখন আমি একটি ছোট ছোট গ্রাম খুঁজে বের করতে পারব। এবং আমি আশা করি, আমি আমার জীবনের জন্য। আমি আমার জীবনের জন্য। আমি আমার জীবনের পথে এগিয়ে যাচ্ছি। আমি যখন আমি আমার বাবা-মাট্যুর কথা বলছি, তখন আমি আমার বাবা-মাটফটফট এবং আমি আমার বাবা-মাকে পেয়েছি। তার মুখের দিকে.","‏ ‏حَدَّثَنَا ‏ ‏قُرَّانُ بْنُ تَمَّامٍ ‏ ‏عَنْ ‏ ‏عُبَيْدِ اللَّهِ ‏ ‏عَنِ ‏ ‏نَافِعٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ ‏ ‏يُصَلِّي عَلَى رَاحِلَتِهِ حَيْثُ تَوَجَّهَتْ بِهِ ‏","","",""],[4717,4717,"","আমরা একটি ছেলে কথা বলেছি যে জন্ম দেওয়ার লজ্জা ভোগ করেছে। তিনি কসম কেটে বলেছিলেন যে ঈশ্বর মারা গেছেন এবং তিনি আমাকে বলেছিলেন যে, যদি তিনি আপনাকে ডেকেও ডাকতেন, তোমাকে আহ্বান কর, সে আমাকে হাত দিবে, আমি আমার হাত ফেরত দিব, যেন সে বলে ঈশ্বর তোমাকে ঋণ প্রদান করে এবং তুমি রাজা হিসেবে সেবা করবে।","‏ ‏حَدَّثَنَا ‏ ‏مَرْوَانُ بْنُ مُعَاوِيَةَ الْفَزَارِيُّ ‏ ‏أَخْبَرَنَا ‏ ‏عَبْدُ الْعَزِيزِ بْنُ عُمَرَ بْنِ عَبْدِ الْعَزِيزِ ‏ ‏عَنْ ‏ ‏إِسْمَاعِيلَ بْنِ جَرِيرٍ ‏ ‏عَنْ ‏ ‏قَزَعَةَ ‏ ‏قَالَ ‏ ‏قَالَ ‏ ‏عَبْدُ اللَّهِ بْنُ عُمَرَ ‏ ‏وَأَرْسَلَنِي فِي حَاجَةٍ لَهُ فَقَالَ تَعَالَ حَتَّى أُوَدِّعَكَ كَمَا وَدَّعَنِي رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَأَرْسَلَنِي فِي حَاجَةٍ لَهُ فَأَخَذَ بِيَدِي فَقَالَ ‏ ‏أَسْتَوْدِعُ ‏ ‏اللَّهَ دِينَكَ وَأَمَانَتَكَ وَخَوَاتِيمَ عَمَلِكَ ‏","","",""],[4718,4718,"","আমরা আমার বাবার দুটো উপায় নিয়ে কথা বলেছিলাম, সে আত্মসমর্পণ করবে আর সে আমাকে মেরে ফেলবে আর তারপর তুমি যা বলেছিলে, সেটাই পাবে। ঈশ্বরের দ্বারা অনুপ্রাণিত হয়ে আমি বলেছিলাম যে, তাদের কাছে সত্য রয়েছে ।","‏ ‏حَدَّثَنَا ‏ ‏عَبْدَةُ بْنُ سُلَيْمَانَ أَبُو مُحَمَّدٍ الْكِلَابِيُّ ‏ ‏حَدَّثَنَا ‏ ‏هِشَامٌ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَقَفَ عَلَى ‏ ‏قَلِيبِ بَدْرٍ ‏ ‏فَقَالَ ‏ ‏هَلْ وَجَدْتُمْ مَا وَعَدَكُمْ رَبُّكُمْ حَقًّا ثُمَّ قَالَ إِنَّهُمْ لَيَسْمَعُونَ مَا أَقُولُ ‏ ‏فَذُكِرَ ‏ ‏ذَلِكَ ‏ ‏لِعَائِشَةَ ‏ ‏فَقَالَتْ ‏ ‏وَهِلَ ‏ ‏يَعْنِي ‏ ‏ابْنَ عُمَرَ ‏ ‏إِنَّمَا قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِنَّهُمْ الْآنَ لَيَعْلَمُونَ أَنَّ الَّذِي كُنْتُ أَقُولُ لَهُمْ لَهُوَ الْحَقُّ ‏","","",""],[4719,4719,"","আমরা এমন একটা ছেলের কথা বলেছিলাম, যার ছেলে আছে, ঈশ্বরের পুত্র রয়েছে । আর তাকে মেরে ফেলতে হবে, তারপর সে চলে যাবে। * ফাজ আর শকুন আমি পাই *","‏ ‏حَدَّثَنَا ‏ ‏عَبْدَةُ ‏ ‏حَدَّثَنَا ‏ ‏هِشَامٌ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّهُ قَالَ ‏ ‏إِنَّ الْمَيِّتَ لَيُعَذَّبُ بِبُكَاءِ أَهْلِهِ عَلَيْهِ ‏ ‏فَذُكِرَ ‏ ‏ذَلِكَ ‏ ‏لِعَائِشَةَ ‏ ‏فَقَالَتْ ‏ ‏وَهِلَ ‏ ‏يَعْنِي ‏ ‏ابْنَ عُمَرَ ‏ ‏إِنَّمَا ‏ ‏مَرَّ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَلَى قَبْرٍ فَقَالَ إِنَّ صَاحِبَ هَذَا لَيُعَذَّبُ وَأَهْلُهُ يَبْكُونَ عَلَيْهِ ثُمَّ قَرَأَتْ هَذِهِ الْآيَةَ ‏ { ‏وَلَا ‏ ‏تَزِرُ ‏ ‏وَازِرَةٌ ‏ ‏وِزْرَ ‏ ‏أُخْرَى ‏}","","",""],[4720,4720,"","আমরা ঈশ্বরের ভালোর কথা বলেছি যে ঈশ্বরের কাছে পাঠানো একটি ছেলে, কিন্তু তিনি যা করেছেন তা হলো, তিনি করতে সক্ষম হবেন এমন ক্ষমতা অর্জন করতে সক্ষম হবেন তিনি সেনাবাহিনী দ্বারা নিহত, গোপন এবং যুক্তি এবং যুক্তি দ্বারা হত্যা তাই তাকে বলা হয় যে আপনার ক্রেতার রাজার কাছে আছে এবং আছে আছে। সে ভালোবাসা এবং তার ইউনিটকে হারিয়ে ফেলেছে।","‏ ‏حَدَّثَنَا ‏ ‏عَبْدَةُ ‏ ‏حَدَّثَنَا ‏ ‏عُبَيْدُ اللَّهِ ‏ ‏عَنْ ‏ ‏نَافِعٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ إِذَا ‏ ‏قَفَلَ ‏ ‏مِنْ الْجُيُوشِ وَالسَّرَايَا أَوْ الْحَجِّ وَالْعُمْرَةِ فَإِذَا أَوْفَى عَلَى ‏ ‏أُرْبِيَّةٍ ‏ ‏كَبَّرَ ثَلَاثًا ثُمَّ قَالَ ‏ ‏لَا إِلَهَ إِلَّا اللَّهُ وَحْدَهُ لَا شَرِيكَ لَهُ لَهُ الْمُلْكُ وَلَهُ الْحَمْدُ وَهُوَ عَلَى كُلِّ شَيْءٍ قَدِيرٌ ‏ ‏آيِبُونَ ‏ ‏تَائِبُونَ عَابِدُونَ سَاجِدُونَ لِرَبِّنَا حَامِدُونَ صَدَقَ وَعْدَهُ وَنَصَرَ عَبْدَهُ وَهَزَمَ الْأَحْزَابَ وَحْدَهُ ‏","","",""],[4721,4721,"","আমরা আমাদের কথা দিয়েছি কিন্তু আমার ভালবাসা ত্যাগ করে, এক ছেলে, যে ভাববাদীর কাছে প্রার্থনা করেছিল, সে পানি চায়, আর তার কাছে পানি চাইলো, দরজার লোক আর সাঁতারু বললো। ঈশ্বর তার জন্য প্রার্থনা করেছেন এবং তাকে আত্মসমর্পণ করেছেন যদি পানি রাজার প্রতারণার দ্বারা বিভক্ত হতে হয়।","‏ ‏حَدَّثَنَا ‏ ‏عَبْدَةُ ‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ إِسْحَاقَ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ جَعْفَرِ بْنِ الزُّبَيْرِ ‏ ‏عَنْ ‏ ‏عُبَيْدِ اللَّهِ بْنِ عَبْدِ اللَّهِ بْنِ عُمَرَ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏قَالَ ‏ ‏سَمِعْتُ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يُسْأَلُ عَنْ الْمَاءِ يَكُونُ بِأَرْضِ ‏ ‏الْفَلَاةِ ‏ ‏وَمَا ‏ ‏يَنُوبُهُ ‏ ‏مِنْ الدَّوَابِّ وَالسِّبَاعِ فَقَالَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِذَا كَانَ الْمَاءُ قَدْرَ ‏ ‏قُلَّتَيْنِ ‏ ‏لَمْ يَحْمِلْ الْخَبَثَ ‏","","",""],[4722,4722,"","আমরা দুটো উপায় নিয়ে কথা বলেছি একটা ছেলে নিয়ে কথা বলার জন্য। আমি ভগবানকে তার জন্য প্রার্থনা করতে দেখলাম এবং বিছানায় তার পর প্রার্থনা করতে দেখলাম।","‏ ‏حَدَّثَنَا ‏ ‏عَبْدَةُ بْنُ سُلَيْمَانَ ‏ ‏حَدَّثَنَا ‏ ‏عُبَيْدُ اللَّهِ ‏ ‏حَدَّثَنِي ‏ ‏مَنْ ‏ ‏سَمِعَ ‏ ‏ابْنَ سُرَاقَةَ ‏ ‏يَذْكُرُ عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏قَالَ ‏ ‏مَا رَأَيْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يُصَلِّي قَبْلَ الصَّلَاةِ وَلَا بَعْدَهَا فِي السَّفَرِ ‏","","",""],[4723,4723,"","আমরা ঈশ্বরের ভালোর কথা বলেছি যে ঈশ্বরকে তার শান্তি এবং ভালবাসার জন্য ঈশ্বরকে ধন্যবাদ দিয়েছে।","‏ ‏حَدَّثَنَا ‏ ‏عَبْدَةُ ‏ ‏حَدَّثَنَا ‏ ‏عُبَيْدُ اللَّهِ ‏ ‏عَنْ ‏ ‏نَافِعٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَأَبَا بَكْرٍ ‏ ‏وَعُمَرَ ‏ ‏كَانُوا ‏ ‏يَبْدَءُونَ بِالصَّلَاةِ قَبْلَ الْخُطْبَةِ فِي الْعِيدِ ‏","","",""],[4724,4724,"","আমরা একটা ছেলের কথা বলেছি যে তার হয়ে কাজ করেছে। একটা সিদ্ধান্ত নিয়েছে যে, এটা তাদের সমাধান করে তাকে নিয়ে যাবে না।","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ يَمَانٍ ‏ ‏عَنْ ‏ ‏سُفْيَانَ ‏ ‏عَنْ ‏ ‏عُبَيْدِ اللَّهِ ‏ ‏عَنْ ‏ ‏نَافِعٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏طَافَ طَوَافًا وَاحِدًا لِإِقْرَانِهِ لَمْ يَحِلَّ بَيْنَهُمَا وَاشْتَرَى هَدْيًا مِنْ الطَّرِيقِ مِنْ ‏ ‏قُدَيْدٍ ‏","","",""],[4725,4725,"","আমরা একটি মই এর জন্মের কথা বলেছি যে আমরা একটি ছেলের জন্মের জন্য উপযুক্ত যে সন্তান জন্ম হবে খুশি হবে, তার প্রভুকে উপাসনা করতে পারি। একটি শিশু সন্তান যে ছেলে ছিল, তার ছেলে। আগুন তাকে কানে ঢুকিয়ে দিয়েছে। আগুন বলে, \"মানুষ, আমরা একই কাজ করি।\" আমি দেখেছি আল্লাহ তাকে প্রার্থনা করতে এবং তাকে উদ্ধার করে একটি আতঙ্কের আক্রমন শুনতে।","‏ ‏حَدَّثَنَا ‏ ‏الْوَلِيدُ بْنُ مُسْلِمٍ ‏ ‏حَدَّثَنَا ‏ ‏سَعِيدُ بْنُ عَبْدِ الْعَزِيزِ ‏ ‏وَمَخْلَدُ بْنُ يَزِيدَ ‏ ‏أَخْبَرَنَا ‏ ‏سَعِيدٌ ‏ ‏الْمَعْنَى ‏ ‏عَنْ ‏ ‏سُلَيْمَانَ بْنِ مُوسَى ‏ ‏عَنْ ‏ ‏نَافِعٍ ‏ ‏مَوْلَى ‏ ‏ابْنِ عُمَرَ ‏ ‏سَمِعَ ‏ ‏ابْنُ عُمَرَ ‏ ‏صَوْتَ زَمَّارَةِ رَاعٍ فَوَضَعَ إِصْبَعَيْهِ فِي أُذُنَيْهِ وَعَدَلَ رَاحِلَتَهُ عَنْ الطَّرِيقِ وَهُوَ يَقُولُ يَا ‏ ‏نَافِعُ ‏ ‏أَتَسْمَعُ فَأَقُولُ نَعَمْ قَالَ ‏ ‏فَيَمْضِي حَتَّى قُلْتُ لَا قَالَ فَوَضَعَ يَدَيْهِ وَأَعَادَ الرَّاحِلَةَ إِلَى الطَّرِيقِ وَقَالَ ‏ ‏رَأَيْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَسَمِعَ صَوْتَ زَمَّارَةِ رَاعٍ فَصَنَعَ مِثْلَ هَذَا ‏","","",""],[4726,4726,"","আমরা লর্ডের কথা বলেছি মানে একজন পণ্ডিতের ছেলে যে আমার সাথে কথা বলেছে, সে একবার ফ্ল্যাশ করেছিল আর সে এটা করতে পারতো। তিন দিন পর সে তার শান্তির জন্য প্রার্থনা করবে। আত্মসমর্পণ করো.","‏ ‏حَدَّثَنَا ‏ ‏الْوَلِيدُ يَعْنِي ابْنَ مُسْلِمٍ ‏ ‏حَدَّثَنَا ‏ ‏الْأَوْزَاعِيُّ ‏ ‏حَدَّثَنِي ‏ ‏الْمُطَّلِبُ بْنُ عَبْدِ اللَّهِ بْنِ حَنْطَبٍ ‏ ‏أَنَّ ‏ ‏ابْنَ عَبَّاسٍ ‏ ‏كَانَ ‏ ‏يَتَوَضَّأُ مَرَّةً مَرَّةً وَيُسْنِدُ ذَلِكَ إِلَى رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَأَنَّ ‏ ‏ابْنَ عُمَرَ ‏ ‏كَانَ ‏ ‏يَتَوَضَّأُ ثَلَاثًا ثَلَاثًا وَيُسْنِدُ ذَلِكَ إِلَى رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏","","",""],[4727,4727,"","আমরা লর্ডের কাছে বলেছি, আস্থার সাথে, তিনি একটি ছোট ছেলে যে কিনা তার ইচ্ছার কথা বলেছে, আমি ঈশ্বরের অনুগ্রহের সাথে প্রতিজ্ঞাটা দেখেছি, ঈশ্বর তাকে একটি হিসেবে সেবা করেছেন তিনি একটা নিরস্ত্র কান নিয়ে এসে একটা গুরুত্বপূর্ণ কান দিয়ে প্রতিজ্ঞা করেছিলেন । পরে আমরা দুই ছেলে হয়ে গেলাম, আর সে কখনো সূর্য সম্বন্ধে কিছু বলেনি। সে আমাকে বলে সে একটা পরিত্যক্ত তরুণের ছেলে, কিভাবে ঈশ্বরকে খুঁজে পেতে হয়। টক টক বা বলো।","‏ ‏حَدَّثَنَا ‏ ‏الْوَلِيدُ بْنُ مُسْلِمٍ ‏ ‏عَنْ ‏ ‏عَبْدِ الرَّزَّاقِ بْنِ عُمَرَ الثَّقَفِيِّ ‏ ‏أَنَّهُ سَمِعَ ‏ ‏ابْنَ شِهَابٍ ‏ ‏يُخْبِرُ عَنْ ‏ ‏سَالِمٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏قَالَ ‏ ‏شَهِدْتُ الْعِيدَ مَعَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَصَلَّى ‏ ‏بِلَا أَذَانٍ وَلَا إِقَامَةٍ ‏ ‏ثُمَّ شَهِدْتُ الْعِيدَ مَعَ ‏ ‏أَبِي بَكْرٍ ‏ ‏فَصَلَّى ‏ ‏بِلَا أَذَانٍ وَلَا إِقَامَةٍ ‏ ‏قَالَ ‏ ‏ثُمَّ شَهِدْتُ الْعِيدَ مَعَ ‏ ‏عُمَرَ ‏ ‏فَصَلَّى ‏ ‏بِلَا أَذَانٍ وَلَا إِقَامَةٍ ‏ ‏ثُمَّ شَهِدْتُ الْعِيدَ مَعَ ‏ ‏عُثْمَانَ ‏ ‏فَصَلَّى ‏ ‏بِلَا أَذَانٍ وَلَا إِقَامَةٍ ‏ ‏حَدَّثَنَا ‏ ‏الْوَلِيدُ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ ثَوْبَانَ ‏ ‏أَنَّهُ سَمِعَ ‏ ‏النُّعْمَانَ بْنَ رَاشِدٍ الْجَزَرِيَّ ‏ ‏يُخْبِرُ أَنَّهُ سَمِعَ ‏ ‏ابْنَ شِهَابٍ الزُّهْرِيَّ ‏ ‏يُخْبِرُ عَنْ ‏ ‏سَالِمِ بْنِ عَبْدِ اللَّهِ ‏ ‏يُخْبِرُ عَنْ ‏ ‏أَبِيهِ ‏ ‏عَبْدِ اللَّهِ بْنِ عُمَرَ ‏ ‏مِثْلَ هَذَا الْحَدِيثِ أَوْ نَحْوَهُ ‏","","",""],[4728,4728,"","আমরা একটি ভাল ছেলে আছে কথা বলেছি, যে কিনা বলতে পারে না, ঈশ্বর তা দিয়েছেন, এটা একটা কামনার সাথে বন্ধুত্বের সুযোগ পাবে না।","‏ ‏حَدَّثَنَا ‏ ‏حُسَيْنُ بْنُ عَلِيٍّ ‏ ‏عَنْ ‏ ‏زَائِدَةَ ‏ ‏عَنْ ‏ ‏سِمَاكٍ ‏ ‏عَنْ ‏ ‏مُصْعَبِ بْنِ سَعْدٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَا تُقْبَلُ ‏ ‏صَدَقَةٌ ‏ ‏مِنْ ‏ ‏غُلُولٍ ‏ ‏وَلَا صَلَاةٌ بِغَيْرِ طُهُورٍ ‏","","",""],[4729,4729,"","আমরা একটি ছেলে আছে এমন একটি ছেলে আছে কথা বলছি যে ছেলে যখন মানুষ, বিশ্ব এমন এক সময়ের কথা বলছে যা আমাদের হারিয়ে ফেলেছে তিনি বলেছিলেন যে, তিনি জানতেন যে তিনি ঈশ্বরের কাছে আসবেন, তাকে তা উদ্ধার করতে হবে এবং তিনি বলেছিলেন যে, দিনটা ছিল মহান দিন ।","‏ ‏حَدَّثَنَا ‏ ‏حُسَيْنُ بْنُ عَلِيٍّ ‏ ‏عَنْ ‏ ‏زَائِدَةَ ‏ ‏عَنْ ‏ ‏إِبْرَاهِيمَ بْنِ مُهَاجِرٍ ‏ ‏عَنْ ‏ ‏أَبِي الشَّعْثَاءِ ‏ ‏قَالَ ‏ ‏أَتَيْنَا ‏ ‏ابْنَ عُمَرَ ‏ ‏فِي الْيَوْمِ الْأَوْسَطِ مِنْ أَيَّامِ التَّشْرِيقِ قَالَ فَأُتِيَ بِطَعَامٍ فَدَنَا الْقَوْمُ وَتَنَحَّى ابْنٌ لَهُ قَالَ فَقَالَ لَهُ ادْنُ فَاطْعَمْ قَالَ فَقَالَ إِنِّي صَائِمٌ قَالَ فَقَالَ أَمَا عَلِمْتَ أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏إِنَّهَا أَيَّامُ ‏ ‏طُعْمٍ ‏ ‏وَذِكْرٍ ‏","","",""],[4730,4730,"","আমরা একটা ছেলের কথা বলেছিলাম যে আমার কাছে জন্ম হয়েছে বা না চায়, সে কখনও ঈশ্বরের কাছে প্রার্থনা করেছে এবং সে উদ্ধার করেছে।","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ بِشْرٍ ‏ ‏حَدَّثَنَا ‏ ‏عُبَيْدُ اللَّهِ ‏ ‏عَنْ ‏ ‏نَافِعٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏قَالَ ‏ ‏وَمَنْ صَلَّى مِنْ أَوَّلِ اللَّيْلِ فَلْيَجْعَلْ آخِرَ صَلَاتِهِ ‏ ‏وِتْرًا ‏ ‏فَإِنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ يَأْمُرُ بِذَلِكَ ‏","","",""],[4731,4731,"","আমরা একটি মহান মন্দ কথা বলেছি... ...যে আমার সাথে প্রেম করে, সে আমাকে বলেছিল, ঈশ্বরের কাছে প্রার্থনা করে আমি প্রার্থনা করি আর আমি বলতে পারি যে আমি ই আছি, আমি এখানেই আছি। ঘুমের মধ্যে আমি নিজেকে একা একা ফেলে এসেছি, বড় হও, তারপর আমরা পাগল হয়ে যাব আর উড়িয়ে দিব. মানুষ একটা সুর আঘাত করে।","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ بِشْرٍ ‏ ‏حَدَّثَنَا ‏ ‏عُبَيْدُ اللَّهِ ‏ ‏حَدَّثَنِي ‏ ‏أَبُو بَكْرِ بْنُ سَالِمٍ ‏ ‏عَنْ ‏ ‏سَالِمِ بْنِ عَبْدِ اللَّهِ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ عُمَرَ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ أُرِيتُ فِي النَّوْمِ أَنِّي ‏ ‏أَنْزِعُ بِدَلْوِ ‏ ‏بَكْرَةٍ ‏ ‏عَلَى ‏ ‏قَلِيبٍ ‏ ‏فَجَاءَ ‏ ‏أَبُو بَكْرٍ ‏ ‏فَنَزَعَ ‏ ‏ذَنُوبًا ‏ ‏أَوْ ‏ ‏ذَنُوبَيْنِ ‏ ‏وَنَزَعَ نَزْعًا ضَعِيفًا وَاللَّهُ يَغْفِرُ لَهُ ثُمَّ جَاءَ ‏ ‏عُمَرُ بْنُ الْخَطَّابِ ‏ ‏فَاسْتَقَى ‏ ‏فَاسْتَحَالَتْ ‏ ‏غَرْبًا ‏ ‏فَلَمْ أَرَ ‏ ‏عَبْقَرِيًّا ‏ ‏مِنْ النَّاسِ ‏ ‏يَفْرِي ‏ ‏فَرِيَّهُ ‏ ‏حَتَّى رَوَّى النَّاسُ وَضَرَبُوا بِعَطَنٍ ‏","","",""],[4732,4732,"","ঈশ্বরের কাছে তার সৌভাগ্যের প্রতিজ্ঞার ব্যাপারে এক বিবেক আছে, ঈশ্বর তাকে প্রার্থনা করেছেন এবং তাকে হত্যা করার জন্য আত্মসমর্পণ করেছেন প্রভু এবং বিস্ময়কর শপথটি করেছেন মাথা.","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ بِشْرٍ ‏ ‏عَنْ ‏ ‏عُبَيْدِ اللَّهِ ‏ ‏عَنْ ‏ ‏عُمَرَ بْنِ نَافِعٍ ‏ ‏عَنْ ‏ ‏نَافِعٍ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ عُمَرَ ‏ ‏قَالَ ‏ ‏نَهَى رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَنْ ‏ ‏الْقَزَعِ ‏ ‏قَالَ ‏ ‏عُبَيْدُ اللَّهِ ‏ ‏وَالْقَزَعُ ‏ ‏التَّرْقِيعُ فِي الرَّأْسِ ‏","","",""],[4733,4733,"","আমরা প্রায় দুই ডজন কথা বলেছি, আমরা তার বাবার ছেলের জন্য ভালো কাজ করেছি... ...সে ঈশ্বরের ইচ্ছা পূরণ করেছে।","‏ ‏حَدَّثَنَا ‏ ‏عُثْمَانُ ‏ ‏حَدَّثَنَا ‏ ‏عُمَرُ بْنُ نَافِعٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏قَالَ ‏ ‏نَهَى رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَنْ ‏ ‏الْقَزَعِ ‏","","",""],[4734,4734,"","আমরা দু'টো ভাবে সাঁতার কাটতে চেষ্টা করেছি আমার বাবার প্রভুর শপথ শোনার জন্য, ঈশ্বর তার জন্য প্রার্থনা করেছেন এবং বলেন যে তিনি শুধু মারা যাবেন। চুল ভর্তি করো।","‏ ‏حَدَّثَنَا ‏ ‏إِسْحَاقُ بْنُ سُلَيْمَانَ ‏ ‏سَمِعْتُ ‏ ‏حَنْظَلَةَ بْنَ أَبِي سُفْيَانَ الْجُمَحِيَّ ‏ ‏سَمِعْتُ ‏ ‏سَالِمَ بْنَ عَبْدِ اللَّهِ ‏ ‏يَقُولُ سَمِعْتُ ‏ ‏عَبْدَ اللَّهِ بْنَ عُمَرَ ‏ ‏يَقُولُ ‏ ‏سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏لَأَنْ يَمْتَلِئَ جَوْفُ أَحَدِكُمْ قَيْحًا خَيْرٌ لَهُ مِنْ أَنْ يَمْتَلِئَ شِعْرًا ‏","","",""],[4735,4735,"","আমরা দুটো উপায় খুঁজছি, আমাদের বলতে হবে আমার বাবা কেমন হতে পারে। ভগবান ঈশ্বরের কাছে প্রার্থনা করেছিলেন, আর আত্মসমর্পণ করেছিলেন তার হাতের ডালে।","‏ ‏حَدَّثَنَا ‏ ‏إِسْحَاقُ بْنُ سُلَيْمَانَ ‏ ‏أَخْبَرَنَا ‏ ‏عَبْدُ الْعَزِيزِ بْنُ أَبِي رَوَّادٍ ‏ ‏عَنْ ‏ ‏نَافِعٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏أَنَّ فَصَّ خَاتَمِ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ فِي بَاطِنِ كَفِّهِ ‏","","",""],[4736,4736,"","আমরা দুটো ভাঙ্গা উপায় চুরি করেছি, যা আমার বাবা বলতে চান তা বিষ। তিনি ঈশ্বরের কাছে প্রার্থনা করেছেন, আর তাকে দেখতে পাবেন যে তিনি কি করতে চান। তার বা তার শ্রেষ্ঠত্বের কারণে কে হারবে, যার কাছে তারা বলেছে, মেরি বা ঈশ্বরের ছেলে না হওয়া। আমি ভয় পাচ্ছি বসের কাছে আমি সঠিক ধার নিয়েছি।","‏ ‏حَدَّثَنَا ‏ ‏إِسْحَاقُ بْنُ سُلَيْمَانَ ‏ ‏سَمِعْتُ ‏ ‏حَنْظَلَةَ بْنَ أَبِي سُفْيَانَ ‏ ‏سَمِعْتُ ‏ ‏سَالِمًا ‏ ‏يَقُولُ سَمِعْتُ ‏ ‏عَبْدَ اللَّهِ بْنَ عُمَرَ ‏ ‏يَقُولُ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏رَأَيْتُ عِنْدَ ‏ ‏الْكَعْبَةِ ‏ ‏مِمَّا يَلِي وَجْهَهَا رَجُلًا آدَمَ ‏ ‏سَبْطَ ‏ ‏الرَّأْسِ وَاضِعًا يَدَهُ عَلَى رَجُلَيْنِ ‏ ‏يَسْكُبُ ‏ ‏رَأْسُهُ ‏ ‏أَوْ يَقْطُرُ رَأْسُهُ ‏ ‏فَقُلْتُ مَنْ هَذَا قَالُوا ‏ ‏عِيسَى ابْنُ مَرْيَمَ ‏ ‏أَوْ ‏ ‏الْمَسِيحُ ابْنُ مَرْيَمَ ‏ ‏وَرَأَيْتُ وَرَاءَهُ رَجُلًا أَحْمَرَ أَعْوَرَ عَيْنِ الْيُمْنَى ‏ ‏جَعْدَ ‏ ‏الرَّأْسِ أَشْبَهُ مَنْ رَأَيْتُ بِهِ ‏ ‏ابْنُ قَطَنٍ ‏ ‏فَقُلْتُ مَنْ هَذَا قَالُوا ‏ ‏الْمَسِيحُ الدَّجَّالُ ‏","","",""],[4737,4737,"","আমরা দু'টো চুরি করার চেষ্টা করেছি এবং সমুদ্রতলিয় ঈশ্বর কে এমন করে খেলছি যার নাম 'সমুদ্র'। সে বলছিল যে, সে ভুল করেছে। নবী তাঁর কাছে প্রার্থনা করে তাঁর সেরা গুলিটা দিয়েছিলেন। আপনি এই স্যুটটা কিনেছিলেন, যদি আপনার কাছে এসে থাকে আর মানুষ হত্যা করবে। আপনি বলেছিলেন যে, আমি যখন তাকে খুঁজে বের করতে অথবা আপনার মুখে খনন করতে বলি, তখন আমি তাকে খুঁজে বের করতে অথবা তার মুখ থেকে খোঁড়ার চেষ্টা করতে পারি । আমি যখন তার সাথে কথা বলেছি তখন তাকে তার কাছে হারতে হয়নি, অথবা সে যখন তার কথা শুনতে পায় তখন সে শুনতে পায় যে সে হয়ত হয়ত তার কথা শুনেছে। সে সময় তার কথা খুঁজে পেয়েছে, যখন সে উল্লেখ করেছিল তখন সে সময় সে তার কথা বলছিল। আমি তার জামা পড়ে থাকতে পারি এবং ঈশ্বরকে তার শান্তির জন্য প্রার্থনা করতে তাকে তার দিকে তাকিয়ে বলতে চাই আর সে আমাকে বলতে বলেছে যে, সে আমার বাবা ।","‏ ‏حَدَّثَنَا ‏ ‏إِسْحَاقُ بْنُ سُلَيْمَانَ ‏ ‏وَعَبْدُ اللَّهِ بْنُ الْحَارِثِ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏حَنْظَلَةُ ‏ ‏سَمِعْتُ ‏ ‏سَالِمًا ‏ ‏يَقُولُ سَمِعْتُ ‏ ‏عَبْدَ اللَّهِ بْنَ عُمَرَ ‏ ‏يَقُولُ ‏ ‏إِنَّ ‏ ‏عُمَرَ بْنَ الْخَطَّابِ ‏ ‏أَتَى النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بِحُلَّةِ ‏ ‏إِسْتَبْرَقٍ ‏ ‏فَقَالَ يَا رَسُولَ اللَّهِ لَوْ اشْتَرَيْتَ هَذِهِ ‏ ‏الْحُلَّةَ ‏ ‏فَتَلْبَسَهَا ‏ ‏إِذَا قَدِمَ عَلَيْكَ وُفُودُ النَّاسِ فَقَالَ ‏ ‏إِنَّمَا يَلْبَسُ هَذَا مَنْ لَا ‏ ‏خَلَاقَ ‏ ‏لَهُ ثُمَّ أُتِيَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بِحُلَلٍ ‏ ‏ثَلَاثٍ فَبَعَثَ إِلَى ‏ ‏عُمَرَ ‏ ‏بِحُلَّةٍ ‏ ‏وَإِلَى ‏ ‏عَلِيٍّ ‏ ‏بِحُلَّةٍ ‏ ‏وَإِلَى ‏ ‏أُسَامَةَ بْنِ زَيْدٍ ‏ ‏بِحُلَّةٍ ‏ ‏فَأَتَى ‏ ‏عُمَرُ ‏ ‏بِحُلَّتِهِ ‏ ‏النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ يَا رَسُولَ اللَّهِ بَعَثْتَ إِلَيَّ بِهَذِهِ وَقَدْ سَمِعْتُكَ قُلْتَ فِيهَا مَا قُلْتَ قَالَ إِنَّمَا بَعَثْتُ بِهَا إِلَيْكَ لِتَبِيعَهَا أَوْ تُشَقِّقَهَا لِأَهْلِكَ خُمُرًا ‏ ‏قَالَ ‏ ‏إِسْحَاقُ ‏ ‏فِي حَدِيثِهِ وَأَتَاهُ ‏ ‏أُسَامَةُ ‏ ‏وَعَلَيْهِ ‏ ‏الْحُلَّةُ ‏ ‏فَقَالَ إِنِّي لَمْ أَبْعَثْ بِهَا إِلَيْكَ لِتَلْبَسَهَا إِنَّمَا بَعَثْتُ بِهَا إِلَيْكَ لِتَبِيعَهَا ‏ ‏مَا أَدْرِي أَقَالَ ‏ ‏لِأُسَامَةَ ‏ ‏تُشَقِّقُهَا خُمُرًا أَمْ لَا ‏ ‏قَالَ ‏ ‏عَبْدُ اللَّهِ بْنُ الْحَارِثِ ‏ ‏فِي حَدِيثِهِ ‏ ‏أَنَّهُ سَمِعَ ‏ ‏سَالِمَ بْنَ عَبْدِ اللَّهِ ‏ ‏يَقُولُ سَمِعْتُ ‏ ‏عَبْدَ اللَّهِ بْنَ عُمَرَ ‏ ‏يَقُولُ ‏ ‏وَجَدَ ‏ ‏عُمَرُ ‏ ‏فَذَكَرَ مَعْنَاهُ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ الْحَارِثِ ‏ ‏حَدَّثَنِي ‏ ‏حَنْظَلَةُ ‏ ‏عَنْ ‏ ‏نَافِعٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏قَالَ ‏ ‏وَأَتَاهُ ‏ ‏أُسَامَةُ ‏ ‏وَقَدْ لَبِسَهَا فَنَظَرَ إِلَيْهِ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ أَنْتَ كَسَوْتَنِي قَالَ ‏ ‏شَقِّقْهَا بَيْنَ نِسَائِكَ ‏ ‏خُمُرًا ‏ ‏أَوْ اقْضِ بِهَا حَاجَتَكَ ‏","","",""],[4738,4738,"","আমরা শুনেছি যে এটা অন্ধকার হতে পারে, ঈশ্বর তাঁর কাছে প্রার্থনা করেছেন এবং তাকে শাস্তি প্রদান করবেন অথবা বলেন যে ঈশ্বর তাকে উদ্ধার করেছেন এবং তিনি ব্যর্থ হবেন না। সে বলেছে, মেয়েটা এখানে আছে ছায়া ভাঙ্গার জন্য।","‏ ‏حَدَّثَنَا ‏ ‏إِسْحَاقُ بْنُ سُلَيْمَانَ ‏ ‏سَمِعْتُ ‏ ‏حَنْظَلَةَ ‏ ‏سَمِعْتُ ‏ ‏سَالِمًا ‏ ‏يَقُولُ سَمِعْتُ ‏ ‏عَبْدَ اللَّهِ بْنَ عُمَرَ ‏ ‏يَقُولُ ‏ ‏رَأَيْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يُشِيرُ إِلَى الْمَشْرِقِ ‏ ‏أَوْ قَالَ إِنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يُشِيرُ إِلَى الْمَشْرِقِ ‏ ‏وَيَقُولُ ‏ ‏إِنَّ ‏ ‏الْفِتْنَةَ هَاهُنَا هَا إِنَّ الْفِتْنَةَ هَاهُنَا هَا إِنَّ الْفِتْنَةَ هَاهُنَا مِنْ حَيْثُ يُطْلِعُ الشَّيْطَانُ قَرْنَيْهِ ‏","","",""],[4739,4739,"","আমরা এক যুবকের কথা শুনেছি যে আমার বাবাকে এত ভয় পায় যে সে হবে সেই হবে যে হবে সেই হবে সেই হবে। সে-ই হবে যে , যে ব ্ যক ্ তি হবে , যে ব ্ যক ্ তি তার জন ্ যে উত ্ তম হবে । ঈশ্বর হয়তো শুনেছিলেন যে, তিনি তার জন্য প্রার্থনা করতে শুনেছেন এবং তাকে বিখ্যাত ও অবিশ্বাস্য বলে বলেছিলেন ।","‏ ‏حَدَّثَنَا ‏ ‏هِشَامُ بْنُ سَعْدٍ ‏ ‏حَدَّثَنَا ‏ ‏مُعَاوِيَةُ بْنُ سَلَّامٍ ‏ ‏سَمِعْتُ ‏ ‏يَحْيَى بْنَ أَبِي كَثِيرٍ ‏ ‏يُخْبِرُ أَنَّ ‏ ‏أَبَا سَلَمَةَ ‏ ‏أَخْبَرَهُ عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ عُمَرَ ‏ ‏أَنَّهُ سَمِعَهُ يَقُولُ ‏ ‏سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏الشَّهْرُ تِسْعٌ وَعِشْرُونَ ‏","","",""],[4740,4740,"","সে তার লোককে ফোন করতো আর আমরা বলেছিলাম যে তিনি আমাকে তার কাছে পাঠাতে বলেছেন।","‏ ‏حَدَّثَنَا ‏ ‏أَبُو أَحْمَدَ الزُّبَيْرِيُّ ‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏مَنْصُورٍ ‏ ‏عَنْ ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ سَعْدٍ ‏ ‏قَالَ ‏ ‏كُنْتُ مَعَ ‏ ‏ابْنِ عُمَرَ ‏ ‏فَكَانَ ‏ ‏يُصَلِّي عَلَى ‏ ‏رَاحِلَتِهِ ‏ ‏هَاهُنَا وَهَاهُنَا فَقُلْتُ لَهُ فَقَالَ هَكَذَا رَأَيْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَفْعَلُ ‏","","",""],[4741,4741,"","আমরা ঈশ্বরের প্রতি ভালবাসাকে এমন একটা ছেলের জন্য ভালো করার স্বপ্নের কথা বলেছি যে আমার জন্য ঈশ্বরের কাছে এসেছে। পাথরের তিনটি পাথর পাথর পাথর পাথরের উপর দিয়ে হেঁটে চলে গেছে।","‏ ‏حَدَّثَنَا ‏ ‏زَيْدُ بْنُ الْحُبَابِ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ ‏ ‏عَنْ ‏ ‏نَافِعٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏رَمَلَ ‏ ‏ثَلَاثًا مِنْ الْحَجَرِ إِلَى الْحَجَرِ وَمَشَى أَرْبَعًا ‏","","",""],[4742,4742,"","আমরা প্রেম দুই দিনের মধ্যে একটা ছেলের জন্য একটা অনুগ্রহের কথা বলেছি যে এই ছেলে এমন হতে চায় যে সে সেই লোক যে কিনা... যে ব ্ যক ্ তি উপুড় হয়ে পড়েছে , সেই সফলকাম হয় । সে তার ইফকে হত্যা করেছে, কিন্তু বলতে পারে না সে ঘুমিয়ে পড়েছে আর তার মূল্যও কমেছে ভোজের সাথে সাথে চলে গেছে।","‏ ‏حَدَّثَنَا ‏ ‏زَيْدُ بْنُ الْحُبَابِ ‏ ‏حَدَّثَنِي ‏ ‏أُسَامَةُ بْنُ زَيْدٍ ‏ ‏حَدَّثَنِي ‏ ‏نَافِعٌ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَمَّا رَجَعَ مِنْ ‏ ‏أُحُدٍ ‏ ‏فَجَعَلَتْ نِسَاءُ ‏ ‏الْأَنْصَارِ ‏ ‏يَبْكِينَ عَلَى مَنْ قُتِلَ مِنْ أَزْوَاجِهِنَّ قَالَ فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَلَكِنْ ‏ ‏حَمْزَةُ ‏ ‏لَا ‏ ‏بَوَاكِيَ لَهُ قَالَ ثُمَّ نَامَ فَاسْتَنْبَهَ وَهُنَّ يَبْكِينَ قَالَ فَهُنَّ الْيَوْمَ إِذًا يَبْكِينَ يَنْدُبْنَ ‏ ‏بِحَمْزَةَ ‏","","",""],[4743,4743,"","আমরা চেষ্টা করেছি আমাদের সর্বোচ্চ ঈশ্বর সূর্য দিয়ে সাঁতার কেটে সূর্য পর্যন্ত আমাকে সাঁতার কাটতে। তাদের সাথে যারা ছিল তাদের কাছে যাও এবং তারা তাদের নিলাম করছে এবং বলছে যে তাদের সময়মতো তাদের এই কাজ করতে হবে।","‏ ‏حَدَّثَنَا ‏ ‏عَتَّابٌ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ ‏ ‏وَعَلِيُّ بْنُ إِسْحَاقَ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏عَبْدُ اللَّهِ ‏ ‏أَخْبَرَنَا ‏ ‏يُونُسُ ‏ ‏عَنِ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنْ ‏ ‏حَمْزَةَ بْنِ عَبْدِ اللَّهِ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِذَا أَرَادَ اللَّهُ بِقَوْمٍ عَذَابًا أَصَابَ الْعَذَابُ مَنْ كَانَ فِيهِمْ ثُمَّ بُعِثُوا عَلَى أَعْمَالِهِمْ ‏ ‏وَقَالَ ‏ ‏عَلِيٌّ ‏ ‏فِي حَدِيثِهِ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏حَمْزَةُ بْنُ عَبْدِ اللَّهِ بْنِ عُمَرَ ‏ ‏أَنَّهُ سَمِعَ ‏ ‏ابْنَ عُمَرَ ‏ ‏يَقُولُهُ ‏","","",""],[4744,4744,"","আমি যা করতে যাচ্ছি, সেই সুন্দর ছেলেকে নিয়ে কথা বলছিলাম। কল্পনা করুন ।","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الْوَهَّابِ بْنُ عَبْدِ الْمَجِيدِ الثَّقَفِيُّ ‏ ‏عَنْ ‏ ‏أَيُّوبَ ‏ ‏عَنْ ‏ ‏نَافِعٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏قَالَ ‏ ‏مَا أَتَيْتُ عَلَى الرُّكْنِ مُنْذُ رَأَيْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَمْسَحُهُ فِي ‏ ‏شِدَّةٍ ‏ ‏وَلَا رَخَاءٍ إِلَّا مَسَحْتُهُ ‏","","",""],[4745,4745,"","আমরা কথা বলেছিলাম যে কোন ছেলের বোন হতে পারে যে রাতের বেলায় প্রার্থনা করতে হতো দু'বার, তাই সে একবার বিস্ফোরণকে ভয় পেয়েছিল।","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الْأَعْلَى بْنُ عَبْدِ الْأَعْلَى ‏ ‏عَنْ ‏ ‏خَالِدٍ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ شَقِيقٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏صَلَاةُ اللَّيْلِ مَثْنَى مَثْنَى فَإِذَا خَشِيتَ الْفَجْرَ ‏ ‏فَأَوْتِرْ ‏ ‏بِوَاحِدَةٍ ‏","","",""],[4746,4746,"","ঈশ্বরের প্রতিজ্ঞার প্রতিজ্ঞায় লোকেদের দেখেছে এমন একজন ছেলে তারা এটা বিক্রি করে যাতে তারা তা করতে পারে ।","‏ ‏حَدَّثَنَا ‏ ‏الضَّحَّاكُ بْنُ مَخْلَدٍ أَبُو عَاصِمٍ ‏ ‏عَنِ ‏ ‏ابْنِ جُرَيْجٍ ‏ ‏أَخْبَرَنِي ‏ ‏ابْنُ شِهَابٍ ‏ ‏عَنْ ‏ ‏حَدِيثِ ‏ ‏سَالِمِ بْنِ عَبْدِ اللَّهِ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏قَالَ ‏ ‏رَأَيْتُ النَّاسَ فِي عَهْدِ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يُضْرَبُونَ إِذَا ابْتَاعُوا الطَّعَامَ ‏ ‏جُزَافًا ‏ ‏أَنْ يَبِيعُوهُ حَتَّى ‏ ‏يُؤْوُوهُ ‏ ‏إِلَى رِحَالِهِمْ ‏","","",""],[4747,4747,"","আমরা আমার বাবার ছেলের কথা বলেছি যে আমার বাবা পাপ করেছেন বলে ঈশ্বর কখনো তার বাবাকে বলেছিলেন যে তিনি ঈশ্বরের কাছে যাচ্ছেন আর তিনি হবেন। আত্মসমর্পণ করো, আমরা গ্রীষ্মের সময়ে বিশ্বাস করি না।","‏ ‏حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ خَالِدٍ ‏ ‏عَنِ ‏ ‏ابْنِ أَبِي ذِئْبٍ ‏ ‏وَيَزِيدُ ‏ ‏قَالَ أَنْبَأَنَا ‏ ‏ابْنُ أَبِي ذِئْبٍ ‏ ‏عَنِ ‏ ‏الْحَارِثِ بْنِ عَبْدِ الرَّحْمَنِ ‏ ‏عَنْ ‏ ‏سَالِمِ بْنِ عَبْدِ اللَّهِ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏قَالَ ‏ ‏إِنْ كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَيَأْمُرُنَا بِالتَّخْفِيفِ وَإِنْ كَانَ لَيَؤُمُّنَا ‏ ‏بِالصَّافَّاتِ ‏ ‏قَالَ ‏ ‏يَزِيدُ ‏ ‏فِي الصُّبْحِ ‏","","",""],[4748,4748,"","আমরা একদিন কথা বলেছিলাম, আমার বাবার কথা বলছি, আমরা আমার বাবার সাথে কথা বলেছি, বেঁচে যাওয়া লোকটির ছেলে, লর্ডের কাছে প্রার্থনা করলো, যদি আপনাকে কবর দিতে বলা হত ঈশ্বর ক্ষমা করুন, তিনি আত্মসমর্পণ করেছেন","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الْوَاحِدِ يَعْنِي الْحَدَّادَ ‏ ‏حَدَّثَنَا ‏ ‏هَمَّامٌ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏عَنْ ‏ ‏أَبِي الصِّدِّيقِ النَّاجِيِّ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏إِذَا وَضَعْتُمْ مَوْتَاكُمْ فِي الْقُبُورِ فَقُولُوا بِسْمِ اللَّهِ وَعَلَى مِلَّةِ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏","","",""],[4749,4749,"","আমরা একটা নির্দিষ্ট ছেলের ব্যাপারে বলতে চেষ্টা করেছি যে তার চাচা আমার ভালো প্রেমিক, আমি হয়তো ঈশ্বরের চোখে দেখেছি, আর আমি কখনোই স্বপ্নেও ভাবিনি যে সাধু মারা গেছে।","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ ‏ ‏أَخْبَرَنَا ‏ ‏يَحْيَى ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ يَحْيَى ‏ ‏أَنَّ ‏ ‏عَمَّهُ ‏ ‏وَاسِعَ بْنَ حَبَّانَ ‏ ‏أَخْبَرَهُ أَنَّهُ سَمِعَ ‏ ‏ابْنَ عُمَرَ ‏ ‏قَالَ ‏ ‏لَقَدْ ظَهَرْتُ ذَاتَ يَوْمٍ عَلَى ظَهْرِ بَيْتِنَا فَرَأَيْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَاعِدًا عَلَى ‏ ‏لَبِنَتَيْنِ ‏ ‏مُسْتَقْبِلًا ‏ ‏بَيْتَ الْمَقْدِسِ ‏","","",""],[4750,4750,"","আমরা ওকে একটা ছেলে সম্পর্কে বলেছি, যাকে ঈশ্বর সৃষ্টি করেছেন। সূর্যাস্ত আর নদী আজ রাতে প্রার্থনা করছে।","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ ‏ ‏أَخْبَرَنَا ‏ ‏هِشَامٌ ‏ ‏عَنْ ‏ ‏مُحَمَّدٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّهُ قَالَ ‏ ‏صَلَاةُ الْمَغْرِبِ ‏ ‏وِتْرُ ‏ ‏النَّهَارِ ‏ ‏فَأَوْتِرُوا ‏ ‏صَلَاةَ اللَّيْلِ ‏","","",""],[4751,4751,"","আমরা রাজা হওয়ার ব্যাপারে কথা বলেছি... ...ঈশ্বরের জীবন নিয়ে ক্লাস পরিবর্তনের মাধ্যমে, একটি জীবনী-জীবনের মধ্য দিয়ে যায়, আমি যা বলেছি তা কখনো শেষ হয়নি. ঈশ্বর তাঁর জন্য প্রার্থনা করেন এবং তিনি আপনার প্রস্থান.","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ ‏ ‏عَنْ ‏ ‏حَجَّاجٍ ‏ ‏عَنْ ‏ ‏عَبْدِ الْمَلِكِ بْنِ الْمُغِيرَةِ الطَّائِفِيِّ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ الْمِقْدَامِ ‏ ‏قَالَ ‏ ‏رَأَيْتُ ‏ ‏ابْنَ عُمَرَ ‏ ‏يَمْشِي بَيْنَ ‏ ‏الصَّفَا ‏ ‏وَالْمَرْوَةِ ‏ ‏فَقُلْتُ لَهُ ‏ ‏أَبَا عَبْدِ الرَّحْمَنِ ‏ ‏مَا لَكَ لَا ‏ ‏تَرْمُلُ ‏ ‏فَقَالَ قَدْ ‏ ‏رَمَلَ ‏ ‏رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَتَرَكَ ‏","","",""],[4752,4752,"","আমরা আমাদের চেয়ে ভালো বলতে চেষ্টা করেছি মাত্র দু’বার চেয়ে, ঈশ্বর যখন আমার কাছে প্রার্থনা করেছিলেন, তিনি বলেছিলেন তুমি কখনো আমার জন্য প্রার্থনা করোনি।","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ ‏ ‏أَخْبَرَنَا ‏ ‏حُسَيْنُ بْنُ ذَكْوَانَ ‏ ‏عَنْ ‏ ‏عَمْرِو بْنِ شُعَيْبٍ ‏ ‏حَدَّثَنِي ‏ ‏سُلَيْمَانُ ‏ ‏مَوْلَى ‏ ‏مَيْمُونَةَ ‏ ‏سَمِعْتُ ‏ ‏عَبْدَ اللَّهِ بْنَ عُمَرَ ‏ ‏قَالَ ‏ ‏سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏لَا تُصَلُّوا صَلَاةً فِي يَوْمٍ مَرَّتَيْنِ ‏","","",""],[4753,4753,"","আমরা আমাদের বলতে চাই যে জাদু হচ্ছে সূর্য শোনার জন্য। সে বলল, আমি তার সাথে ঈশ্বরের প্রার্থনার বাল্ব পেয়েছি। সে বলেছে, ঈশ্বর তাকে যে খারাপ কিছু দিতে বলেছেন, তার কাছে থাকতে হবে। ঐ মহিমা আর মাথামোটা নিয়ে।","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ ‏ ‏أَخْبَرَنَا ‏ ‏عَبْدُ الْخَالِقِ بْنُ سَلَمَةَ الشَّيْبَانِيُّ ‏ ‏سَمِعْتُ ‏ ‏سَعِيدَ بْنَ الْمُسَيَّبِ ‏ ‏سَمِعْتُ ‏ ‏عَبْدَ اللَّهِ بْنَ عُمَرَ ‏ ‏يَقُولُ ‏ ‏كُنْتُ عِنْدَ مِنْبَرِ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قُدُومَ ‏ ‏وَفْدِ عَبْدِ الْقَيْسِ ‏ ‏مَعَ ‏ ‏الْأَشَجِّ ‏ ‏فَسَأَلُوا رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَنْ الْأَشْرِبَةِ ‏ ‏فَنَهَاهُمْ عَنْ ‏ ‏الْحَنْتَمِ ‏ ‏وَالدُّبَّاءِ ‏ ‏وَالنَّقِيرِ ‏","","",""],[4754,4754,"","আমরা জন্ম নিয়ে কথা বলেছি। আমি একবার এবং সবার জন্য করতে পারবো। আমি ঈশ্বরের কাছে প্রার্থনা করব। আমি এটা করবো। যখন তিনি এগিয়ে এলেন, তখন আমি তাঁর সাথে কথা বলব, কাকে তার সাথে যোগাযোগ করতে হবে না। সে কোন সমাধান করেনি।","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ ‏ ‏أَخْبَرَنَا ‏ ‏حُمَيْدٌ ‏ ‏عَنْ ‏ ‏بَكْرٍ ‏ ‏قَالَ ذَكَرْتُ ‏ ‏لِابْنِ عُمَرَ ‏ ‏أَنَّ ‏ ‏أَنَسًا ‏ ‏حَدَّثَنَا أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَهَلَّ ‏ ‏بِعُمْرَةٍ وَحَجٍّ فَقَالَ ‏ ‏وَهِلَ ‏ ‏أَنَسٌ ‏ ‏إِنَّمَا ‏ ‏أَهَلَّ ‏ ‏رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بِالْحَجِّ وَأَهْلَلْنَا مَعَهُ فَلَمَّا قَدِمَ قَالَ مَنْ لَمْ يَكُنْ مَعَهُ ‏ ‏هَدْيٌ ‏ ‏فَلْيَجْعَلْهَا عُمْرَةً وَكَانَ مَعَ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏هَدْيٌ ‏ ‏فَلَمْ ‏ ‏يَحِلَّ ‏","","",""],[4755,4755,"","বাবা তার চেয়ে ভাল কিছু পাওয়ার চেষ্টা করেছিলেন ।","‏ ‏حَدَّثَنَا ‏ ‏أَبُو مُعَاوِيَةَ ‏ ‏حَدَّثَنَا ‏ ‏عُبَيْدُ اللَّهِ ‏ ‏عَنْ ‏ ‏نَافِعٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏قَالَ ‏ ‏أَرْبَعًا تَلَقَّفْتُهُنَّ مِنْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَبَّيْكَ اللَّهُمَّ لَبَّيْكَ لَبَّيْكَ لَا شَرِيكَ لَكَ لَبَّيْكَ إِنَّ الْحَمْدَ وَالنِّعْمَةَ لَكَ وَالْمُلْكَ لَا شَرِيكَ لَكَ ‏","","",""],[4756,4756,"","বাবা তার আবেগ নিয়ে তর্ক করার চেষ্টা করে।","‏ ‏حَدَّثَنَا ‏ ‏أَبُو مُعَاوِيَةَ ‏ ‏حَدَّثَنَا ‏ ‏حَجَّاجٌ ‏ ‏عَنْ ‏ ‏عَطِيَّةَ الْعَوْفِيِّ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏قَالَ ‏ ‏نَهَى رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنْ تُبَاعَ الثَّمَرَةُ حَتَّى يَبْدُوَ صَلَاحُهَا قَالَ قَالُوا يَا رَسُولَ اللَّهِ مَا صَلَاحُهَا قَالَ إِذَا ذَهَبَتْ ‏ ‏عَاهَتُهَا ‏ ‏وَخَلَصَ ‏ ‏طَيِّبُهَا ‏","","",""],[4757,4757,"","আমরা বাবা কথা বলেছিলাম যে ঈশ্বরের কাছে প্রার্থনা করতে হবে, যে কিনা ঈশ্বরের কাছে পাঠানো হয়েছে।","‏ ‏حَدَّثَنَا ‏ ‏أَبُو مُعَاوِيَةَ ‏ ‏حَدَّثَنَا ‏ ‏عُبَيْدُ اللَّهِ ‏ ‏عَنْ ‏ ‏نَافِعٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَسْهَمَ ‏ ‏لِلرَّجُلِ وَفَرَسِهِ ثَلَاثَةَ ‏ ‏أَسْهُمٍ ‏ ‏سَهْمًا ‏ ‏لَهُ ‏ ‏وَسَهْمَيْنِ ‏ ‏لِفَرَسِهِ ‏","","",""],[4758,4758,"","বাবা যখন সভাগুলোতে যেতে চেষ্টা করছিল, তখন আমরা বাবার সঙ্গে কথা বলেছিলাম ।","‏ ‏حَدَّثَنَا ‏ ‏أَبُو مُعَاوِيَةَ ‏ ‏حَدَّثَنَا ‏ ‏الْأَعْمَشُ ‏ ‏عَنْ ‏ ‏مُجَاهِدٍ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ عُمَرَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِنِّي لَأَعْرِفُ شَجَرَةً بَرَكَتُهَا كَالرَّجُلِ الْمُسْلِمِ النَّخْلَةُ ‏","","",""],[4759,4759,"","আমরা ঈশ্বরের ছেলের কথা বলেছিলাম, আমার ছেলের সাথে আমাকে সাহায্য করার চেষ্টা করছিল। সে যখন তার ছেলে তাকে যা বলেছে, সে সেটা করে যেতে পারে। তারা আপনাকে ভিক্ষা বলেছে.","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ إِدْرِيسَ ‏ ‏عَنْ ‏ ‏عَبْدِ الْمَلِكِ يَعْنِي ابْنَ أَبِي سُلَيْمَانَ ‏ ‏عَنْ ‏ ‏سَعِيدِ بْنِ جُبَيْرٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏يُصَلِّي حَيْثُمَا تَوَجَّهَتْ بِهِ رَاحِلَتُهُ وَقَدْ رَأَيْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَفْعَلُ ذَلِكَ وَيَتَأَوَّلُ عَلَيْهِ ‏ { ‏وَحَيْثُ مَا كُنْتُمْ ‏ ‏فَوَلُّوا ‏ ‏وُجُوهَكُمْ ‏}","","",""],[4760,4760,"","কিন্তু আমাকে আমার কিছু লাশ বিক্রি করতে হবে বলে বলতে হবে, \"ঈশ্বর, তুমি অদ্ভুত ছিলে অথবা শ্বাস নিতে ফিরে যেতে।\" কিন্তু আমি বলেছিলাম, \"ঈশ্বর, তুমি অদ্ভুত ছিলে অথবা তুমি আমার শ্বাস নিতে চাও।\" কিন্তু আমি আমার বাবাকে জিজ্ঞাসা করলাম, আমি আমার কাছে একটা জিনিস বিক্রি করতে চাই। কিন্তু আমি জানি, আমি জানি না যে, আমি আমার কিছু জিনিস বিক্রি করতে চাই। আমি জানি না যে আমি শুধু একটা জিনিস আছে। কিন্তু আমি কি জানি না। আমি কি, আমি তোমার কাছে এটা একটা অদ্ভুত জিনিস আছে? কিন্তু আমি কি জানি? আমি জানি না? আমি জানি না। আমি জানি না, আমি জানি না, আমি কি করি, আমি জানি না। আমি জানি না, আমি জানি না, আমি এটা একটা ছোট। আমি যদি আমার বাবা আমাকে এটা করতে পারি, আমি এটা করতে হবে। আমি এটা একটা জিনিস। কিন্তু আমি কি করবো? আমি কি করবো?","‏ ‏حَدَّثَنَا ‏ ‏أَبُو مُعَاوِيَةَ ‏ ‏حَدَّثَنَا ‏ ‏لَيْثٌ ‏ ‏عَنْ ‏ ‏مُجَاهِدٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏قَالَ ‏ ‏أَخَذَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بِثَوْبِي ‏ ‏أَوْ بِبَعْضِ جَسَدِي ‏ ‏وَقَالَ ‏ ‏عَبْدَ اللَّهِ ‏ ‏كُنْ كَأَنَّكَ غَرِيبٌ أَوْ عَابِرُ سَبِيلٍ وَعُدَّ نَفْسَكَ مِنْ أَهْلِ الْقُبُورِ ‏","","",""],[4761,4761,"","আমরা বাবা কথা বলেছিলাম যে ঈশ্বর এটা করতে চেষ্টা করছেন আর তার কোন অবকাশ থাকবে না আর ব্যর্থ হবে না। খেলাটা খুব বেশি হবে না, আর ক্ষমা করা যাবে না।","‏ ‏حَدَّثَنَا ‏ ‏أَبُو مُعَاوِيَةَ ‏ ‏حَدَّثَنَا ‏ ‏عُبَيْدُ اللَّهِ ‏ ‏عَنْ ‏ ‏نَافِعٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَا يَلْبَسُ الْمُحْرِمُ الْبُرْنُسَ وَلَا الْقَمِيصَ وَلَا الْعِمَامَةَ وَلَا السَّرَاوِيلَ وَلَا الْخُفَّيْنِ إِلَّا أَنْ يَضْطَرَّ يَقْطَعُهُ مِنْ عِنْدِ الْكَعْبَيْنِ وَلَا يَلْبَسُ ثَوْبًا مَسَّهُ ‏ ‏الْوَرْسُ ‏ ‏وَلَا ‏ ‏الزَّعْفَرَانُ ‏ ‏إِلَّا أَنْ يَكُونَ غَسِيلًا ‏","","",""],[4762,4762,"","আমরা আপনার টাকা নিয়ে কথা বলেছি মানে একটা ছেলে যে কিনা ঈশ্বরের কাজে নিয়োজিত, অফিসারদের কাছে অনুরোধ করে।","‏ ‏حَدَّثَنَا ‏ ‏أَبُو مُعَاوِيَةَ ‏ ‏عَنْ ‏ ‏مَالِكٍ يَعْنِي ابْنَ مِغْوَلٍ ‏ ‏عَنْ ‏ ‏نَافِعٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏سُئِلَ عَنْ الضَّبِّ فَقَالَ لَا آكُلُهُ وَلَا ‏ ‏أَنْهَى عَنْهُ ‏","","",""],[4763,4763,"","আমরা আপনাদের টাকা নিয়ে কথা বলেছি মানে একটা ছেলের জন্য কাজ করা ছেলে যে বলেছে, সে বলেছে, সে আমাদের সাহায্য করছে।","‏ ‏حَدَّثَنَا ‏ ‏أَبُو مُعَاوِيَةَ ‏ ‏عَنْ ‏ ‏مَالِكٍ يَعْنِي ابْنَ مِغْوَلٍ ‏ ‏عَنْ ‏ ‏نَافِعٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَنْ أَتَى الْجُمُعَةَ فَلْيَغْتَسِلْ ‏","","",""],[4764,4764,"","আমরা আমাদের পরিবারের সঙ্গে বাইবেল অধ্যয়ন করতে শুরু করেছিলাম । আত্মসমর্পণ করলো সে বালি আর তোমাকে ছেড়ে চলে গেছে।","‏ ‏حَدَّثَنَا ‏ ‏أَبُو مُعَاوِيَةَ ‏ ‏حَدَّثَنَا ‏ ‏حَجَّاجٌ ‏ ‏عَنْ ‏ ‏عَبْدِ الْمَلِكِ بْنِ الْمُغِيرَةِ الطَّائِفِيِّ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ مِقْدَامِ بْنِ وَرْدٍ ‏ ‏قَالَ ‏ ‏رَأَيْتُ ‏ ‏ابْنَ عُمَرَ ‏ ‏طَافَ بَيْنَ ‏ ‏الصَّفَا ‏ ‏وَالْمَرْوَةِ ‏ ‏فَلَمْ ‏ ‏يَرْمُلْ ‏ ‏فَقُلْتُ لِمَ تَفْعَلُ هَذَا قَالَ فَقَالَ نَعَمْ كُلًّا قَدْ ‏ ‏رَأَيْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَعَلَ ‏ ‏رَمَلَ ‏ ‏وَتَرَكَ ‏","","",""],[4765,4765,"","আমরা আমার বাবা তোমার কাছে জন্ম দিয়েছি একটি ছেলে গান গেয়ে, ঈশ্বর এটা উদ্ধার করতে হবে এবং আপনি প্রচেষ্টা ছেড়ে আপনার ঘাড়ের উপর যেতে হবে, আপনি আপনার গলায় আমার কাছে ঈশ্বরের ফিরে আসার জন্য তোমাকে শাস্তিও দিতে হবে না।","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ عَبْدِ الْمَلِكِ بْنِ أَبِي غَنِيَّةَ ‏ ‏أَنْبَأَنَا ‏ ‏أَبُو جَنَابٍ ‏ ‏عَنْ ‏ ‏شَهْرِ بْنِ حَوْشَبٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏لَئِنْ تَرَكْتُمْ الْجِهَادَ وَأَخَذْتُمْ بِأَذْنَابِ الْبَقَرِ وَتَبَايَعْتُمْ ‏ ‏بِالْعِينَةِ ‏ ‏لَيُلْزِمَنَّكُمْ اللَّهُ مَذَلَّةً فِي رِقَابِكُمْ لَا تَنْفَكُّ عَنْكُمْ حَتَّى تَتُوبُوا إِلَى اللَّهِ وَتَرْجِعُوا عَلَى مَا كُنْتُمْ عَلَيْهِ ‏","","",""],[4766,4766,"","আমরা বাবার সৌভাগ্যের কথা বলেছি, ঈশ্বর তার কাছে প্রার্থনা করেছেন আর তিনি তার কাছে প্রার্থনা করবেন, যে বলবে আমি কে তার সাথে দেখা করব আর জিজ্ঞেস করবো","‏ ‏حَدَّثَنَا ‏ ‏عُمَرُ بْنُ عُبَيْدٍ الطَّنَافِسِيُّ ‏ ‏عَنْ ‏ ‏أَبِي إِسْحَاقَ يَعْنِي السُّبَيْعِيَّ ‏ ‏عَنْ ‏ ‏نَافِعٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏قَالَ ‏ ‏سَمِعْتُ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَلَى الْمِنْبَرِ يَقُولُ ‏ ‏مَنْ أَتَى الْجُمُعَةَ فَلْيَغْتَسِلْ ‏","","",""],[4767,4767,"","রাজা এর আগে আমাদের বলা হয়েছে যে সে কাপুরুষের ছেলেকে সাহায্য করবে। ঈশ্বরের সবচেয়ে ভালোটা হলো তাদের সাথে ভাঙ্গা। সে জানে কে জানে যে আমি এটা জিজ্ঞেস করবো কিনা। তাকে যেতে দেয়া অসম্ভবভাবে সে তার প্রয়োজন পূরণ করতে পারত না, তাই তাকে ঈশ্বরের কাছে পাঠানো হলে সে এটা করতে পারত। আমি মিথ্যা বলেছি আর তারপর তাকে বলে তাকে বলে দিলাম যে সে যেন তাকে গিয়ে বলে সে মিথ্যার জন্য মিথ্যার জন্য মিথ্যার অধিকার হারিয়ে গেছে। আমরা তাকে দেখতে চাই যে সে শিকারী নয়। আন্টির কাছে মিথ্যা বলতে হয়েছিল, দুই বন্ধু তাদের সাথে দেখা করতে শুরু করে।","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ ‏ ‏أَخْبَرَنَا ‏ ‏عَبْدُ الْمَلِكِ ‏ ‏سَمِعْتُ ‏ ‏سَعِيدَ بْنَ جُبَيْرٍ ‏ ‏قَالَ ‏ ‏سَأَلْتُ ‏ ‏ابْنَ عُمَرَ ‏ ‏فَقُلْتُ يَا ‏ ‏أَبَا عَبْدِ الرَّحْمَنِ ‏ ‏الْمُتَلَاعِنَيْنِ ‏ ‏يُفَرَّقُ بَيْنَهُمَا قَالَ سُبْحَانَ اللَّهِ نَعَمْ إِنَّ أَوَّلَ مَنْ سَأَلَ عَنْ ذَلِكَ فُلَانٌ قَالَ يَا رَسُولَ اللَّهِ أَرَأَيْتَ لَوْ أَنَّ أَحَدَنَا رَأَى امْرَأَتَهُ عَلَى ‏ ‏فَاحِشَةٍ ‏ ‏كَيْفَ يَصْنَعُ إِنْ سَكَتَ سَكَتَ عَلَى أَمْرٍ عَظِيمٍ وَإِنْ تَكَلَّمَ فَمِثْلُ ذَلِكَ فَسَكَتَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَلَمْ يُجِبْهُ فَقَامَ ‏ ‏لِحَاجَتِهِ ‏ ‏فَلَمَّا كَانَ بَعْدَ ذَلِكَ أَتَى رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ إِنَّ الَّذِي سَأَلْتُكَ عَنْهُ قَدْ ابْتُلِيتُ بِهِ قَالَ فَأَنْزَلَ اللَّهُ تَعَالَى هَذِهِ الْآيَاتِ فِي سُورَةِ ‏ ‏النُّورِ ‏ { ‏وَالَّذِينَ يَرْمُونَ أَزْوَاجَهُمْ ‏} ‏حَتَّى خَتَمَ الْآيَاتِ فَدَعَا الرَّجُلَ فَتَلَاهُنَّ عَلَيْهِ وَذَكَّرَهُ بِاللَّهِ تَعَالَى وَأَخْبَرَهُ أَنَّ عَذَابَ الدُّنْيَا أَهْوَنُ مِنْ عَذَابِ الْآخِرَةِ فَقَالَ وَالَّذِي بَعَثَكَ بِالْحَقِّ مَا كَذَبْتُ عَلَيْهَا ثُمَّ دَعَا الْمَرْأَةَ فَوَعَظَهَا وَذَكَّرَهَا وَأَخْبَرَهَا بِأَنَّ عَذَابَ الدُّنْيَا أَهْوَنُ مِنْ عَذَابِ الْآخِرَةِ فَقَالَتْ وَالَّذِي بَعَثَكَ بِالْحَقِّ إِنَّهُ لَكَاذِبٌ فَدَعَا الرَّجُلَ فَشَهِدَ أَرْبَعَ شَهَادَاتٍ بِاللَّهِ إِنَّهُ لَمِنْ الصَّادِقِينَ وَالْخَامِسَةَ أَنَّ لَعْنَةَ اللَّهِ عَلَيْهِ إِنْ كَانَ مِنْ الْكَاذِبِينَ ثُمَّ دَعَا بِالْمَرْأَةِ فَشَهِدَتْ أَرْبَعَ شَهَادَاتٍ بِاللَّهِ إِنَّهُ لَمِنْ الْكَاذِبِينَ وَالْخَامِسَةَ أَنَّ غَضَبَ اللَّهِ عَلَيْهَا إِنْ كَانَ مِنْ الصَّادِقِينَ ثُمَّ فَرَّقَ بَيْنَهُمَا ‏","","",""],[4768,4768,"","আমরা বাবার ছেলে একটা ছিনতাই শিক্ষককে নিয়ে কথা বলেছি, যে তার সর্বোচ্চ চেষ্টা করেছে, ক্যাপ্টেনকে ডেলিভারমেন্ট দেয়া হবে অথবা অন্য কাউকে বিক্রি করতে হবে যতক্ষণ না পর্যন্ত না সে অন্য চোরের কাছে যাবে। সূর্যাস্ত আর আলো আর আলো না উঠে সূর্য উদিত হওয়ার আগ পর্যন্ত","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ ‏ ‏أَخْبَرَنَا ‏ ‏ابْنُ أَبِي ذِئْبٍ ‏ ‏عَنْ ‏ ‏مُسْلِمٍ الْخَبَّاطِ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏قَالَ ‏ ‏نَهَى رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنْ ‏ ‏يُتَلَقَّى الرُّكْبَانُ ‏ ‏أَوْ يَبِيعَ حَاضِرٌ ‏ ‏لِبَادٍ ‏ ‏وَلَا يَخْطُبْ أَحَدُكُمْ عَلَى خِطْبَةِ أَخِيهِ حَتَّى يَنْكِحَ أَوْ يَدَعَ وَلَا صَلَاةَ بَعْدَ الْعَصْرِ حَتَّى تَغِيبَ الشَّمْسُ وَلَا بَعْدَ الصُّبْحِ حَتَّى تَرْتَفِعَ الشَّمْسُ أَوْ تُضْحِيَ ‏","","",""],[4769,4769,"","আমাদের বাবার ছেলেকে বলা হয়েছে যে, সে তার নিজের উপর দয়া করে চলে গেছে। সে তাকে থামাতে চেয়েছিল। \"ঈশ্বর তাকে আদেশ দিয়েছেন, \"ঈশ্বর তাকে আদেশ দিয়েছেন।\" পতন হোক। ঈশ্বর মুক্তি দিয়েছেন। আর আমি আপনার স্ত্রীর সাথে বিবাহ বিচ্ছেদ করেছি।","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ ‏ ‏أَخْبَرَنَا ‏ ‏ابْنُ أَبِي ذِئْبٍ ‏ ‏عَنِ ‏ ‏الْحَارِثِ بْنِ عَبْدِ الرَّحْمَنِ ‏ ‏عَنْ ‏ ‏حَمْزَةَ بْنِ عَبْدِ اللَّهِ بْنِ عُمَرَ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏قَالَ ‏ ‏كَانَتْ تَحْتِي امْرَأَةٌ أُحِبُّهَا وَكَانَ ‏ ‏عُمَرُ ‏ ‏يَكْرَهُهَا فَأَمَرَنِي أَنْ أُطَلِّقَهَا فَأَبَيْتُ فَأَتَى النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ يَا رَسُولَ اللَّهِ إِنَّ عِنْدَ ‏ ‏عَبْدِ اللَّهِ بْنِ عُمَرَ ‏ ‏امْرَأَةً كَرِهْتُهَا لَهُ فَأَمَرْتُهُ أَنْ يُطَلِّقَهَا فَأَبَى فَقَالَ لِي رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَا ‏ ‏عَبْدَ اللَّهِ ‏ ‏طَلِّقْ امْرَأَتَكَ فَطَلَّقْتُهَا ‏","","",""],[4770,4770,"","আমরা কয়েকটা পোরেশন বানাতে চেষ্টা করেছি, যে আমার বাবাকে বলেছিল যে অন্ধকার জীবনের পর একটা ছেলে চলে গেছে। আমি একটা ছেলেকে জিজ্ঞেস করবো যে, ঈশ্বর তার জন্য প্রার্থনা করেছেন আর আপনি যা জানেন, তার জন্য আমি তাকে জিজ্ঞাসা করছি, বাবাও হয়তো তাই করেছে। তুমি যা করতে যাচ্ছ তাতে কি লেখা আছে?","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ بْنُ هَارُونَ ‏ ‏قَالَ أَخْبَرَنِي ‏ ‏ابْنُ أَبِي ذِئْبٍ ‏ ‏عَنْ ‏ ‏عُثْمَانَ بْنِ عَبْدِ اللَّهِ بْنِ سُرَاقَةَ ‏ ‏قَالَ ‏ ‏كُنَّا فِي سَفَرٍ وَمَعَنَا ‏ ‏ابْنُ عُمَرَ ‏ ‏فَسَأَلْتُهُ فَقَالَ رَأَيْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَا يُسَبِّحُ فِي السَّفَرِ قَبْلَ الصَّلَاةِ وَلَا بَعْدَهَا قَالَ وَسَأَلْتُ ‏ ‏ابْنَ عُمَرَ ‏ ‏عَنْ بَيْعِ الثِّمَارِ فَقَالَ نَهَى رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَنْ بَيْعِ الثِّمَارِ حَتَّى تَذْهَبَ ‏ ‏الْعَاهَةُ ‏ ‏قُلْتُ ‏ ‏أَبَا عَبْدِ الرَّحْمَنِ ‏ ‏وَمَا تَذْهَبُ ‏ ‏الْعَاهَةُ ‏ ‏مَا ‏ ‏الْعَاهَةُ ‏ ‏قَالَ ‏ ‏طُلُوعُ ‏ ‏الثُّرَيَّا ‏","","",""],[4771,4771,"","আমরা একটা পাহাড়ের কথা বলেছি যার নাম একটা গণ্ডারের ছেলে, ঈশ্বর তাকে আমার আগেই বলেছে যে এই চুলটা বলার কোন ইচ্ছা নেই।","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏وَبَهْزٌ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏جَبَلَةَ ‏ ‏سَمِعْتُ ‏ ‏ابْنَ عُمَرَ ‏ ‏يُحَدِّثُ قَالَ ‏ ‏نَهَى رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَنْ ‏ ‏الْحَنْتَمَةِ ‏ ‏قُلْتُ لَهُ مَا ‏ ‏الْحَنْتَمَةُ ‏ ‏قَالَ ‏ ‏الْجَرَّةُ ‏","","",""],[4772,4772,"","আমরা আবেগ নিয়ে কথা বলেছি... ...আমরা একটা রীতিতে... ...যে কিনা একটা ছেলে ঈশ্বরকে বলে যে... ...ঈশ্বর তাকে... ...সন্দেহেছে... দেখো খোদা।","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏سَمِعْتُ ‏ ‏مُحَارِبَ بْنَ دِثَارٍ ‏ ‏سَمِعْتُ ‏ ‏ابْنَ عُمَرَ ‏ ‏يَقُولُ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَنْ ‏ ‏جَرَّ ‏ ‏ثَوْبَهُ مِنْ ‏ ‏مَخِيلَةٍ ‏ ‏لَمْ يَنْظُرْ اللَّهُ إِلَيْهِ يَوْمَ الْقِيَامَةِ ‏","","",""],[4773,4773,"","আমরা আবেগ নিয়ে বাপ্তাইজিত হয়েছি এবং বলার প্রয়োজন যে আমরা একটি মৃত ছেলের সাথে যুদ্ধ করেছি, ঈশ্বর তার জন্য প্রার্থনা করেছেন এবং তিনি ভাল্লুকের জন্য আত্মসমর্পণ করবেন এবং দুঃখ ও দুঃখ প্রকাশ করবেন সে ক্র্যাডেলের কথা শুনেছে, সে বলেছে, আমি তার আলোচনায় একবার ঐ পুতুলের কথা বলেছি।","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏وَالْحَجَّاجُ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏مُحَارِبِ بْنِ دِثَارٍ ‏ ‏سَمِعْتُ ‏ ‏ابْنَ عُمَرَ ‏ ‏يَقُولُ ‏ ‏نَهَى رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَنْ ‏ ‏الدُّبَّاءِ ‏ ‏وَالْحَنْتَمِ ‏ ‏وَالْمُزَفَّتِ ‏ ‏قَالَ ‏ ‏شُعْبَةُ ‏ ‏سَمِعْتُهُ غَيْرَ مَرَّةٍ ‏ ‏قَالَ ‏ ‏حَجَّاجٌ ‏ ‏وَقَالَ أَشُكُّ فِي ‏ ‏النَّقِيرِ ‏ ‏قَالَ ‏ ‏حَجَّاجٌ ‏ ‏فِي حَدِيثِهِ مَرَّاتٍ ‏","","",""],[4774,4774,"","আমরা আবেগ নিয়ে কথা বলেছি... ...আর আমার ভাইয়ের সাথে কথা বলেছি, যার ছেলে আছে, লর্ড তার জন্য প্রার্থনা করেছে, আর গত রাতের শেষ শিখা উপহার দিয়েছে।","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏وَحَجَّاجٌ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏أَبِي التَّيَّاحِ ‏ ‏عَنْ ‏ ‏أَبِي مِجْلَزٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏الْوَتْرُ ‏ ‏آخِرُ رَكْعَةٍ مِنْ اللَّيْلِ ‏","","",""],[4775,4775,"","আমরা আবেগ দিয়ে বাপ্তাইজিত হয়েছি... ...আমরা হাত হারানোর ব্যাপারে... ...যে ভাববাদীর কাছে প্রার্থনা করেছে, তার কাছে প্রার্থনা করেছে আর আশ্বস্ত করেছে যে আমরা মা মা কেঁদেছে, আর এভাবেই তিন বছরের এই মার্ক ধরে রেখেছে আর এখানে সে এখানে, তিন সেকেন্ড।","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنِ ‏ ‏الْأَسْوَدِ بْنِ قَيْسٍ ‏ ‏سَمِعْتُ ‏ ‏سَعِيدَ بْنَ عَمْرِو بْنِ سَعِيدٍ ‏ ‏يُحَدِّثُ أَنَّهُ سَمِعَ ‏ ‏ابْنَ عُمَرَ ‏ ‏يُحَدِّثُ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّهُ قَالَ ‏ ‏إِنَّا أُمَّةٌ أُمِّيَّةٌ لَا نَكْتُبُ وَلَا نَحْسُبُ الشَّهْرُ هَكَذَا وَهَكَذَا وَهَكَذَا وَعَقَدَ الْإِبْهَامَ فِي الثَّالِثَةِ وَالشَّهْرُ هَكَذَا وَهَكَذَا وَهَكَذَا ‏ ‏يَعْنِي تَمَامَ ثَلَاثِينَ ‏","","",""],[4776,4776,"","আমরা আমাদের ভালো নাম দিয়ে সাহায্য করার জন্য প্রবল আগ্রহ চেষ্টা করেছি, একজন লোক শহরের পথে যাত্রা করেছে, তাই এখন পর্যন্ত কিছু লোক চলে গেছে। তারা একটা ছেলেকে বলে দিয়েছে যে, একটা ছেলে ছিল। ঈশ্বরের কাছে প্রার্থনা করার সময় তিনি জিজ্ঞেস করেছিলেন কে প্রতিনিধিত্ব করবে","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنِ ‏ ‏الْمِنْهَالِ بْنِ عَمْرٍو ‏ ‏وَسَمِعْتُ ‏ ‏سَعِيدَ بْنَ جُبَيْرٍ ‏ ‏قَالَ ‏ ‏مَرَرْتُ مَعَ ‏ ‏ابْنِ عُمَرَ ‏ ‏عَلَى طَرِيقٍ مِنْ طُرُقِ ‏ ‏الْمَدِينَةِ ‏ ‏فَإِذَا فِتْيَةٌ قَدْ نَصَبُوا دَجَاجَةً يَرْمُونَهَا لَهُمْ كُلُّ خَاطِئَةٍ قَالَ فَغَضِبَ وَقَالَ مَنْ فَعَلَ هَذَا قَالَ فَتَفَرَّقُوا فَقَالَ ‏ ‏ابْنُ عُمَرَ ‏ ‏لَعَنَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَنْ ‏ ‏يُمَثِّلُ ‏ ‏بِالْحَيَوَانِ ‏","","",""],[4777,4777,"","আমরা একটা আবেগ নিয়ে কথা বলেছি যা আমরা আমার ছেলে হিসেবে একটা ভালো আর বাবার ভালোবাসা নিয়ে এসেছি, ঈশ্বর হয়ত বলেছেন যে আপনার ছেলে আমাকে আদেশ দিয়েছে তোমাকে রাখতে। অভিশাপ তোমাকে কিনবে না।","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏زَيْدٍ ‏ ‏وَأَبِي بَكْرٍ ‏ ‏ابْنَيْ ‏ ‏مُحَمَّدٍ ‏ ‏أَنَّهُمَا سَمِعَا ‏ ‏نَافِعًا ‏ ‏يُحَدِّثُ عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ عُمَرَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّهُ كَانَ يَقُولُ ‏ ‏لَبَّيْكَ اللَّهُمَّ لَبَّيْكَ لَبَّيْكَ لَا شَرِيكَ لَكَ لَبَّيْكَ إِنَّ الْحَمْدَ وَالنِّعْمَةَ لَكَ وَالْمُلْكَ لَا شَرِيكَ لَكَ ‏","","",""],[4778,4778,"","আমরা আবেগে বাপ্তাইজিত হয়েছি, একজন দাসের জন্য সংগ্রাম করেছি, যে কিনা বালতির শব্দ শুনেছে। সে তার ঋণ শোধ করেছে এবং সে তার হাত দিয়ে তার হাত তুলে দেবে। ঈশ্বর তার জন্য প্রার্থনা করেন এবং বলেন যে, তার কাঁধে সাত জনে খেতে হবে।","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏وَاقِدِ بْنِ مُحَمَّدِ بْنِ زَيْدٍ ‏ ‏أَنَّهُ سَمِعَ ‏ ‏نَافِعًا ‏ ‏قَالَ ‏ ‏رَأَى ‏ ‏ابْنُ عُمَرَ ‏ ‏مِسْكِينًا فَجَعَلَ ‏ ‏يُدْنِيهِ ‏ ‏وَيَضَعُ بَيْنَ يَدَيْهِ فَجَعَلَ يَأْكُلُ أَكْلًا كَثِيرًا فَقَالَ لِي لَا تُدْخِلَنَّ هَذَا عَلَيَّ فَإِنِّي سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏إِنَّ الْكَافِرَ يَأْكُلُ فِي سَبْعَةِ أَمْعَاءٍ ‏","","",""],[4779,4779,"","আমরা এমন আবেগ নিয়ে কথা বলেছি যা ঈশ্বরের প্রতি আনুগত্যের জন্য লড়াই করেছে। সে বলত, তুমি তাকে ছেড়ে দিতে পারবে না। সে বলল সে গুলি করে বলেছিল এবং আমি তোমাকে বলেছি ঈশ্বরকে তার নিজের শান্তি দিয়ে পাঠান এবং তিনি বলেন তিনি এই কথা বলবেন ।","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏سُلَيْمَانَ ‏ ‏عَنْ ‏ ‏مُجَاهِدٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّهُ قَالَ ‏ ‏لَا تَمْنَعُوا نِسَاءَكُمْ الْمَسَاجِدَ بِاللَّيْلِ ‏ ‏فَقَالَ ‏ ‏سَالِمٌ ‏ ‏أَوْ بَعْضُ بَنِيهِ ‏ ‏وَاللَّهِ لَا نَدَعُهُنَّ يَتَّخِذْنَهُ ‏ ‏دَغَلًا ‏ ‏قَالَ فَلَطَمَ صَدْرَهُ وَقَالَ ‏ ‏أُحَدِّثُكَ عَنْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَتَقُولُ هَذَا ‏","","",""],[4780,4780,"","আমরা আবেগ আর তর্কের সাথে কথা বলেছি যে পর্দার কাপড়ের উপর বসে শোনার চেষ্টা করেছি। ( যোহন ১৭: ৩) যে - লোকেরা ব্যর্থ হয় এবং তাদের মধ্যে বেশির ভাগ পাপী হয় তারা মনে করে না, তারা চলে যাওয়ার ভয় পায় না।","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏وَحَجَّاجٌ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏سَمِعْتُ ‏ ‏سُلَيْمَانَ الْأَعْمَشَ ‏ ‏وَقَالَ ‏ ‏حَجَّاجٌ ‏ ‏عَنِ ‏ ‏الْأَعْمَشِ ‏ ‏يُحَدِّثُ عَنْ ‏ ‏يَحْيَى بْنِ وَثَّابٍ ‏ ‏عَنْ ‏ ‏شَيْخٍ مِنْ ‏ ‏أَصْحَابِ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏وَأُرَاهُ ‏ ‏ابْنَ عُمَرَ ‏ ‏قَالَ ‏ ‏حَجَّاجٌ ‏ ‏قَالَ ‏ ‏شُعْبَةُ ‏ ‏قَالَ ‏ ‏سُلَيْمَانُ ‏ ‏وَهُوَ ‏ ‏ابْنُ عُمَرَ ‏ ‏يُحَدِّثُ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّهُ قَالَ ‏ ‏الْمُؤْمِنُ الَّذِي يُخَالِطُ النَّاسَ وَيَصْبِرُ عَلَى أَذَاهُمْ أَعْظَمُ أَجْرًا مِنْ الَّذِي لَا يُخَالِطُهُمْ وَلَا يَصْبِرُ عَلَى أَذَاهُمْ ‏ ‏قَالَ ‏ ‏حَجَّاجٌ ‏ ‏خَيْرٌ مِنْ الَّذِي لَا يُخَالِطُهُمْ ‏","","",""],[4781,4781,"","আমরা প্রভুর অন্ধকার নিয়ে প্রার্থনা করছি... ...তার জন্য প্রার্থনা করছি, আর যদি তুমি তিন বছর আগে তাকে আত্মসমর্পণ করবে, সে বলেছে সে বলছে খারাপ অনুভূতি হচ্ছে.","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏سُلَيْمَانَ ‏ ‏عَنْ ‏ ‏ذَكْوَانَ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ عُمَرَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِذَا كُنْتُمْ ثَلَاثَةً فَلَا يَتَنَاجَ اثْنَانِ دُونَ وَاحِدٍ ‏ ‏قَالَ ‏ ‏فَقُلْتُ ‏ ‏لِابْنِ عُمَرَ ‏ ‏فَإِذَا كَانُوا أَرْبَعَةً قَالَ ‏ ‏فَلَا بَأْسَ بِهِ ‏","","",""],[4782,4782,"","আমরা একটি আবেগ কথা বলেছি যে আমরা ঈশ্বরের সন্তানের শাসনের জন্য ভাল করেছি, ঈশ্বর তার জন্য প্রার্থনা করেছেন এবং আপনার প্রভু আপনার মঙ্গল করেছেন আপনার উপর আপনার ঈশ্বর আশীর্বাদ করেছেন, কিন্তু আপনার আত্মা আপনার জন্য নয়। ক্রেতা তোমার জন্য।","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏سَعِيدٌ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏عَنْ ‏ ‏بَكْرِ بْنِ عَبْدِ اللَّهِ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏أَنَّهُ قَالَ ‏ ‏تَلْبِيَةُ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَبَّيْكَ اللَّهُمَّ لَبَّيْكَ لَبَّيْكَ لَا شَرِيكَ لَكَ لَبَّيْكَ إِنَّ الْحَمْدَ وَالنِّعْمَةَ لَكَ وَالْمُلْكَ لَا شَرِيكَ لَكَ ‏","","",""],[4783,4783,"","আমরা আবেগ দিয়ে বাপ্তাইজিত হয়েছি আর ঈশ্বর হয়ত বলেছেন যে আমরা ভালোর জন্য ধার্মিকতার ধার্মিকদের উপর শাসন করতে পেরে খুশি ধার্মিকতার ধার্মিকতার ধার্মিকতার ধার্মিকতার ধার্মিকতার বিষয়ে চেষ্টা করা হবে । ঈশ্বর তার জন্য প্রার্থনা করেছেন এবং তাকে বলবেন যে, ঈশ্বর তাঁর কাছে প্রার্থনা করেছেন । তার ভুলের জন্য, সে তার মুখের সামনে তালাক দিয়েছে। একভাবে আমরা দেখলাম তুমি ধরে আছো কিনা।","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏وَعَبْدُ اللَّهِ بْنُ بَكْرٍ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏سَعِيدٌ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏عَنْ ‏ ‏يُونُسَ بْنِ جُبَيْرٍ ‏ ‏أَنَّهُ ‏ ‏سَأَلَ ‏ ‏ابْنَ عُمَرَ ‏ ‏عَنْ رَجُلٍ طَلَّقَ امْرَأَتَهُ وَهِيَ حَائِضٌ فَقَالَ أَتَعْرِفُ ‏ ‏عَبْدَ اللَّهِ بْنَ عُمَرَ ‏ ‏فَإِنَّهُ طَلَّقَ امْرَأَتَهُ حَائِضًا فَانْطَلَقَ ‏ ‏عُمَرُ ‏ ‏إِلَى رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَأَخْبَرَهُ بِذَلِكَ فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مُرْهُ فَلْيُرَاجِعْهَا ثُمَّ إِنْ بَدَا لَهُ طَلَاقُهَا طَلَّقَهَا فِي قُبُلِ عِدَّتِهَا ‏ ‏قَالَ ‏ ‏ابْنُ بَكْرٍ ‏ ‏أَوْ فِي قُبُلِ طُهْرِهَا ‏ ‏فَقُلْتُ ‏ ‏لِابْنِ عُمَرَ ‏ ‏أَيُحْسَبُ طَلَاقُهُ ذَلِكَ طَلَاقًا قَالَ ‏ ‏نَعَمْ أَرَأَيْتَ إِنْ عَجَزَ وَاسْتَحْمَقَ ‏","","",""],[4784,4784,"","আমরা একটা আবেগ নিয়ে কথা বলেছি যা তার নিজের সন্তানের বিচার করার রীতি নিয়ে এসেছে। ঈশ্বরের আছে, আমি তাকে খেতে দেবো না আর আমি আদেশ দিচ্ছি না। তার সাথে শেষ করে দাও।","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏يَعْلَى بْنِ حَكِيمٍ ‏ ‏عَنْ ‏ ‏نَافِعٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏أَنَّ نَبِيَّ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏لَا آكُلُهُ وَلَا آمُرُ بِهِ وَلَا أَنْهَى عَنْهُ ‏","","",""],[4785,4785,"","আমরা আবেগ নিয়ে কথা বলেছি, আমরা তাকে যে সময় দিয়েছি, তাকে যেতে বলেছি। ঈশ্বরের দশ বাজে কাজটি করতে হবে। ঠিক আছে.","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏مَعْمَرٌ ‏ ‏أَخْبَرَنَا ‏ ‏ابْنُ شِهَابٍ ‏ ‏وَعَبْدُ الْأَعْلَى ‏ ‏عَنْ ‏ ‏مَعْمَرٍ ‏ ‏عَنِ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنْ ‏ ‏سَالِمِ بْنِ عَبْدِ اللَّهِ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ عُمَرَ ‏ ‏قَالَ ‏ ‏أَسْلَمَ ‏ ‏غَيْلَانُ بْنُ سَلَمَةَ ‏ ‏وَتَحْتَهُ عَشْرُ نِسْوَةٍ فَقَالَ لَهُ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏خُذْ مِنْهُنَّ أَرْبَعًا ‏","","",""],[4786,4786,"","আমরা আবেগ নিয়ে কথা বলেছি যে তাদের সিঁড়ির ফুলকে বলার অভিজ্ঞতার মাধ্যমে তিনি ঈশ্বরের কাছে প্রার্থনা করবেন তিনি আপনাকে আপনার বাড়িতে আগুন দেবেন না ঘুমোও।","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏مَعْمَرٌ ‏ ‏أَخْبَرَنَا ‏ ‏الزُّهْرِيُّ ‏ ‏عَنْ ‏ ‏سَالِمِ بْنِ عَبْدِ اللَّهِ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَا تَتْرُكُوا النَّارَ فِي بُيُوتِكُمْ حِينَ تَنَامُونَ ‏","","",""],[4787,4787,"","আমরা আবেগ নিয়ে কথা বলেছি, তাদের অটুট ফুলকে বলার অভিজ্ঞতা নিয়ে। ওখানে।","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏مَعْمَرٌ ‏ ‏أَخْبَرَنَا ‏ ‏الزُّهْرِيُّ ‏ ‏عَنْ ‏ ‏سَالِمِ بْنِ عَبْدِ اللَّهِ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِنَّمَا النَّاسُ كَإِبِلِ الْمِائَةِ لَا يُوجَدُ فِيهَا ‏ ‏رَاحِلَةٌ ‏","","",""],[4788,4788,"","আমরা একটা কালো হার নিয়ে নাচতে চেষ্টা করেছি যেটা আমরা জিততে চেয়েছিলাম। সে বলছে আল্লাহ তার কাছে প্রার্থনা করছে এবং সে প্রতিবেশীর কাছে আত্মসমর্পণ করবে এবং সে ভালুক আর সে ভালুকের মত ঈশ্বর চলে গেছেন, গান।","‏ ‏حَدَّثَنَا ‏ ‏بَهْزٌ ‏ ‏وَمُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏قَالَ ‏ ‏بَهْزٌ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏عُقْبَةُ بْنُ حُرَيْثٍ ‏ ‏سَمِعْتُ ‏ ‏عَبْدَ اللَّهِ بْنَ عُمَرَ ‏ ‏قَالَ ‏ ‏نَهَى رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَنْ ‏ ‏الْجَرِّ ‏ ‏وَهِيَ ‏ ‏الدُّبَّاءُ ‏ ‏وَالْمُزَفَّتُ ‏ ‏وَقَالَ ‏ ‏انْتَبِذُوا ‏ ‏فِي ‏ ‏الْأَسْقِيَةِ ‏","","",""],[4789,4789,"","আমরা কিভাবে শুনেছি যে ঈশ্বর হয়তো শুনেছেন, তা শোনার জন্য আমরা জাদুটা করতে চেষ্টা করেছি। ঈশ্বর তাকে ছেড়ে দিয়েছেন এবং দশ বছর বয়সী একজনকে তার হৃদয়ে সমর্পণ করবেন, যে কিনা ধরা পড়বে। অন্ধকার.","‏ ‏حَدَّثَنَا ‏ ‏بَهْزٌ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏حَدَّثَنَا ‏ ‏عُقْبَةُ بْنُ حُرَيْثٍ ‏ ‏سَمِعْتُ ‏ ‏عَبْدَ اللَّهِ بْنَ عُمَرَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَنْ كَانَ مُلْتَمِسًا فَلْيَلْتَمِسْهَا فِي الْعَشْرِ فَإِنْ عَجَزَ أَوْ ضَعُفَ فَلَا يُغْلَبْ عَلَى السَّبْعِ الْبَوَاقِي ‏","","",""],[4790,4790,"","আমরা কিছু কৌশল করেছি, যাতে আমরা তার ছেলেকে চুমু দিতে পারি, রাতের প্রার্থনা একই রকম যে আপনি সকালে বা ঠাণ্ডার কথা চিন্তা করেন।","‏ ‏حَدَّثَنَا ‏ ‏بَهْزٌ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏أَخْبَرَنِي ‏ ‏عُقْبَةُ ‏ ‏سَمِعْتُ ‏ ‏ابْنَ عُمَرَ ‏ ‏يَقُولُ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏صَلَاةُ اللَّيْلِ مَثْنَى مَثْنَى فَإِنْ خَشِيتَ الصُّبْحَ فَأَوْتِرْ بِرَكْعَةٍ ‏ ‏قَالَ ‏ ‏قُلْتُ مَا مَثْنَى مَثْنَى قَالَ ‏ ‏رَكْعَتَانِ رَكْعَتَانِ ‏","","",""],[4791,4791,"","আমরা আবেগ নিয়ে কথা বলেছি যে বিচার সংগ্রামকে আমরা প্রাকৃতিক বলে মনে করি, কিন্তু সে জয়ের চেষ্টা করছে না, সে ফিরে এসেছে মাথা থেকে মাথা নিচু করে তাকে ভালবাসার জন্য হাঁটু গেড়ে বসে, আর সে তার বাবার মৃত্যু তার আত্মার কাছে পৌঁছে দিয়েছে।","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنِ ‏ ‏الْحَكَمِ ‏ ‏قَالَ ‏ ‏رَأَيْتُ ‏ ‏طَاوُسًا ‏ ‏حِينَ يَفْتَتِحُ الصَّلَاةَ يَرْفَعُ يَدَيْهِ وَحِينَ يَرْكَعُ وَحِينَ يَرْفَعُ رَأْسَهُ مِنْ الرُّكُوعِ ‏ ‏فَحَدَّثَنِي ‏ ‏رَجُلٌ ‏ ‏مِنْ أَصْحَابِهِ ‏ ‏أَنَّهُ يُحَدِّثُهُ عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏حَدَّثَنَاه ‏ ‏أَبُو النَّضْرِ ‏ ‏بِمَعْنَاهُ ‏","","",""],[4792,4792,"","আমরা আবেগ নিয়ে কথা বলেছি যে, আমরা ঈশ্বরের পুত্র দ্বারা সৃষ্ট একটি পুত্র যার কথা বলেছি তার নাম হল একটি পুত্র যার নাম আমার জন্য কথা বলা হয়েছে। ঈশ্বর তাকে আত্মসমর্পণ করতে বলেছেন যে লোকটি আমাকে কিভাবে বললেন। অনেক দিন সে তাদের একজনকে হারিয়েছে, অন্যজন।","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ دِينَارٍ ‏ ‏سَمِعْتُ ‏ ‏ابْنَ عُمَرَ ‏ ‏يُحَدِّثُ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّهُ قَالَ ‏ ‏إِذَا قَالَ الرَّجُلُ لِلرَّجُلِ يَا كَافِرُ فَقَدْ ‏ ‏بَاءَ ‏ ‏بِهِ أَحَدُهُمَا إِنْ كَانَ كَمَا قَالَ وَإِلَّا رَجَعَتْ عَلَى الْآخَرِ ‏","","",""],[4793,4793,"","আমরা আবেগ নিয়ে কথা বলেছি যে, আমরা ঈশ্বরের পুত্র দ্বারা ঐ ছেলের নাম পেয়েছি যার নাম ছিল মৃত অবস্থায় পাওয়া গেছে। সে বিক্রির জন্য প্রতারণা করেছে, আর সে উল্লেখ করেছে যে, ঈশ্বর আমাকে বলেছেন যে তাঁর ইচ্ছার সবচেয়ে ভালো দিক আছে, আমি হতাশ নই।","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ دِينَارٍ ‏ ‏سَمِعْتُ ‏ ‏ابْنَ عُمَرَ ‏ ‏قَالَ ‏ ‏كَانَ ‏ ‏رَجُلٌ ‏ ‏مِنْ ‏ ‏قُرَيْشٍ ‏ ‏يُغْبَنُ ‏ ‏فِي الْبَيْعِ فَذَكَرَ ذَلِكَ لِلنَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ لَهُ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قُلْ ‏ ‏لَا ‏ ‏خِلَابَةَ ‏","","",""],[4794,4794,"","আমরা আবেগ আর তর্কের সাথে কথা বলেছি... ...তার ছেলের সাথে আমরা একটা ছেলের সাথে বিয়ে দিয়েছি। আমি শুনেছি যে ভালোর ছেলের ছেলে হলে পরাজিত হবে যে - ছেলে মারা গিয়েছে, সে বলে যে, ঈশ্বর তাকে এই কথা বলতে বলার জন্য আপনাকে তৈরি করেছেন, তিনি তা বলার জন্য তিনি আপনাকে ব্যবহার করেছেন । তিনি বলেছিলেন যে, সেই ব্যক্তি কখনোই এই কথা বলতে পারবে না যে, শব্দই সঠিক ।","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏وَحَجَّاجٌ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏الْمَعْنَى ‏ ‏قَالَ ‏ ‏حَجَّاجٌ ‏ ‏عَنْ ‏ ‏جَبَلَةَ ‏ ‏وَقَالَ ‏ ‏ابْنُ جَعْفَرٍ ‏ ‏سَمِعْتُ ‏ ‏جَبَلَةَ ‏ ‏قَالَ ‏ ‏كَانَ ‏ ‏ابْنُ الزُّبَيْرِ ‏ ‏يَرْزُقُنَا التَّمْرَ قَالَ وَقَدْ كَانَ أَصَابَ النَّاسَ يَوْمَئِذٍ جَهْدٌ فَكُنَّا نَأْكُلُ فَيَمُرُّ عَلَيْنَا ‏ ‏ابْنُ عُمَرَ ‏ ‏وَنَحْنُ نَأْكُلُ فَيَقُولُ لَا ‏ ‏تُقَارِنُوا ‏ ‏فَإِنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏نَهَى عَنْ ‏ ‏الْإِقْرَانِ ‏ ‏قَالَ ‏ ‏حَجَّاجٌ ‏ ‏نَهَى عَنْ ‏ ‏الْقِرَانِ ‏ ‏إِلَّا أَنْ يَسْتَأْذِنَ الرَّجُلُ أَخَاهُ ‏ ‏وَقَالَ ‏ ‏شُعْبَةُ ‏ ‏لَا أُرَى هَذِهِ الْكَلِمَةَ فِي ‏ ‏الِاسْتِئْذَانِ إِلَّا مِنْ كَلَامِ ‏ ‏ابْنِ عُمَرَ ‏","","",""],[4795,4795,"","আমরা একটা পাহাড় সম্পর্কে কথা বলেছিলাম যার নাম বিদ্রোহের সন্তান, ঈশ্বর বলেছেন তিনি পরবর্তী জিনিস আগে কখনো দেখেননি।","‏ ‏حَدَّثَنَا ‏ ‏بَهْزٌ ‏ ‏وَمُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏جَبَلَةَ ‏ ‏سَمِعْتُ ‏ ‏ابْنَ عُمَرَ ‏ ‏يُحَدِّثُ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّهُ قَالَ ‏ ‏مَنْ جَرَّ ثَوْبًا مِنْ ثِيَابِهِ مِنْ ‏ ‏مَخِيلَةٍ ‏ ‏فَإِنَّ اللَّهَ تَعَالَى لَا يَنْظُرُ إِلَيْهِ يَوْمَ الْقِيَامَةِ ‏","","",""],[4796,4796,"","আমরা আবেগ-অনুভূতি বের করে একটা ডাইনি খুঁজতে চেষ্টা করেছি। একটি জীবন বলতে যে ভগবান তার কাছে প্রার্থনা করেছে আর তার ভাগ্যকে বলে দিবে। তার কথাবার্তার প্রতি আগ্রহ নিয়ে বাপ্তাইজিত হয়ে তিনি বলতে চেয়েছিলেন যে, এটা বিস্তৃত ও বাসা ।","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏وَبَهْزٌ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏جَبَلَةَ بْنِ سُحَيْمٍ ‏ ‏قَالَ ‏ ‏بَهْزٌ ‏ ‏أَخْبَرَنِي ‏ ‏قَالَ سَمِعْتُ ‏ ‏ابْنَ عُمَرَ ‏ ‏يَقُولُ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏الشَّهْرُ هَكَذَا وَطَبَّقَ بِأَصَابِعِهِ مَرَّتَيْنِ وَكَسَرَ فِي الثَّالِثَةِ الْإِبْهَامَ ‏ ‏قَالَ ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏فِي حَدِيثِهِ ‏ ‏يَعْنِي قَوْلَهُ تِسْعٌ وَعِشْرِينَ ‏","","",""],[4797,4797,"","আমরা ঈশ্বর ও তাঁর পুত্রের মধ্যে ভালবাসার যুদ্ধ নিয়ে প্রার্থনা করেছি, তিনি তার পথিকের সাথে কথা বলার জন্য আহ্বান জানান যে, ঈশ্বর তার জন্য প্রার্থনা করেছেন এবং তিনি তার জন্য প্রার্থনা করেছেন। তাকে টাকা দিয়ে দিবে.","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏خُبَيْبِ بْنِ عَبْدِ الرَّحْمَنِ ‏ ‏عَنْ ‏ ‏حَفْصِ بْنِ عَاصِمٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏أَنَّهُ كَانَ ‏ ‏يُصَلِّي حَيْثُ تَوَجَّهَتْ بِهِ رَاحِلَتُهُ قَالَ وَكَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَفْعَلُهُ ‏","","",""],[4798,4798,"","আমরা আবেগ দিয়ে বাপ্তাইজিত হয়েছি আমরা একটা শিয়ালের যুদ্ধ করেছি যার মানে ঈশ্বরের পুত্র, সে ঈশ্বরের প্রেরিতের সাথে বাইরে যায়, সে আমাকে কল করে, সে আমাকে কল করে তিনি যখন মারা যান, তখন তিনি দুই বছর ধরে মৃত্যুদণ্ড পান ।","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏خُبَيْبٍ يَعْنِي ابْنَ عَبْدِ الرَّحْمَنِ ‏ ‏عَنْ ‏ ‏حَفْصِ بْنِ عَاصِمٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏قَالَ ‏ ‏خَرَجْنَا مَعَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَكَانَ ‏ ‏يُصَلِّي صَلَاةَ ‏ ‏السَّفَرِ ‏ ‏يَعْنِي رَكْعَتَيْنِ ‏ ‏وَمَعَ ‏ ‏أَبِي بَكْرٍ ‏ ‏وَعُمَرَ ‏ ‏وَعُثْمَانَ ‏ ‏سِتَّ سِنِينَ مِنْ إِمْرَتِهِ ثُمَّ صَلَّى أَرْبَعًا ‏","","",""],[4799,4799,"","ঈশ্বর তাকে জিজ্ঞেস করেছেন এবং তিনি তাকেও ফোন করেছেন। সে না আসা পর্যন্ত তার বাবা-মা চলে যায়।","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏أَبِي فَرْوَةَ الْهَمْدَانِيِّ ‏ ‏سَمِعْتُ ‏ ‏عَوْنًا الْأَزْدِيَّ ‏ ‏قَالَ ‏ ‏كَانَ ‏ ‏عُمَرُ بْنُ عُبَيْدِ اللَّهِ بْنِ مَعْمَرٍ ‏ ‏أَمِيرًا عَلَى ‏ ‏فَارِسَ ‏ ‏فَكَتَبَ إِلَى ‏ ‏ابْنِ عُمَرَ ‏ ‏يَسْأَلُهُ عَنْ الصَّلَاةِ فَكَتَبَ ‏ ‏ابْنُ عُمَرَ ‏ ‏إِنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ ‏ ‏إِذَا خَرَجَ مِنْ أَهْلِهِ صَلَّى رَكْعَتَيْنِ حَتَّى يَرْجِعَ إِلَيْهِمْ ‏","","",""],[4800,4800,"","আমার ভালোবাসায় আমরা কথা বলেছি এবং আমাকে মুক্ত করে দিতে চাই। আমার মা বলেছে হঠাৎ করেই তার প্রার্থনা শুনে একটি ছেলে বললো যে কখনো তোমার প্রার্থনার অভিনয় করেনি এবং আল্লাহ্‌র সাথে কথা বলেছে। এমন কিছু করার জন্য এবং তা করার অধিকার আছে এমন একটা ছেলে, যাকে তার বাম হাত এবং হাত বাম হাতে রেখে চলে যেতে হবে।","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏وَحَجَّاجٌ ‏ ‏الْمَعْنَى ‏ ‏قَالَا حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏حَدَّثَنَا ‏ ‏مُسْلِمُ بْنُ أَبِي مَرْيَمَ ‏ ‏قَالَ ‏ ‏حَجَّاجٌ ‏ ‏مِنْ ‏ ‏بَنِي أُمَيَّةَ ‏ ‏قَالَ سَمِعْتُ ‏ ‏عَبْدَ الرَّحْمَنِ بْنَ عَلِيٍّ ‏ ‏قَالَ ‏ ‏حَجَّاجٌ ‏ ‏الْأُمَوِيَّ ‏ ‏قَالَ ‏ ‏سَمِعْتُ ‏ ‏ابْنَ عُمَرَ ‏ ‏وَرَأَى رَجُلًا يَعْبَثُ فِي صَلَاتِهِ فَقَالَ ‏ ‏ابْنُ عُمَرَ ‏ ‏لَا تَعْبَثْ فِي صَلَاتِكَ وَاصْنَعْ كَمَا كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَصْنَعُ ‏ ‏قَالَ ‏ ‏مُحَمَّدٌ ‏ ‏فَوَضَعَ ‏ ‏ابْنُ عُمَرَ ‏ ‏فَخِذَهُ الْيُمْنَى عَلَى الْيُسْرَى وَيَدَهُ الْيُسْرَى عَلَى رُكْبَتِهِ الْيُسْرَى وَوَضَعَ يَدَهُ الْيُمْنَى عَلَى الْيُمْنَى وَقَالَ بِإِصْبَعِهِ ‏","","",""]];
